(1, '{\"en\":\"Address\",\"ar\":null}', NULL, '16441', 'info@alnas-hospital.com', 'https://maps.app.goo.gl/G1Md6VQJxFjz1h2y7', 'https://www.facebook.com/alnashospitaleg/', 'https://www.linkedin.com/company/al-nas-hospital/', 'https://www.instagram.com/alnas.hospital/', 'https://www.youtube.com/channel/UCnSXy2gst2tgUJ_lm6h_15w', NULL, '2026-02-14 11:25:03', NULL);
INSERT INTO `courses` (`id`, `title`, `pic`, `course_category_id`, `course_type_id`, `duration`, `subject`, `location`, `format`, `ceus`, `overview`, `outcomes`, `requirements`, `fees`, `price`, `price_usd`, `max_applicants`, `enrolled_no`, `status`, `created_at`, `updated_at`, `order_column`) VALUES
(1, '{\"ar\":\"كورس عربى\",\"en\":\"Adult Cardiology Observership\"}', NULL, 1, 2, '{\"en\":\"1 month\",\"ar\":null}', '{\"en\":\"Cardiology\",\"ar\":null}', '{\"en\":\"https://maps.app.goo.gl/7cnUmLViWqiSYMZB7\",\"ar\":null}', '{\"en\":\"On-site\",\"ar\":null}', '{\"en\":\"12\",\"ar\":null}', '{\"en\":\"<p>The Adult Cardiology Observership Program at Al-Nas Hospital offers physicians the opportunity to gain structured exposure to advanced cardiovascular care in a high-volume tertiary cardiac center.</p><p>Observers will participate in daily clinical activities, multidisciplinary discussions, outpatient clinics, non-invasive and invasive cardiology services, and academic sessions under the supervision of experienced cardiology consultants.</p><p>This program is designed for international physicians, fellows, and residents seeking clinical insight into modern cardiology practice, advanced imaging, interventional procedures, and evidence-based patient management.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>By the end of the observership, participants will be able to:</p><p>• Understand the workflow of a tertiary adult cardiology department<br>• Observe diagnostic and therapeutic decision-making in complex cardiac cases<br>• Gain exposure to echocardiography interpretation and cardiac imaging pathways<br>• Understand indications and patient selection for cardiac catheterization and interventions<br>• Participate in multidisciplinary case discussions<br>• Recognize international standards in cardiovascular patient safety and quality care</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>Applicants must:</p><p>• Hold a recognized medical degree (MBBS or equivalent)<br>• Be currently enrolled in or have completed cardiology training (residents, fellows, or specialists)<br>• Submit a CV and statement of purpose<br>• Provide a valid passport copy (for non-Egyptians<br>• Submit a letter of good standing from their institution<br>• Provide proof of professional indemnity coverage (if applicable)</p><p>English proficiency is required.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>Program Fee:</p><p>Egyotians: 5000 LE</p><p>Non-Egyptians: 500 $</p><p>The fee includes:</p><p>• Access to clinical observership activities<br>• Participation in academic sessions<br>• Certificate of completion<br>• Access badge for designated clinical areas</p><p>Accommodation and travel expenses are not included.</p>\",\"ar\":\"<p></p>\"}', 5000, 500, 10, 5, 0, '2025-12-26 23:23:45', '2026-02-13 20:48:35', NULL),
(6, '{\"en\":\"NICU Nursing Course\",\"ar\":null}', NULL, 2, 5, '{\"en\":\"4 days\",\"ar\":null}', '{\"en\":\"Nursing Care\",\"ar\":null}', '{\"en\":\"https://maps.app.goo.gl/7cnUmLViWqiSYMZB7\",\"ar\":null}', '{\"en\":\"On-site\",\"ar\":null}', '{\"en\":\"2\",\"ar\":null}', '{\"en\":\"<p>The NICU Nursing Course at Al-Nas Hospital provides specialized training in neonatal cardiac and critical care nursing within a high-acuity neonatal intensive care environment.</p><p>This program is designed to enhance clinical competence in caring for critically ill neonates, including congenital heart disease cases, ventilated infants, and post-operative cardiac patients. Participants will engage in structured clinical observation, competency-based workshops, and multidisciplinary learning activities.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>By the end of the course, participants will be able to:</p><p>• Understand NICU workflow and patient safety protocols<br>• Recognize assessment principles in critically ill neonates<br>• Observe neonatal ventilator management and respiratory support strategies<br>• Understand medication safety in neonatal care<br>• Observe pre- and post-operative care for neonatal cardiac patients<br>• Understand infection prevention standards in NICU settings<br>• Participate in neonatal case discussions and multidisciplinary rounds</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>• Bachelor’s degree in Nursing<br>• Valid nursing license<br>• Minimum 1 year NICU or pediatric experience preferred<br>• Updated CV<br>• Letter of good standing<br>• English proficiency</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>Program Fee:</p><p>Egyptians: 2000 LE</p><p>Non- Egyptians: 200 $</p><p>The fee includes structured training access, academic sessions, and a certificate of completion.<br>Accommodation and travel expenses are not included.</p>\",\"ar\":\"<p></p>\"}', 2000, 200, 50, 27, 1, '2026-02-13 18:02:28', '2026-02-13 18:02:28', NULL),
(7, '{\"en\":\"Cardiovascular Perfusion Programa\",\"ar\":null}', NULL, 4, 2, '{\"en\":\"1 month\",\"ar\":null}', '{\"en\":\"Perfusion\",\"ar\":null}', '{\"en\":\"https://maps.app.goo.gl/7cnUmLViWqiSYMZB7\",\"ar\":null}', '{\"en\":\"On-site\",\"ar\":null}', '{\"en\":\"12\",\"ar\":null}', '{\"en\":\"<p>The Perfusion Observership Program offers specialized exposure to cardiovascular perfusion practice within a high-volume cardiothoracic surgery center.</p><p>Participants will observe cardiopulmonary bypass procedures, extracorporeal circulation management, ECMO support systems, and perfusion safety protocols under the supervision of experienced cardiac perfusionists and surgical teams.</p><p>This program is ideal for licensed perfusionists or trainees seeking advanced exposure to cardiac surgery support systems.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>Participants will:</p><p>• Observe cardiopulmonary bypass setup and management<br>• Understand ECMO circuit configuration and monitoring<br>• Gain exposure to perfusion safety and quality control protocols<br>• Understand anticoagulation management principles<br>• Observe intraoperative coordination with surgical and anesthesia teams<br>• Understand emergency response protocols in cardiac surgery</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>• Bachelor’s degree in medicin, nursing or relevant cardiovascular sciences<br>• Holds a valid fellowship in Perfusion<br>• Valid professional license (if applicable)<br>• CV submission<br>• Letter from employer or training institution<br>• English proficiency</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>Program Fee:<br>Egyptians: 3000 LE</p><p>Non-Egyptians: 300 $</p><p>Includes clinical observership access and certificate of completion.<br>Travel and accommodation are not included.</p>\",\"ar\":\"<p></p>\"}', 3000, 300, 5, NULL, 1, '2026-02-13 18:24:34', '2026-02-13 18:25:51', NULL),
(8, '{\"en\":\"Healthcare Leadership & Hospital Operations Program\",\"ar\":null}', NULL, 6, 5, '{\"en\":\"5 Days\",\"ar\":null}', '{\"en\":\"Leadership\",\"ar\":null}', '{\"en\":\"https://maps.app.goo.gl/7cnUmLViWqiSYMZB7\",\"ar\":null}', '{\"en\":\"On-site\",\"ar\":null}', '{\"en\":\"2\",\"ar\":null}', '{\"en\":\"<p>The Healthcare Leadership &amp; Hospital Operations Program is designed for healthcare administrators and department managers seeking structured exposure to hospital governance, quality management, operational strategy, and digital transformation in a tertiary cardiac hospital.</p><p>Participants will observe leadership meetings, quality rounds, and operational workflows.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>Participants will:</p><p>• Understand hospital governance structure<br>• Observe quality and patient safety frameworks<br>• Gain exposure to accreditation standards implementation<br>• Understand HR, training, and workforce development systems<br>• Observe digital transformation and healthcare IT workflows</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>• Bachelor’s degree in healthcare administration, management, or related field<br>• Minimum 1 year experience in healthcare setting<br>• CV submission<br>• Statement of purpose</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>Program Fee:</p><p>Egyptians: 5000 LE</p><p>Non-Egyptians: 200 $</p><p>Includes structured observation sessions and certificate of participation.</p>\",\"ar\":\"<p></p>\"}', 5000, 200, 10, 3, 1, '2026-02-13 19:07:00', '2026-02-13 19:07:00', NULL),
(9, '{\"en\":\"Occupational Safety in Healthcare\",\"ar\":null}', NULL, 7, 5, '{\"en\":\"5 Days\",\"ar\":null}', '{\"en\":\"Occupational Safety\",\"ar\":null}', '{\"en\":\"https://maps.app.goo.gl/7cnUmLViWqiSYMZB7\",\"ar\":null}', '{\"en\":\"On-site\",\"ar\":null}', '{\"en\":\"2\",\"ar\":null}', '{\"en\":\"<p>The Occupational Safety in Healthcare Course is designed to promote a safe working environment for support and operational staff within hospital settings.</p><p>This program focuses on workplace hazard prevention, risk assessment, injury prevention, and regulatory compliance to ensure the protection of healthcare workers and support personnel. It aligns with international occupational health and safety standards and hospital accreditation requirements.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>By the end of this course, participants will be able to:</p><p>• Identify workplace hazards in hospital environments<br>• Apply risk assessment and hazard control principles<br>• Implement proper use of Personal Protective Equipment (PPE)<br>• Understand fire safety and emergency evacuation procedures<br>• Apply safe manual handling and body mechanics techniques<br>• Recognize electrical, mechanical, and chemical safety risks<br>• Understand incident reporting and workplace injury documentation procedures<br>• Promote a culture of safety and compliance within operational teams</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>• Employment in healthcare operational or support services</p><p>        • Housekeeping staff<br>        • Engineering &amp; maintenance teams<br>        • Security personnel<br>        • Kitchen &amp; laundry staff<br>        • Transport &amp; logistics teams<br>        • Operational supervisors<br>• Basic literacy and ability to follow safety instructions</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<p>Program Fee:</p><p>Egyptians: 1000 LE</p><p>Non-Egyptians: 100 $</p><p>Includes structured training sessions, practical demonstrations, and certificate of completion.</p>\",\"ar\":\"<p></p>\"}', 1000, 100, 20, 14, 1, '2026-02-13 19:26:52', '2026-02-13 19:26:52', NULL);
INSERT INTO `course_applicants` (`id`, `course_id`, `name`, `email`, `mobile`, `institution`, `country`, `reference_no`, `amount`, `currency`, `course_dates`, `paid`, `notes`, `status`, `created_at`, `updated_at`) VALUES
