(19, '{\"ar\":\"خدمات المرضى الداخليين\",\"en\":\"Inpatient Services\"}', NULL, NULL, '{\"ar\":\"22\",\"en\":\"Al nas hospital\"}', '{\"en\":\"Why Choose Al Nas Hospital for Burn, Plastic & Reconstructive Surgery\",\"ar\":null}', '{\"en\":\"<p>The unit provides full-spectrum burn care, integrating medical, surgical, rehabilitative, and psychological support. Services extend from critical care management in the early stages to reconstructive surgery and long-term rehabilitation, ensuring patients receive interdisciplinary continuous care.</p>\",\"ar\":\"<p>4566</p>\"}', NULL, '[{\"uuid\":\"0158c9e1-e84f-43e9-875b-25f272adff38\",\"title\":{\"en\":\"Clinical Programs\",\"ar\":\"ww\"},\"content\":{\"en\":\"Discover our clinical programs delivering expert, patient-centered care.\",\"ar\":null}},{\"uuid\":\"a0ee469c-9eb6-40cb-9f97-82c39d5cd454\",\"title\":{\"en\":\"Departments, Umbrellas of Excellence & Centers\",\"ar\":\"ee\"},\"content\":{\"en\":\"Explore our specialties offering comprehensive care across multiple fields.\",\"ar\":null}},{\"uuid\":\"58ae3b88-3111-4fc6-8506-ae71eb4338a8\",\"title\":{\"en\":\"Outcomes\",\"ar\":\"dd\"},\"content\":{\"en\":\"Learn how our care transforms patient outcomes and quality of life.\",\"ar\":null}}]', '{\"en\":\"Al nas hospital\",\"ar\":null}', '{\"ar\":null}', '{\"en\":\"<p>Hana… her name tells a story of healing.<br>A journey that began at Al Nas Hospital, and today she is living her life in full health and happiness.</p>\",\"ar\":\"<p>هنا.. اسمها بيحكي قصة شفاء<br>رحلة بدأت في مستشفى الناس، واليوم بتعيش حياتها بكل صحة وسعادة.</p>\"}', NULL, '{\"en\":\"al nas hospital\",\"ar\":null}', '{\"en\":\" Al Nas Hospital Clinical Programs\",\"ar\":null}', '{\"en\":\"al nas hospital\",\"ar\":null}', '{\"en\":\"Departments\",\"ar\":null}', '{\"en\":\"<p>The unit provides full-spectrum burn care, integrating medical, surgical, rehabilitative, and psychological support. Services extend from critical care management in the early stages to reconstructive surgery and long-term rehabilitation, ensuring patients receive interdisciplinary continuous care.</p>\",\"ar\":\"<p></p>\"}', '[{\"0\":{\"title\":\"out 1\",\"content\":\"<p>Our department is equipped with advanced imaging technologies including 3D echocardiography, CT, and MRI, ensuring precise diagnostics, safer interventions, and improved outcomes.<\\/p><p>With renowned professors and consultants who bring international expertise, we excel in treating complex and high-risk cases such as chronic total occlusions, high-risk percutaneous interventions, and adult congenital heart disease.<\\/p><p>Care is delivered through a collaborative heart team approach that integrates cardiologists, surgeons, and imaging specialists, supported by extensive case experience, innovative non-surgical options such as TAVI and TAVR, and a strong commitment to minimally invasive procedures for faster recovery.<\\/p><p>As a teaching hospital, we are dedicated to academic excellence through fellowships, international collaborations, and continuous training.<\\/p><p>Our patient-centered model ensures accessible, lifelong care including specialized adult congenital programs, while maintaining the highest standards of quality, safety, and evidence-based practice through ongoing audits and performance reviews.<\\/p>\",\"embed\":null},\"1\":{\"title\":\"out 2\",\"content\":\"<p>Our department is equipped with advanced imaging technologies including 3D echocardiography, CT, and MRI, ensuring precise diagnostics, safer interventions, and improved outcomes.<\\/p><p>With renowned professors and consultants who bring international expertise, we excel in treating complex and high-risk cases such as chronic total occlusions, high-risk percutaneous interventions, and adult congenital heart disease.<\\/p><p>Care is delivered through a collaborative heart team approach that integrates cardiologists, surgeons, and imaging specialists, supported by extensive case experience, innovative non-surgical options such as TAVI and TAVR, and a strong commitment to minimally invasive procedures for faster recovery.<\\/p><p>As a teaching hospital, we are dedicated to academic excellence through fellowships, international collaborations, and continuous training.<\\/p><p>Our patient-centered model ensures accessible, lifelong care including specialized adult congenital programs, while maintaining the highest standards of quality, safety, and evidence-based practice through ongoing audits and performance reviews.<\\/p>\",\"embed\":null},\"content\":{\"en\":\"<p>Discover the medical specialties at Al Nas Hospital, where expert teams provide care across<\\/p>\",\"ar\":\"<p><\\/p>\"},\"embeds\":[{\"embed\":\"embed\"}],\"title\":{\"en\":\"Outcomes\",\"ar\":null}}]', '2025-12-24 08:31:48', '2026-02-11 14:28:31', NULL, 0, 0, 'https://www.youtube.com/watch?v=93Q0fFxd9ZI', '{\"ar\":null}', '{\"ar\":null}', '{\"ar\":null}', '{\"ar\":null}', NULL);
INSERT INTO `departments` (`id`, `title`, `icon`, `header_bg`, `why_toptitle`, `why_title`, `why_content`, `why_pic`, `boxes`, `overview_toptitle`, `overview_title`, `overview_content`, `overview_pic`, `program_toptitle`, `program_title`, `sections_toptitle`, `sections_title`, `sections_content`, `outcomes`, `created_at`, `updated_at`, `order_column`, `is_simple`, `reverse_layout`, `overview_video`, `tab1_title`, `tab2_title`, `tab3_title`, `tab4_title`, `simple_tabs`) VALUES
(20, '{\"ar\":\"وحدات العناية المركزة (للبالغين والأطفال وحديثي الولادة)\",\"en\":\"Intensive Care Units (Adult, Pediatric & Neonatal)\"}', NULL, NULL, '{\"ar\":\"22\",\"en\":\"Al nas hospital\"}', '{\"en\":\"Why Choose Al Nas Hospital for Intensive Care Units (Adult, Pediatric & Neonatal)?\",\"ar\":null}', '{\"en\":\"<p>At Al Nas Hospital, our Intensive Care Units combine advanced life-support technologies with highly specialized medical and nursing teams to deliver continuous, high-acuity care for critically ill patients of all ages. We provide seamless coordination between adult, pediatric, and neonatal services, ensuring safe transitions and consistent standards of care across every stage of treatment. With a strong emphasis on evidence-based protocols, multidisciplinary collaboration, and continuous monitoring, our ICUs are designed to optimize recovery, minimize complications, and support the best possible outcomes for patients and their families.</p>\",\"ar\":\"<p>4566</p>\"}', NULL, '[{\"uuid\":\"0158c9e1-e84f-43e9-875b-25f272adff38\",\"title\":{\"en\":\"Clinical Programs\",\"ar\":\"ww\"},\"content\":{\"en\":\"Discover our clinical programs delivering expert, patient-centered care.\",\"ar\":null}},{\"uuid\":\"a0ee469c-9eb6-40cb-9f97-82c39d5cd454\",\"title\":{\"en\":\"Departments, Umbrellas of Excellence & Centers\",\"ar\":\"ee\"},\"content\":{\"en\":\"Explore our specialties offering comprehensive care across multiple fields.\",\"ar\":null}},{\"uuid\":\"58ae3b88-3111-4fc6-8506-ae71eb4338a8\",\"title\":{\"en\":\"Outcomes\",\"ar\":\"dd\"},\"content\":{\"en\":\"Learn how our care transforms patient outcomes and quality of life.\",\"ar\":null}}]', '{\"en\":\"Al nas hospital\",\"ar\":null}', '{\"ar\":null}', '{\"en\":\"<p>Youssef… faced the challenge, and today he is the hero of his story <br>His journey of treatment began at Al Nas Hospital, and today he is living his life anew. But there are still other children waiting for their chance to heal, and your support can change their lives.</p>\",\"ar\":\"<p>يوسف.. واجه التحدي، والنهارده هو بطل القصة <br>    من مستشفى الناس، بدأ رحلة العلاج، والنهارده بيعيش حياته من جديد. لكن في أطفال تانين لسه مستنيين فرصة الشفاء، ودعمكم يقدر يغير حياتهم.</p>\"}', NULL, '{\"en\":\"al nas hospital\",\"ar\":null}', '{\"en\":\" Al Nas Hospital Clinical Programs\",\"ar\":null}', '{\"en\":\"al nas hospital\",\"ar\":null}', '{\"en\":\"Departments\",\"ar\":null}', '{\"en\":\"<p>The Intensive Care Units at Al Nas Hospital provide comprehensive, around-the-clock critical care for patients across all age groups, from newborns to adults. Supported by advanced monitoring, life-support technologies, and highly trained multidisciplinary teams, our ICUs manage complex medical and surgical conditions, including high-risk cardiac, gastrointestinal, and transplant cases. Through seamless coordination between adult, pediatric, and neonatal critical care services, we ensure continuous, patient-centered management from preoperative stabilization to postoperative recovery, with a strong focus on safety, precision, and long-term outcomes.</p>\",\"ar\":\"<p></p>\"}', '[{\"0\":{\"title\":\"out 1\",\"content\":\"<p>Our department is equipped with advanced imaging technologies including 3D echocardiography, CT, and MRI, ensuring precise diagnostics, safer interventions, and improved outcomes.<\\/p><p>With renowned professors and consultants who bring international expertise, we excel in treating complex and high-risk cases such as chronic total occlusions, high-risk percutaneous interventions, and adult congenital heart disease.<\\/p><p>Care is delivered through a collaborative heart team approach that integrates cardiologists, surgeons, and imaging specialists, supported by extensive case experience, innovative non-surgical options such as TAVI and TAVR, and a strong commitment to minimally invasive procedures for faster recovery.<\\/p><p>As a teaching hospital, we are dedicated to academic excellence through fellowships, international collaborations, and continuous training.<\\/p><p>Our patient-centered model ensures accessible, lifelong care including specialized adult congenital programs, while maintaining the highest standards of quality, safety, and evidence-based practice through ongoing audits and performance reviews.<\\/p>\",\"embed\":null},\"1\":{\"title\":\"out 2\",\"content\":\"<p>Our department is equipped with advanced imaging technologies including 3D echocardiography, CT, and MRI, ensuring precise diagnostics, safer interventions, and improved outcomes.<\\/p><p>With renowned professors and consultants who bring international expertise, we excel in treating complex and high-risk cases such as chronic total occlusions, high-risk percutaneous interventions, and adult congenital heart disease.<\\/p><p>Care is delivered through a collaborative heart team approach that integrates cardiologists, surgeons, and imaging specialists, supported by extensive case experience, innovative non-surgical options such as TAVI and TAVR, and a strong commitment to minimally invasive procedures for faster recovery.<\\/p><p>As a teaching hospital, we are dedicated to academic excellence through fellowships, international collaborations, and continuous training.<\\/p><p>Our patient-centered model ensures accessible, lifelong care including specialized adult congenital programs, while maintaining the highest standards of quality, safety, and evidence-based practice through ongoing audits and performance reviews.<\\/p>\",\"embed\":null},\"content\":{\"en\":\"<p>Discover the medical specialties at Al Nas Hospital, where expert teams provide care across<\\/p>\",\"ar\":\"<p><\\/p>\"},\"embeds\":[{\"embed\":\"embed\"}],\"title\":{\"en\":\"Outcomes\",\"ar\":null}}]', '2025-12-24 08:31:48', '2026-02-11 14:36:46', NULL, 0, 0, 'https://www.youtube.com/watch?v=h0Cp207PJGI', '{\"ar\":null}', '{\"ar\":null}', '{\"ar\":null}', '{\"ar\":null}', NULL),
(21, '{\"ar\":\"المختبر وبنك الدم\",\"en\":\"Laboratory & Blood bank\"}', NULL, NULL, '{\"ar\":\"22\",\"en\":\"Al nas hospital\"}', '{\"en\":\"Why Choose Al Nas Hospital for Laboratory & Blood bank?\",\"ar\":null}', '{\"en\":\"<p>Al Nas Hospital’s Laboratory and Blood Bank combine advanced technology, highly trained specialists, and strict adherence to international quality standards to deliver safe, accurate, and timely diagnostic and transfusion services. Our integrated approach ensures reliable results, rapid availability of blood and blood components, and seamless support for complex medical and surgical procedures. By prioritizing patient safety, traceability, and excellence, we provide clinicians with the confidence to make informed decisions and optimize outcomes across all hospital specialties.</p>\",\"ar\":\"<p>4566</p>\"}', NULL, '[{\"uuid\":\"0158c9e1-e84f-43e9-875b-25f272adff38\",\"title\":{\"en\":\"Clinical Programs\",\"ar\":\"ww\"},\"content\":{\"en\":\"Discover our clinical programs delivering expert, patient-centered care.\",\"ar\":null}},{\"uuid\":\"a0ee469c-9eb6-40cb-9f97-82c39d5cd454\",\"title\":{\"en\":\"Departments, Umbrellas of Excellence & Centers\",\"ar\":\"ee\"},\"content\":{\"en\":\"Explore our specialties offering comprehensive care across multiple fields.\",\"ar\":null}},{\"uuid\":\"58ae3b88-3111-4fc6-8506-ae71eb4338a8\",\"title\":{\"en\":\"Outcomes\",\"ar\":\"dd\"},\"content\":{\"en\":\"Learn how our care transforms patient outcomes and quality of life.\",\"ar\":null}}]', '{\"en\":\"Al nas hospital\",\"ar\":null}', '{\"ar\":null}', '{\"en\":\"<p>Nada was very sick, and thanks to your support, we were able to help her—and many other children like her. Don’t stop doing good.</p>\",\"ar\":\"<p>ندى كانت تعبانة قوي، وبفضل مساعدتكم قدرنا نساعدها ونساعد اطفال تانية كتير زي ندى. متوقفش الخير.</p>\"}', NULL, '{\"en\":\"al nas hospital\",\"ar\":null}', '{\"en\":\" Al Nas Hospital Clinical Programs\",\"ar\":null}', '{\"en\":\"al nas hospital\",\"ar\":null}', '{\"en\":\"Departments\",\"ar\":null}', '{\"en\":\"<p>At Al Nas Hospital, our Laboratory and Blood Bank services form the cornerstone of safe, accurate, and advanced patient care. Together, they provide timely, precise, and reliable diagnostic testing, as well as a safe and readily available supply of blood and blood components for routine needs and complex procedures, including cardiac surgery, liver transplantation, and pediatric interventions. Staffed by highly skilled professionals and equipped with cutting-edge technology, both departments adhere to international quality and safety standards, ensuring every clinical decision is supported by accurate results and every transfusion is traceable and secure.</p>\",\"ar\":\"<p></p>\"}', '[{\"0\":{\"title\":\"out 1\",\"content\":\"<p>Our department is equipped with advanced imaging technologies including 3D echocardiography, CT, and MRI, ensuring precise diagnostics, safer interventions, and improved outcomes.<\\/p><p>With renowned professors and consultants who bring international expertise, we excel in treating complex and high-risk cases such as chronic total occlusions, high-risk percutaneous interventions, and adult congenital heart disease.<\\/p><p>Care is delivered through a collaborative heart team approach that integrates cardiologists, surgeons, and imaging specialists, supported by extensive case experience, innovative non-surgical options such as TAVI and TAVR, and a strong commitment to minimally invasive procedures for faster recovery.<\\/p><p>As a teaching hospital, we are dedicated to academic excellence through fellowships, international collaborations, and continuous training.<\\/p><p>Our patient-centered model ensures accessible, lifelong care including specialized adult congenital programs, while maintaining the highest standards of quality, safety, and evidence-based practice through ongoing audits and performance reviews.<\\/p>\",\"embed\":null},\"1\":{\"title\":\"out 2\",\"content\":\"<p>Our department is equipped with advanced imaging technologies including 3D echocardiography, CT, and MRI, ensuring precise diagnostics, safer interventions, and improved outcomes.<\\/p><p>With renowned professors and consultants who bring international expertise, we excel in treating complex and high-risk cases such as chronic total occlusions, high-risk percutaneous interventions, and adult congenital heart disease.<\\/p><p>Care is delivered through a collaborative heart team approach that integrates cardiologists, surgeons, and imaging specialists, supported by extensive case experience, innovative non-surgical options such as TAVI and TAVR, and a strong commitment to minimally invasive procedures for faster recovery.<\\/p><p>As a teaching hospital, we are dedicated to academic excellence through fellowships, international collaborations, and continuous training.<\\/p><p>Our patient-centered model ensures accessible, lifelong care including specialized adult congenital programs, while maintaining the highest standards of quality, safety, and evidence-based practice through ongoing audits and performance reviews.<\\/p>\",\"embed\":null},\"content\":{\"en\":\"<p>Discover the medical specialties at Al Nas Hospital, where expert teams provide care across<\\/p>\",\"ar\":\"<p><\\/p>\"},\"embeds\":[{\"embed\":\"embed\"}],\"title\":{\"en\":\"Outcomes\",\"ar\":null}}]', '2025-12-24 08:31:48', '2026-02-11 14:47:47', NULL, 0, 0, 'https://www.youtube.com/watch?v=KX1lBcrXXNE', '{\"ar\":null}', '{\"ar\":null}', '{\"ar\":null}', '{\"ar\":null}', NULL),
