INSERT INTO `department_sections` (`id`, `title`, `department_id`, `overview`, `scope_of_unit`, `what_we_treat`, `leadership`, `achievements`, `news`, `created_at`, `updated_at`) VALUES
(1, '{\"en\":\"Endocrinology Department\",\"ar\":\"قسم الغدد الصماء – وحدة السكري\"}', 6, '{\"en\":\"<p>The Diabetes Unit at Al Nas Hospital is a central part of our Endocrinology Department, dedicated to the diagnosis, management, and long-term care of patients with diabetes and endocrine disorders. The unit combines advanced medical expertise with evidence-based protocols to deliver comprehensive care for a wide spectrum of conditions, from diabetes and thyroid disease to adrenal, pituitary, and metabolic bone disorders.</p>\",\"ar\":\"<p>تُعد وحدة السكري بمستشفى الناس جزءًا محوريًا من قسم الغدد الصماء، وتختص بتشخيص وعلاج والمتابعة طويلة المدى لمرضى السكري واضطرابات الغدد الصماء. تجمع الوحدة بين الخبرات الطبية المتقدمة والبروتوكولات العلاجية المعتمدة على الأدلة العلمية لتقديم رعاية شاملة لمجموعة واسعة من الحالات، بدءًا من السكري وأمراض الغدة الدرقية، وصولًا إلى اضطرابات الغدة الكظرية والنخامية وأمراض العظام الأيضية.</p>\"}', '{\"en\":\"<p>The unit specializes in both inpatient and outpatient endocrine care, integrating advanced diagnostics, personalized treatment plans, and multidisciplinary collaboration. It also plays a key role in prevention, patient education, long-term disease management and complications monitoring and treatment.</p><ul><li><p>Diabetes &amp; Metabolic Disorders: Management of type 1 and type 2 diabetes, gestational diabetes, pre-diabetes, obesity, and lipid disorders.</p></li><li><p>Thyroid Disorders: Diagnosis and treatment of hypothyroidism, hyperthyroidism, thyroid nodules, and thyroid cancers.</p></li><li><p>Adrenal &amp; Pituitary Disorders: Comprehensive care for adrenal insufficiency, Cushing’s syndrome, pituitary tumors, and hormonal imbalances.</p></li><li><p>Metabolic Bone &amp; Growth Disorders: Evaluation and management of osteoporosis, calcium/vitamin D disorders, short stature, and growth hormone abnormalities.</p></li></ul>\",\"ar\":\"<p>تختص الوحدة بتقديم رعاية الغدد الصماء للمرضى الداخليين والمترددين على العيادات الخارجية، مع دمج أحدث وسائل التشخيص، وخطط علاجية فردية، وتعاون متعدد التخصصات. كما تلعب دورًا أساسيًا في الوقاية، وتثقيف المرضى، وإدارة الأمراض المزمنة على المدى الطويل، ومتابعة وعلاج المضاعفات.</p><p></p><p>اضطرابات السكري والتمثيل الغذائي: علاج داء السكري من النوعين الأول والثاني، وسكري الحمل، ومقدمات السكري، والسمنة، واضطرابات الدهون.</p><p></p><p>اضطرابات الغدة الدرقية: تشخيص وعلاج قصور وفرط نشاط الغدة الدرقية، وعُقَد الغدة الدرقية، وسرطانات الغدة الدرقية.</p><p></p><p>اضطرابات الغدة الكظرية والنخامية: رعاية شاملة لحالات القصور الكظري، ومتلازمة كوشينج، وأورام الغدة النخامية، واضطرابات الهرمونات.</p><p></p><p>اضطرابات العظام الأيضية والنمو: تقييم وعلاج هشاشة العظام، واضطرابات الكالسيوم وفيتامين (د)، وقصر القامة، واضطرابات هرمون النمو.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u0646\\u0639\\u0627\\u0644\\u062c\\u0647\\u0627\"},\"content\":{\"en\":\"<p>We care for patients with hormonal and metabolic disorders affecting glands such as the thyroid, adrenal, pituitary, and parathyroid, including:<\\/p>\",\"ar\":\"<p>\\u0646\\u0642\\u062f\\u0651\\u0645 \\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0645\\u0635\\u0627\\u0628\\u064a\\u0646 \\u0628\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u063a\\u062f\\u062f \\u0627\\u0644\\u0635\\u0645\\u0627\\u0621\\u060c \\u0628\\u0645\\u0627 \\u064a\\u0634\\u0645\\u0644 \\u0627\\u0644\\u0627\\u062e\\u062a\\u0644\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0647\\u0631\\u0645\\u0648\\u0646\\u064a\\u0629\\u060c \\u0648\\u0627\\u0644\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0623\\u064a\\u0636\\u064a\\u0629\\u060c \\u0648\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u063a\\u062f\\u062f \\u0627\\u0644\\u062a\\u064a \\u062a\\u0624\\u062b\\u0631 \\u0641\\u064a \\u0627\\u0644\\u0635\\u062d\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629 \\u0648\\u0648\\u0638\\u0627\\u0626\\u0641 \\u0627\\u0644\\u062c\\u0633\\u0645. \\u0648\\u062a\\u0634\\u0645\\u0644 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a:<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Type 1 and Type 2 Diabetes\",\"ar\":\" \\u0627\\u0644\\u062f\\u0631\\u062c\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649 \\u0648\\u0627\\u0644\\u062b\\u0627\\u0646\\u064a\\u0629 \\u0645\\u0646 \\u0645\\u0631\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631\\u0649\"}},{\"text\":{\"en\":\"Gestational Diabetes\",\"ar\":\"\\u0633\\u0643\\u0631\\u0649 \\u0627\\u0644\\u062d\\u0645\\u0644\"}},{\"text\":{\"en\":\"Pre diabetes\",\"ar\":\"\\u0645\\u0631\\u062d\\u0644\\u0629 \\u0645\\u0627 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u0633\\u0643\\u0631\\u0649\"}},{\"text\":{\"en\":\"Obesity and metabolic syndrome\",\"ar\":\"\\u0627\\u0644\\u0633\\u0645\\u0646\\u0629 \\u0648\\u0645\\u062a\\u0644\\u0627\\u0632\\u0645\\u0629 \\u0627\\u0644\\u0623\\u064a\\u0636 (\\u0627\\u0644\\u062a\\u0645\\u062b\\u064a\\u0644 \\u0627\\u0644\\u063a\\u0630\\u0627\\u0626\\u064a)\"}},{\"text\":{\"en\":\"Thyroid disease (hypothyroidism, hyperthyroidism, nodules, thyroid cancer)\",\"ar\":\"\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u063a\\u062f\\u0629 \\u0627\\u0644\\u062f\\u0631\\u0642\\u064a\\u0629 (\\u0642\\u0635\\u0648\\u0631 \\u0627\\u0644\\u063a\\u062f\\u0629 \\u0627\\u0644\\u062f\\u0631\\u0642\\u064a\\u0629\\u060c \\u0641\\u0631\\u0637 \\u0646\\u0634\\u0627\\u0637 \\u0627\\u0644\\u063a\\u062f\\u0629 \\u0627\\u0644\\u062f\\u0631\\u0642\\u064a\\u0629\\u060c \\u0627\\u0644\\u0639\\u064f\\u0642\\u064a\\u062f\\u0627\\u062a \\u0627\\u0644\\u062f\\u0631\\u0642\\u064a\\u0629\\u060c \\u0648\\u0633\\u0631\\u0637\\u0627\\u0646 \\u0627\\u0644\\u063a\\u062f\\u0629 \\u0627\\u0644\\u062f\\u0631\\u0642\\u064a\\u0629)\"}},{\"text\":{\"en\":\"Adrenal disorders (Cushing\\u2019s, Addison\\u2019s, pheochromocytoma, adrenal tumors)\",\"ar\":\"\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u063a\\u062f\\u0629 \\u0627\\u0644\\u0643\\u0638\\u0631\\u064a\\u0629 (\\u0645\\u062a\\u0644\\u0627\\u0632\\u0645\\u0629 \\u0643\\u0648\\u0634\\u064a\\u0646\\u063a\\u060c \\u0645\\u0631\\u0636 \\u0623\\u062f\\u064a\\u0633\\u0648\\u0646\\u060c \\u0627\\u0644\\u0648\\u0631\\u0645 \\u0627\\u0644\\u0639\\u0635\\u0628\\u064a \\u0627\\u0644\\u0643\\u0638\\u0631\\u064a\\u060c \\u0623\\u0648\\u0631\\u0627\\u0645 \\u0627\\u0644\\u063a\\u062f\\u0629 \\u0627\\u0644\\u0643\\u0638\\u0631\\u064a\\u0629)\"}},{\"text\":{\"en\":\"Pituitary disorders (prolactinoma, growth hormone abnormalities, pituitary adenomas)\",\"ar\":\"\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u063a\\u062f\\u0629 \\u0627\\u0644\\u0646\\u062e\\u0627\\u0645\\u064a\\u0629 (\\u0627\\u0644\\u0648\\u0631\\u0645 \\u0627\\u0644\\u0628\\u0631\\u0648\\u0644\\u0627\\u0643\\u062a\\u064a\\u0646\\u064a\\u060c \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0647\\u0631\\u0645\\u0648\\u0646 \\u0627\\u0644\\u0646\\u0645\\u0648\\u060c \\u0648\\u0623\\u0648\\u0631\\u0627\\u0645 \\u0627\\u0644\\u063a\\u062f\\u0629 \\u0627\\u0644\\u0646\\u062e\\u0627\\u0645\\u064a\\u0629 \\u0627\\u0644\\u062d\\u0645\\u064a\\u062f\\u0629)\"}},{\"text\":{\"en\":\"Osteoporosis and bone health conditions\",\"ar\":\"\\u0647\\u0634\\u0627\\u0634\\u0629 \\u0627\\u0644\\u0639\\u0638\\u0627\\u0645 \\u0648\\u062d\\u0627\\u0644\\u0627\\u062a \\u0635\\u062d\\u0629 \\u0627\\u0644\\u0639\\u0638\\u0627\\u0645\"}},{\"text\":{\"en\":\"Lipid disorders and dyslipidemia\",\"ar\":\"\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u062f\\u0647\\u0648\\u0646 \\u0648\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0634\\u062d\\u0648\\u0645 \\u0627\\u0644\\u062f\\u0645 (\\u062e\\u0644\\u0644 \\u0634\\u062d\\u0648\\u0645 \\u0627\\u0644\\u062f\\u0645)\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":56,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"ahm ar\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":\"\\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\"},\"doctors\":[{\"doctor\":74,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":57,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]}]', '[{\"text\":{\"en\":\"An 11-year-old child was diagnosed with diabetes 2 years ago. His mother was in a state of shock and deeply wished that her child did not have diabetes, as she found it very difficult to manage his condition. The child was experiencing frequent episodes of hypoglycemia and unexplained high blood sugar, both for the mother and the child. Since the diagnosis, he had been unable to live a normal daily life. After coming to Al-Nas Hospital and attending the Diabetes Education Clinic, we worked together to identify several errors that were contributing to the fluctuations. The most important of these included injecting insulin into areas of hardened tissue, inaccurate carbohydrate counting, incorrect treatment of low blood sugar, and raising blood glucose levels beyond the appropriate target after a hypoglycemic episode. With continuous follow-up, these mistakes were corrected. The child no longer experiences unexplained hypoglycemia, and with treatment of the injection-sites, accurate meal calculations, and regular rotation of injection sites, he no longer has unexplained high blood sugar. Today, the child is living a calm and normal life without constant stress. He is able to return to school after a period of avoiding many daily activities due to fear of low blood sugar episodes.\",\"ar\":\"\\u062a\\u0645 \\u062a\\u0634\\u062e\\u064a\\u0635 \\u0637\\u0641\\u0644 \\u064a\\u0628\\u0644\\u063a \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0631 11 \\u0639\\u0627\\u0645\\u064b\\u0627 \\u0628\\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0645\\u0646\\u0630 \\u0639\\u0627\\u0645\\u064a\\u0646. \\u0643\\u0627\\u0646\\u062a \\u0648\\u0627\\u0644\\u062f\\u062a\\u0647 \\u0641\\u064a \\u062d\\u0627\\u0644\\u0629 \\u0635\\u062f\\u0645\\u0629\\u060c \\u0648\\u0643\\u0627\\u0646\\u062a \\u062a\\u062a\\u0645\\u0646\\u0649 \\u0628\\u0634\\u062f\\u0629 \\u0623\\u0644\\u0627 \\u064a\\u064f\\u0635\\u0627\\u0628 \\u0637\\u0641\\u0644\\u0647\\u0627 \\u0628\\u0627\\u0644\\u0633\\u0643\\u0631\\u064a\\u060c \\u0625\\u0630 \\u0648\\u062c\\u062f\\u062a \\u0635\\u0639\\u0648\\u0628\\u0629 \\u0643\\u0628\\u064a\\u0631\\u0629 \\u0641\\u064a \\u0625\\u062f\\u0627\\u0631\\u0629 \\u062d\\u0627\\u0644\\u062a\\u0647. \\u0643\\u0627\\u0646 \\u0627\\u0644\\u0637\\u0641\\u0644 \\u064a\\u0639\\u0627\\u0646\\u064a \\u0645\\u0646 \\u0646\\u0648\\u0628\\u0627\\u062a \\u0645\\u062a\\u0643\\u0631\\u0631\\u0629 \\u0645\\u0646 \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645 \\u0648\\u0627\\u0631\\u062a\\u0641\\u0627\\u0639 \\u063a\\u064a\\u0631 \\u0645\\u0641\\u0633\\u0631 \\u0644\\u0645\\u0633\\u062a\\u0648\\u0649 \\u0627\\u0644\\u0633\\u0643\\u0631\\u060c \\u0648\\u0647\\u0648 \\u0645\\u0627 \\u0633\\u0628\\u0628 \\u0627\\u0644\\u0642\\u0644\\u0642 \\u0644\\u0643\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0645 \\u0648\\u0627\\u0644\\u0637\\u0641\\u0644. \\u0645\\u0646\\u0630 \\u0627\\u0644\\u062a\\u0634\\u062e\\u064a\\u0635\\u060c \\u0644\\u0645 \\u064a\\u062a\\u0645\\u0643\\u0646 \\u0627\\u0644\\u0637\\u0641\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0639\\u064a\\u0634 \\u062d\\u064a\\u0627\\u0629 \\u064a\\u0648\\u0645\\u064a\\u0629 \\u0637\\u0628\\u064a\\u0639\\u064a\\u0629.  \\u0628\\u0639\\u062f \\u062d\\u0636\\u0648\\u0631\\u0647 \\u0625\\u0644\\u0649 \\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0648\\u0627\\u0644\\u0627\\u0646\\u0636\\u0645\\u0627\\u0645 \\u0625\\u0644\\u0649 \\u0639\\u064a\\u0627\\u062f\\u0629 \\u062a\\u062b\\u0642\\u064a\\u0641 \\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a\\u060c \\u0639\\u0645\\u0644\\u0646\\u0627 \\u0645\\u0639\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u062a\\u062d\\u062f\\u064a\\u062f \\u0639\\u062f\\u0629 \\u0623\\u062e\\u0637\\u0627\\u0621 \\u0643\\u0627\\u0646\\u062a \\u062a\\u0633\\u0628\\u0628 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062a\\u0642\\u0644\\u0628\\u0627\\u062a. \\u0645\\u0646 \\u0623\\u0647\\u0645 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u0623\\u062e\\u0637\\u0627\\u0621: \\u062d\\u0642\\u0646 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0641\\u064a \\u0645\\u0646\\u0627\\u0637\\u0642 \\u0645\\u0646 \\u0627\\u0644\\u0646\\u0633\\u064a\\u062c \\u0627\\u0644\\u0645\\u062a\\u0635\\u0644\\u0628\\u060c \\u0639\\u062f\\u0645 \\u062f\\u0642\\u0629 \\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0643\\u0631\\u0628\\u0648\\u0647\\u064a\\u062f\\u0631\\u0627\\u062a\\u060c \\u0627\\u0644\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u063a\\u064a\\u0631 \\u0627\\u0644\\u0635\\u062d\\u064a\\u062d\\u0629 \\u0644\\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645\\u060c \\u0648\\u0631\\u0641\\u0639 \\u0645\\u0633\\u062a\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0628\\u0639\\u062f \\u0646\\u0648\\u0628\\u0629 \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0623\\u0643\\u062b\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0647\\u062f\\u0641 \\u0627\\u0644\\u0645\\u0648\\u0635\\u0649 \\u0628\\u0647.  \\u0645\\u0639 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631\\u0629\\u060c \\u062a\\u0645 \\u062a\\u0635\\u062d\\u064a\\u062d \\u0647\\u0630\\u0647 \\u0627\\u0644\\u0623\\u062e\\u0637\\u0627\\u0621. \\u0644\\u0645 \\u064a\\u0639\\u062f \\u0627\\u0644\\u0637\\u0641\\u0644 \\u064a\\u0639\\u0627\\u0646\\u064a \\u0645\\u0646 \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u063a\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0641\\u0633\\u0631\\u060c \\u0648\\u0645\\u0639 \\u062a\\u0635\\u062d\\u064a\\u062d \\u0645\\u0648\\u0627\\u0642\\u0639 \\u0627\\u0644\\u062d\\u0642\\u0646\\u060c \\u0648\\u0627\\u0644\\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642 \\u0644\\u0644\\u0648\\u062c\\u0628\\u0627\\u062a\\u060c \\u0648\\u0627\\u0644\\u062a\\u0646\\u0627\\u0648\\u0628 \\u0627\\u0644\\u0645\\u0646\\u062a\\u0638\\u0645 \\u0644\\u0645\\u0648\\u0627\\u0642\\u0639 \\u0627\\u0644\\u062d\\u0642\\u0646\\u060c \\u0644\\u0645 \\u062a\\u0639\\u062f \\u062a\\u0638\\u0647\\u0631 \\u0627\\u0631\\u062a\\u0641\\u0627\\u0639\\u0627\\u062a \\u063a\\u064a\\u0631 \\u0645\\u0641\\u0633\\u0631\\u0629 \\u0641\\u064a \\u0633\\u0643\\u0631 \\u0627\\u0644\\u062f\\u0645.  \\u0627\\u0644\\u064a\\u0648\\u0645\\u060c \\u064a\\u0639\\u064a\\u0634 \\u0627\\u0644\\u0637\\u0641\\u0644 \\u062d\\u064a\\u0627\\u0629 \\u0647\\u0627\\u062f\\u0626\\u0629 \\u0648\\u0637\\u0628\\u064a\\u0639\\u064a\\u0629 \\u062f\\u0648\\u0646 \\u062a\\u0648\\u062a\\u0631 \\u0645\\u0633\\u062a\\u0645\\u0631. \\u0648\\u0642\\u062f \\u0623\\u0635\\u0628\\u062d \\u0642\\u0627\\u062f\\u0631\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0639\\u0648\\u062f\\u0629 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0645\\u062f\\u0631\\u0633\\u0629 \\u0628\\u0639\\u062f \\u0641\\u062a\\u0631\\u0629 \\u0645\\u0646 \\u062a\\u062c\\u0646\\u0628 \\u0627\\u0644\\u0639\\u062f\\u064a\\u062f \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0646\\u0634\\u0637\\u0629 \\u0627\\u0644\\u064a\\u0648\\u0645\\u064a\\u0629 \\u062e\\u0648\\u0641\\u064b\\u0627 \\u0645\\u0646 \\u0646\\u0648\\u0628\\u0627\\u062a \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645.\"}},{\"text\":{\"en\":\"A 12-year-old girl from Upper Egypt had been experiencing frequent nighttime hypoglycemic episodes for eight months. Her family felt anxious and unprepared to handle diabetes emergencies, especially due to limited access to experienced care in their local hospitals.  The medical team trained the family on how to manage common emergencies at home and provided direct contact numbers for ongoing support. Daily phone follow-ups and glucose monitoring revealed that the girl had been secretly administering extra insulin, which was the true cause of the repeated low blood sugar episodes.  The team spoke directly with her, understood her concerns, and supported her emotionally. Gradually, she began following her correct treatment plan, her readings improved significantly, and accurate insulin ratios were finally established after the underlying cause was identified.\",\"ar\":\"\\u0641\\u062a\\u0627\\u0629 \\u062a\\u0628\\u0644\\u063a \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0631 12 \\u0639\\u0627\\u0645\\u064b\\u0627 \\u0645\\u0646 \\u0635\\u0639\\u064a\\u062f \\u0645\\u0635\\u0631 \\u0643\\u0627\\u0646\\u062a \\u062a\\u0639\\u0627\\u0646\\u064a \\u0645\\u0646 \\u0646\\u0648\\u0628\\u0627\\u062a \\u0645\\u062a\\u0643\\u0631\\u0631\\u0629 \\u0645\\u0646 \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645 \\u0623\\u062b\\u0646\\u0627\\u0621 \\u0627\\u0644\\u0644\\u064a\\u0644 \\u0644\\u0645\\u062f\\u0629 \\u062b\\u0645\\u0627\\u0646\\u064a\\u0629 \\u0623\\u0634\\u0647\\u0631. \\u0634\\u0639\\u0631\\u062a \\u0639\\u0627\\u0626\\u0644\\u062a\\u0647\\u0627 \\u0628\\u0627\\u0644\\u0642\\u0644\\u0642 \\u0648\\u0639\\u062f\\u0645 \\u0627\\u0644\\u0642\\u062f\\u0631\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0639\\u0627\\u0645\\u0644 \\u0645\\u0639 \\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0637\\u0648\\u0627\\u0631\\u0626 \\u0627\\u0644\\u0645\\u062a\\u0639\\u0644\\u0642\\u0629 \\u0628\\u0627\\u0644\\u0633\\u0643\\u0631\\u064a\\u060c \\u062e\\u0635\\u0648\\u0635\\u064b\\u0627 \\u0628\\u0633\\u0628\\u0628 \\u0645\\u062d\\u062f\\u0648\\u062f\\u064a\\u0629 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062a\\u062e\\u0635\\u0635\\u0629 \\u0641\\u064a \\u0645\\u0633\\u062a\\u0634\\u0641\\u064a\\u0627\\u062a \\u0645\\u0646\\u0637\\u0642\\u062a\\u0647\\u0645.  \\u0642\\u0627\\u0645 \\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a \\u0628\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0627\\u0644\\u0639\\u0627\\u0626\\u0644\\u0629 \\u0639\\u0644\\u0649 \\u0643\\u064a\\u0641\\u064a\\u0629 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0637\\u0627\\u0631\\u0626\\u0629 \\u0627\\u0644\\u0634\\u0627\\u0626\\u0639\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0646\\u0632\\u0644\\u060c \\u0648\\u062a\\u0632\\u0648\\u064a\\u062f\\u0647\\u0645 \\u0628\\u0623\\u0631\\u0642\\u0627\\u0645 \\u0627\\u062a\\u0635\\u0627\\u0644 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0644\\u0644\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631. \\u0643\\u0634\\u0641\\u062a \\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0627\\u0644\\u064a\\u0648\\u0645\\u064a\\u0629 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0648\\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u0645\\u0633\\u062a\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0623\\u0646 \\u0627\\u0644\\u0641\\u062a\\u0627\\u0629 \\u0643\\u0627\\u0646\\u062a \\u062a\\u062a\\u0646\\u0627\\u0648\\u0644 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0628\\u0634\\u0643\\u0644 \\u0625\\u0636\\u0627\\u0641\\u064a \\u0628\\u0634\\u0643\\u0644 \\u0633\\u0631\\u064a\\u060c \\u0648\\u0647\\u0648 \\u0627\\u0644\\u0633\\u0628\\u0628 \\u0627\\u0644\\u062d\\u0642\\u064a\\u0642\\u064a \\u0644\\u0644\\u0646\\u0648\\u0628\\u0627\\u062a \\u0627\\u0644\\u0645\\u062a\\u0643\\u0631\\u0631\\u0629 \\u0645\\u0646 \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645.  \\u062a\\u062d\\u062f\\u062b \\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0645\\u0639\\u0647\\u0627\\u060c \\u0648\\u0641\\u0647\\u0645 \\u0645\\u062e\\u0627\\u0648\\u0641\\u0647\\u0627\\u060c \\u0648\\u0642\\u062f\\u0645 \\u0644\\u0647\\u0627 \\u0627\\u0644\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a \\u0648\\u0627\\u0644\\u0639\\u0627\\u0637\\u0641\\u064a. \\u062a\\u062f\\u0631\\u064a\\u062c\\u064a\\u064b\\u0627\\u060c \\u0628\\u062f\\u0623\\u062a \\u0627\\u0644\\u0641\\u062a\\u0627\\u0629 \\u0628\\u0627\\u0644\\u0627\\u0644\\u062a\\u0632\\u0627\\u0645 \\u0628\\u062e\\u0637\\u0629 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u0635\\u062d\\u064a\\u062d\\u0629\\u060c \\u0648\\u062a\\u062d\\u0633\\u0646\\u062a \\u0642\\u0631\\u0627\\u0621\\u0627\\u062a\\u0647\\u0627 \\u0628\\u0634\\u0643\\u0644 \\u0643\\u0628\\u064a\\u0631\\u060c \\u0648\\u062a\\u0645 \\u062a\\u062d\\u062f\\u064a\\u062f \\u0646\\u0633\\u0628 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642\\u0629 \\u0628\\u0639\\u062f \\u0627\\u0643\\u062a\\u0634\\u0627\\u0641 \\u0627\\u0644\\u0633\\u0628\\u0628 \\u0627\\u0644\\u0643\\u0627\\u0645\\u0646 \\u0648\\u0631\\u0627\\u0621 \\u0627\\u0644\\u0645\\u0634\\u0643\\u0644\\u0629.\"}},{\"text\":{\"en\":\"A 7-year-old child was diagnosed with type 1 diabetes. Initially, the mother refused insulin therapy and tried using oral medications that are not suitable for this condition. She also restricted the child\\u2019s food intake to avoid high blood sugar, which led to noticeable weight loss and repeated episodes of diabetic ketoacidosis requiring hospital admission. Through careful medical follow-up and continuous education, the healthcare team explained the nature of type 1 diabetes and emphasized that insulin is the essential and only effective treatment. The risks of food deprivation were also clarified, along with the importance of a balanced diet and proper adjustment of both basal and mealtime insulin. As a result, the mother adhered to the treatment plan, the child\\u2019s blood sugar levels stabilized, overall health improved significantly, and no further hospital admissions were required.\",\"ar\":\"\\u062a\\u0645 \\u062a\\u0634\\u062e\\u064a\\u0635 \\u0637\\u0641\\u0644 \\u064a\\u0628\\u0644\\u063a \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0631 7 \\u0633\\u0646\\u0648\\u0627\\u062a \\u0628\\u0645\\u0631\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0645\\u0646 \\u0627\\u0644\\u0646\\u0648\\u0639 \\u0627\\u0644\\u0623\\u0648\\u0644. \\u0641\\u064a \\u0627\\u0644\\u0628\\u062f\\u0627\\u064a\\u0629\\u060c \\u0631\\u0641\\u0636\\u062a \\u0627\\u0644\\u0623\\u0645 \\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0648\\u062d\\u0627\\u0648\\u0644\\u062a \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0623\\u062f\\u0648\\u064a\\u0629 \\u0641\\u0645\\u0648\\u064a\\u0629 \\u063a\\u064a\\u0631 \\u0645\\u0646\\u0627\\u0633\\u0628\\u0629 \\u0644\\u0647\\u0630\\u0647 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0629. \\u0643\\u0645\\u0627 \\u0642\\u0627\\u0645\\u062a \\u0628\\u062a\\u0642\\u064a\\u064a\\u062f \\u063a\\u0630\\u0627\\u0621 \\u0627\\u0644\\u0637\\u0641\\u0644 \\u0644\\u062a\\u062c\\u0646\\u0628 \\u0627\\u0631\\u062a\\u0641\\u0627\\u0639 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645\\u060c \\u0645\\u0645\\u0627 \\u0623\\u062f\\u0649 \\u0625\\u0644\\u0649 \\u0641\\u0642\\u062f\\u0627\\u0646 \\u0648\\u0632\\u0646 \\u0645\\u0644\\u062d\\u0648\\u0638 \\u0648\\u062d\\u062f\\u0648\\u062b \\u0646\\u0648\\u0628\\u0627\\u062a \\u0645\\u062a\\u0643\\u0631\\u0631\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u062d\\u0645\\u0627\\u0636 \\u0627\\u0644\\u0643\\u064a\\u062a\\u0648\\u0646\\u064a \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0627\\u0633\\u062a\\u062f\\u0639\\u062a \\u062f\\u062e\\u0648\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649.  \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642\\u0629 \\u0648\\u0627\\u0644\\u062a\\u062b\\u0642\\u064a\\u0641 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631\\u060c \\u0642\\u0627\\u0645 \\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a \\u0628\\u0634\\u0631\\u062d \\u0637\\u0628\\u064a\\u0639\\u0629 \\u0645\\u0631\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0645\\u0646 \\u0627\\u0644\\u0646\\u0648\\u0639 \\u0627\\u0644\\u0623\\u0648\\u0644\\u060c \\u0648\\u0623\\u0643\\u062f \\u0623\\u0646 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0647\\u0648 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633\\u064a \\u0648\\u0627\\u0644\\u0648\\u062d\\u064a\\u062f \\u0627\\u0644\\u0641\\u0639\\u0627\\u0644. \\u0643\\u0645\\u0627 \\u062a\\u0645 \\u062a\\u0648\\u0636\\u064a\\u062d \\u0645\\u062e\\u0627\\u0637\\u0631 \\u062d\\u0631\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0637\\u0641\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0637\\u0639\\u0627\\u0645\\u060c \\u0648\\u0623\\u0647\\u0645\\u064a\\u0629 \\u0627\\u0644\\u062a\\u063a\\u0630\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062a\\u0648\\u0627\\u0632\\u0646\\u0629 \\u0648\\u0636\\u0628\\u0637 \\u062c\\u0631\\u0639\\u0627\\u062a \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633\\u064a\\u0629 \\u0648\\u062c\\u0631\\u0639\\u0627\\u062a \\u0627\\u0644\\u0648\\u062c\\u0628\\u0627\\u062a \\u0628\\u0634\\u0643\\u0644 \\u0635\\u062d\\u064a\\u062d.  \\u0648\\u0646\\u062a\\u064a\\u062c\\u0629 \\u0644\\u0630\\u0644\\u0643\\u060c \\u0627\\u0644\\u062a\\u0632\\u0645\\u062a \\u0627\\u0644\\u0623\\u0645 \\u0628\\u062e\\u0637\\u0629 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c\\u060c \\u0648\\u0627\\u0633\\u062a\\u0642\\u0631\\u062a \\u0645\\u0633\\u062a\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u062f\\u0645 \\u0627\\u0644\\u0637\\u0641\\u0644\\u060c \\u0648\\u062a\\u062d\\u0633\\u0646\\u062a \\u0635\\u062d\\u062a\\u0647 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629 \\u0628\\u0634\\u0643\\u0644 \\u0643\\u0628\\u064a\\u0631\\u060c \\u0648\\u0644\\u0645 \\u062a\\u0639\\u062f \\u0647\\u0646\\u0627\\u0643 \\u062d\\u0627\\u062c\\u0629 \\u0644\\u062f\\u062e\\u0648\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0645\\u0631\\u0629 \\u0623\\u062e\\u0631\\u0649.\"}},{\"text\":{\"en\":\"Two 8-year-old twin girls were diagnosed with type 1 diabetes. Although insulin therapy was started, the mother administered only the basal insulin and did not provide mealtime doses. Out of guilt for restricting their food, she allowed them to eat large amounts of sweets and sugary foods, leading to unstable blood sugar levels and repeated complications. She also kept them out of school due to fear of sudden hypoglycemia. Through regular medical follow-up and education, the team explained the difference between basal and mealtime insulin and the importance of balancing both. The mother was trained to calculate insulin doses based on carbohydrate intake, and the twins were included in understanding their condition and how to manage it. As a result, the twins\\u2019 health improved, they were able to follow a balanced diet with appropriate insulin doses, returned safely to school, and experienced a noticeable improvement in blood sugar stability and overall quality of life.\",\"ar\":null}},{\"text\":{\"en\":\"A 16-year-old female with a nine-year history of type 1 diabetes had been experiencing severe insulin resistance for the past six months. During this period, she required weekly admissions to the intensive care unit due to recurrent episodes of diabetic ketoacidosis that developed shortly after returning home. As a result, she missed an entire academic term. Her condition progressed to the point where her body no longer responded adequately to subcutaneous insulin, and intramuscular insulin became necessary to stabilize her for discharge. She presented to us with critically elevated blood glucose levels. Following the initiation of a hybrid closed-loop insulin pump system, the patient achieved sustained normoglycemia for the first time in six months. At her one-week follow-up visit, her blood glucose levels remained within the normal range, marking her first full week at home without hospitalization during this period.\",\"ar\":\"\\u062a\\u0645 \\u062a\\u0634\\u062e\\u064a\\u0635 \\u062a\\u0648\\u0623\\u0645\\u062a\\u064a\\u0646 \\u062a\\u0628\\u0644\\u063a\\u0627\\u0646 \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0631 8 \\u0633\\u0646\\u0648\\u0627\\u062a \\u0628\\u0645\\u0631\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0645\\u0646 \\u0627\\u0644\\u0646\\u0648\\u0639 \\u0627\\u0644\\u0623\\u0648\\u0644. \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0631\\u063a\\u0645 \\u0645\\u0646 \\u0628\\u062f\\u0621 \\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646\\u060c \\u0643\\u0627\\u0646\\u062a \\u0627\\u0644\\u0623\\u0645 \\u062a\\u0642\\u0648\\u0645 \\u0628\\u0625\\u0639\\u0637\\u0627\\u0621 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633\\u064a \\u0641\\u0642\\u0637 \\u0648\\u0644\\u0645 \\u062a\\u0648\\u0641\\u0631 \\u062c\\u0631\\u0639\\u0627\\u062a \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0645\\u0639 \\u0627\\u0644\\u0648\\u062c\\u0628\\u0627\\u062a. \\u0648\\u0645\\u0646 \\u0634\\u0639\\u0648\\u0631\\u0647\\u0627 \\u0628\\u0627\\u0644\\u0630\\u0646\\u0628 \\u0628\\u0633\\u0628\\u0628 \\u062a\\u0642\\u064a\\u064a\\u062f \\u0627\\u0644\\u0637\\u0639\\u0627\\u0645\\u060c \\u0633\\u0645\\u062d\\u062a \\u0644\\u0647\\u0645\\u0627 \\u0628\\u062a\\u0646\\u0627\\u0648\\u0644 \\u0643\\u0645\\u064a\\u0627\\u062a \\u0643\\u0628\\u064a\\u0631\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u062d\\u0644\\u0648\\u064a\\u0627\\u062a \\u0648\\u0627\\u0644\\u0623\\u0637\\u0639\\u0645\\u0629 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a\\u0629\\u060c \\u0645\\u0645\\u0627 \\u0623\\u062f\\u0649 \\u0625\\u0644\\u0649 \\u062a\\u0642\\u0644\\u0628 \\u0645\\u0633\\u062a\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645 \\u0648\\u062d\\u062f\\u0648\\u062b \\u0645\\u0636\\u0627\\u0639\\u0641\\u0627\\u062a \\u0645\\u062a\\u0643\\u0631\\u0631\\u0629. \\u0643\\u0645\\u0627 \\u0623\\u0628\\u0642\\u062a\\u0647\\u0645\\u0627 \\u062e\\u0627\\u0631\\u062c \\u0627\\u0644\\u0645\\u062f\\u0631\\u0633\\u0629 \\u062e\\u0648\\u0641\\u064b\\u0627 \\u0645\\u0646 \\u062d\\u062f\\u0648\\u062b \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0645\\u0641\\u0627\\u062c\\u0626 \\u0641\\u064a \\u0627\\u0644\\u0633\\u0643\\u0631.  \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0646\\u062a\\u0638\\u0645\\u0629 \\u0648\\u0627\\u0644\\u062a\\u062b\\u0642\\u064a\\u0641 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631\\u060c \\u0634\\u0631\\u062d \\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a \\u0627\\u0644\\u0641\\u0631\\u0642 \\u0628\\u064a\\u0646 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633\\u064a \\u0648\\u062c\\u0631\\u0639\\u0627\\u062a \\u0627\\u0644\\u0648\\u062c\\u0628\\u0627\\u062a \\u0648\\u0623\\u0647\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0632\\u0646\\u0629 \\u0628\\u064a\\u0646\\u0647\\u0645\\u0627. \\u062a\\u0645 \\u062a\\u062f\\u0631\\u064a\\u0628 \\u0627\\u0644\\u0623\\u0645 \\u0639\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628 \\u062c\\u0631\\u0639\\u0627\\u062a \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0643\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0643\\u0631\\u0628\\u0648\\u0647\\u064a\\u062f\\u0631\\u0627\\u062a\\u060c \\u0648\\u062a\\u0645 \\u0625\\u0634\\u0631\\u0627\\u0643 \\u0627\\u0644\\u062a\\u0648\\u0623\\u0645\\u062a\\u064a\\u0646 \\u0641\\u064a \\u0641\\u0647\\u0645 \\u062d\\u0627\\u0644\\u062a\\u0647\\u0645\\u0627 \\u0648\\u0643\\u064a\\u0641\\u064a\\u0629 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0628\\u0634\\u0643\\u0644 \\u0635\\u062d\\u064a\\u062d.\"}}]', '[{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '2025-12-26 06:33:44', '2026-02-10 15:38:26'),
(2, '{\"ar\":\" قسم تخطيط صدى قلب الجنين \",\"en\":\"Fetal Cardiology & Echocardiography\"}', 5, '{\"en\":\"<p>The Fetal Echocardiography Unit at Al Nas Hospital provides early and precise diagnosis of congenital heart conditions before birth. Our specialists work closely with maternal-fetal medicine and pediatric cardiology teams to ensure seamless perinatal planning and counseling for families. With advanced imaging, expert care, and a family-centered approach, we support high-risk pregnancies and help improve outcomes for both mother and child.</p>\",\"ar\":\"<p>يُعد قسم تخطيط صدى قلب الجنين بمستشفى الناس مركز إحالة وطنيًا متخصصًا في الاكتشاف المبكر وتشخيص وإدارة أمراض القلب الخِلقية أثناء الحمل. ومنذ تأسيسه في نوفمبر 2023، حقق القسم إنجازات بارزة في مجال التشخيص قبل الولادة والتنسيق العلاجي للحالات المعقدة، مثل انقلاب الشرايين الكبرى (Dextro-Transposition of the Great Arteries)، ونقص تَنَسُّج قوس الأبهر، وحالات القلب أحادي البطين التي تتطلب دعامة للحفاظ على الدورة الدموية المعتمدة على القناة الشريانية.<br>كما يتمتع القسم بخبرة متميزة في التعامل التحفّظي مع اضطرابات نظم القلب داخل الرحم، والكشف عن التحويلات الدموية خارج القلب، بما يضمن تقديم استشارات شاملة للأسر ووضع خطط ولادة ورعاية حول الولادة تتناسب مع كل حالة على حدة. ومن خلال استخدام تقنيات تصوير متقدمة، والتعاون الوثيق مع فرق طب الأم والجنين، وأمراض قلب الأطفال، وجراحة القلب، يقدّم القسم تقييمات عالية الدقة ورعاية متكاملة. وضمن خططه المستقبلية، يستعد البرنامج للتوسع ليشمل مسارات جراحية شديدة التعقيد لحديثي الولادة، مع التخطيط لإدخال دعم الأكسجة الغشائية خارج الجسم بعد الجراحة (ECMO).</p>\"}', '{\"en\":\"<p>The Fetal Echocardiography Department specializes in prenatal cardiac imaging and risk stratification for congenital and fetal functional heart conditions. The unit plays a pivotal role in guiding delivery planning, optimizing perinatal care, and preparing families for possible postnatal interventions.</p><ul><li><p><strong>Diagnostic Fetal Echocardiography:</strong> Comprehensive fetal cardiac imaging, rhythm assessment, blood flow studies, and early detection of congenital anomalies.</p></li><li><p><strong>High-Risk Pregnancy Assessment:</strong> Evaluation of fetuses of diabetic mothers, IVF pregnancies, multiple gestations, and families with genetic predisposition to CHD.</p></li><li><p><strong>Counseling &amp; Family Support Services:</strong> Structured sessions for parents to discuss findings, expected outcomes, treatment options, and delivery planning.</p></li><li><p><strong>Research, Training &amp; Education:</strong> Academic contributions, specialized training programs for cardiologists and sonographers, and participation in multicenter studies on fetal cardiac disease.</p></li></ul>\",\"ar\":\"<p>يختص قسم تخطيط صدى قلب الجنين بالتصوير القلبي قبل الولادة وتحديد درجات الخطورة لأمراض القلب الخِلقية واضطرابات الوظيفة القلبية الجنينية. ويلعب القسم دورًا محوريًا في توجيه خطط الولادة، وتحسين الرعاية المحيطة بالولادة، وتجهيز الأسر لاحتمالات التدخلات العلاجية بعد الولادة.</p><p>·         <strong>تخطيط صدى قلب الجنين التشخيصي:</strong> تصوير شامل لقلب الجنين، وتقييم نظم القلب، ودراسة تدفق الدم، والكشف المبكر عن العيوب الخِلقية.</p><p>·         <strong>تقييم حالات الحمل عالية الخطورة:</strong> فحص أجنّة الأمهات المصابات بالسكري، وحالات الحمل الناتجة عن الإخصاب المساعد (IVF)، والحمل المتعدد، والعائلات ذات الاستعداد الوراثي لأمراض القلب الخِلقية.</p><p>·         <strong>خدمات الاستشارة ودعم الأسرة:</strong> جلسات منظمة لشرح نتائج الفحوصات، والتوقعات المستقبلية، والخيارات العلاجية، وخطط الولادة.</p><p>·         <strong>البحث العلمي والتدريب والتعليم:</strong> الإسهام الأكاديمي، وبرامج تدريب متخصصة لأطباء القلب وفنيي الموجات فوق الصوتية، والمشاركة في دراسات متعددة المراكز حول أمراض القلب الجنينية.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627 \\/ \\u0645\\u062a\\u0627\\u0628\\u0639\\u062a\\u0647\\u0627\"},\"content\":{\"en\":\"<p>We evaluate and manage fetal heart structure, rhythm, and function during pregnancy, including the early detection of congenital heart disease and fetal cardiac abnormalities:<\\/p>\",\"ar\":\"<p>\\u0646\\u0642\\u0648\\u0645 \\u0628\\u062a\\u0642\\u064a\\u064a\\u0645 \\u0648\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0628\\u0646\\u064a\\u0629 \\u0642\\u0644\\u0628 \\u0627\\u0644\\u062c\\u0646\\u064a\\u0646\\u060c \\u0648\\u0646\\u0638\\u0645 \\u0636\\u0631\\u0628\\u0627\\u062a\\u0647\\u060c \\u0648\\u0648\\u0638\\u0627\\u0626\\u0641\\u0647 \\u0623\\u062b\\u0646\\u0627\\u0621 \\u0641\\u062a\\u0631\\u0629 \\u0627\\u0644\\u062d\\u0645\\u0644\\u060c \\u0628\\u0645\\u0627 \\u064a\\u0634\\u0645\\u0644 \\u0627\\u0644\\u0643\\u0634\\u0641 \\u0627\\u0644\\u0645\\u0628\\u0643\\u0631 \\u0639\\u0646 \\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0627\\u0644\\u062e\\u0650\\u0644\\u0642\\u064a\\u0629 \\u0648\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0644\\u062f\\u0649 \\u0627\\u0644\\u062c\\u0646\\u064a\\u0646.<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Structural congenital heart disease (ASD, VSD, hypoplastic right heart syndromes, outflow tract anomalies and aortic arch abnormalities).\",\"ar\":\"\\u2022\\t\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0627\\u0644\\u062e\\u0650\\u0644\\u0642\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0631\\u0643\\u064a\\u0628\\u064a\\u0629 (\\u0645\\u062b\\u0644 \\u0639\\u064a\\u0648\\u0628 \\u0627\\u0644\\u062d\\u0627\\u062c\\u0632 \\u0627\\u0644\\u0623\\u0630\\u064a\\u0646\\u064a \\u0648\\u0627\\u0644\\u0628\\u0637\\u064a\\u0646\\u064a\\u060c \\u0648\\u0645\\u062a\\u0644\\u0627\\u0632\\u0645\\u0627\\u062a \\u0646\\u0642\\u0635 \\u062a\\u0646\\u0633\\u0651\\u062c \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0627\\u0644\\u0623\\u064a\\u0645\\u0646\\u060c \\u0648\\u062a\\u0634\\u0648\\u0647\\u0627\\u062a \\u0645\\u062e\\u0631\\u062c \\u0627\\u0644\\u0634\\u0631\\u0627\\u064a\\u064a\\u0646\\u060c \\u0648\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0642\\u0648\\u0633 \\u0627\\u0644\\u0623\\u0628\\u0647\\u0631).\"}},{\"text\":{\"en\":\"Fetal arrhythmias and conduction abnormalities.\",\"ar\":\"\\u2022\\t\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0646\\u0638\\u0645 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0627\\u0644\\u062c\\u0646\\u064a\\u0646\\u064a\\u0629 \\u0648\\u0645\\u0634\\u0643\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0648\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0643\\u0647\\u0631\\u0628\\u064a.\"}},{\"text\":{\"en\":\"Cardiomyopathies and functional heart disease.\",\"ar\":\"\\u2022\\t\\u0627\\u0639\\u062a\\u0644\\u0627\\u0644\\u0627\\u062a \\u0639\\u0636\\u0644\\u0629 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0648\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0627\\u0644\\u0648\\u0638\\u064a\\u0641\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Secondary cardiac effects of maternal diseases (diabetes, lupus, hypertension).\",\"ar\":\"\\u2022\\t\\u0627\\u0644\\u062a\\u0623\\u062b\\u064a\\u0631\\u0627\\u062a \\u0627\\u0644\\u0642\\u0644\\u0628\\u064a\\u0629 \\u0627\\u0644\\u062b\\u0627\\u0646\\u0648\\u064a\\u0629 \\u0644\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0623\\u0645 (\\u0627\\u0644\\u0633\\u0643\\u0631\\u064a\\u060c \\u0627\\u0644\\u0630\\u0626\\u0628\\u0629 \\u0627\\u0644\\u062d\\u0645\\u0631\\u0627\\u0621\\u060c \\u0627\\u0631\\u062a\\u0641\\u0627\\u0639 \\u0636\\u063a\\u0637 \\u0627\\u0644\\u062f\\u0645).\"}},{\"text\":{\"en\":\"High-output cardiac states.\",\"ar\":\"\\u2022\\t\\u062d\\u0627\\u0644\\u0627\\u062a \\u0632\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0646\\u062a\\u0627\\u062c \\u0627\\u0644\\u0642\\u0644\\u0628\\u064a.\"}},{\"text\":{\"en\":\"Fetal pericardial effusion and hydrops fetalis related to cardiac causes.\",\"ar\":\"\\u2022\\t\\u0627\\u0644\\u0627\\u0646\\u0635\\u0628\\u0627\\u0628 \\u0627\\u0644\\u062a\\u0627\\u0645\\u0648\\u0631\\u064a \\u0627\\u0644\\u062c\\u0646\\u064a\\u0646\\u064a \\u0648\\u0627\\u0644\\u0627\\u0633\\u062a\\u0633\\u0642\\u0627\\u0621 \\u0627\\u0644\\u062c\\u0646\\u064a\\u0646\\u064a \\u0627\\u0644\\u0645\\u0631\\u062a\\u0628\\u0637 \\u0628\\u0623\\u0633\\u0628\\u0627\\u0628 \\u0642\\u0644\\u0628\\u064a\\u0629.\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":45,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u064a\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":\"\\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\"},\"doctors\":[{\"doctor\":54,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649 \"}}]}]', '[{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '[{\"text\":{\"en\":\".\",\"ar\":null}}]', '2025-12-26 06:33:44', '2026-02-04 15:31:29');
INSERT INTO `department_sections` (`id`, `title`, `department_id`, `overview`, `scope_of_unit`, `what_we_treat`, `leadership`, `achievements`, `news`, `created_at`, `updated_at`) VALUES
(3, '{\"ar\":\"قلب الكبار\",\"en\":\"Adult Cardiology\"}', 2, '{\"en\":\"<p>The Adult Catheterization Unit provides advanced diagnostic and interventional cardiac care for adult patients with coronary artery disease and structural heart disease, including adult congenital heart diseases. The unit serves as a cornerstone for minimally invasive procedures, avoiding the need for open-heart surgery whenever possible.</p>\",\"ar\":\"<p>يوفر <strong>وحدة قسطرة القلب للبالغين</strong> رعاية قلبية متقدمة تشخيصية وتداخلية للمرضى البالغين المصابين بأمراض الشرايين التاجية وأمراض القلب البنيوية، بما في ذلك أمراض القلب الخلقية لدى البالغين. تُعد الوحدة ركيزة أساسية للإجراءات قليلة التدخل، مما يقلل الحاجة إلى الجراحة المفتوحة للقلب كلما أمكن ذلك.</p>\"}', '{\"en\":\"<p>The <strong>Adult Cardiac Catheterization Unit</strong> specializes in the evaluation and management of patients presenting with chest pain, acute coronary syndromes, valvular heart disease, and adult congenital heart defects. Utilizing the latest technologies, the team performs advanced diagnostic imaging and interventional procedures to restore normal cardiac function.</p><p><strong>Diagnostic Catheterization:</strong><br>Coronary angiography, hemodynamic studies, intravascular imaging (IVUS, OCT), and fractional flow reserve (FFR) assessment.</p><p><strong>Interventional Cardiology:</strong><br>Balloon angioplasty, implantation of drug-eluting stents, drug-eluting balloons, management of chronic total occlusions (CTO), complex high-risk indicated procedures (CHIP), and advanced plaque modification techniques for calcified lesions, including rotational atherectomy (rotablation) and shockwave intravascular lithotripsy.</p><p><strong>Structural Heart Procedures:</strong><br>Transcatheter aortic valve implantation (TAVI), paravalvular leak (PVL) closure, and septal reduction procedures for hypertrophic obstructive cardiomyopathy (HOCM).</p><p><strong>Adult Congenital Heart Disease Interventions:</strong><br>Closure of defects such as atrial septal defects (ASD/PFO), ventricular septal defects (VSD), and patent ductus arteriosus (PDA); catheter-based stenting for aortic coarctation; balloon pulmonary valvuloplasty for pulmonary valve stenosis; and transcatheter pulmonary valve implantation in cases of pulmonary regurgitation.</p><p><strong>Cardiac Care Unit:</strong><br>Provision of emergency percutaneous coronary intervention (PCI) for ST-elevation myocardial infarction (STEMI – primary PCI) and high-risk NSTEMI cases, intra-procedural monitoring, and post-intervention follow-up to ensure optimal recovery.</p>\",\"ar\":\"<p>تتخصص وحدة قسطرة القلب للبالغين في تقييم وإدارة المرضى الذين يعانون من آلام الصدر، والمتلازمات التاجية الحادة، واضطرابات الصمامات، وتشوهات القلب الخلقية لدى البالغين. باستخدام أحدث التقنيات، يقوم الفريق بإجراء الفحوصات التصويرية التوضيحية والإجراءات التداخلية لاستعادة وظيفة القلب الطبيعية. القسطرة التشخيصية: تصوير الشرايين التاجية (Coronary Angiography)، الدراسات الهيموديناميكية، التصوير داخل الأوعية الدموية (IVUS، OCT)، قياس التدفق الجزئي (FFR). طب القلب التداخلي: توسعة الشرايين بالبالون (Balloon Angioplasty)، زراعة الدعامات المطلقة للأدوية (Drug-Eluting Stents)، البالونات المطلقة للأدوية (Drug-Eluting Balloons)، إدارة الانسداد الكلي المزمن (CTO)، الإجراءات التداخلية المعقدة عالية الخطورة (CHIP)، أدوات متقدمة لإدارة التكلس في اللويحات (Rotablation و Shockwave Therapy). إجراءات القلب الهيكلية: زراعة صمام الأبهر عبر القسطرة (TAVI)، إغلاق التسريبات حول الصمامات (PVL)، وإجراءات تقليل الحاجز في اعتلال عضلة القلب التضخمي الانسدادي (HOCM). إجراءات أمراض القلب الخلقية لدى البالغين: إغلاق العيوب مثل: [عيوب الحاجز الأذيني (ASD/PFO)، عيوب الحاجز البطيني (VSD)، والفتحة الشريانية المستمرة (PDA)]، توسيع تضيق الأبهر بالقسطرة (Coarctation Stenting)، توسيع صمام الرئة بالبالون في مرضى تضيق صمام الرئة، وزراعة صمام رئوي عبر القسطرة في حالات القلس الرئوي. وحدة العناية بالقلب: إجراء التدخل التاجي الطارئ (PCI) في حالات احتشاء العضلة القلبية ST-elevation (STEMI – Primary PCI) وحالات NSTEMI عالية الخطورة، المراقبة أثناء الإجراءات، والمتابعة بعد التدخل لضمان التعافي.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\" \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627 \"},\"content\":{\"en\":\"<p><strong>Adult Cath (Adults \\u2013 Heart &amp; Vascular Procedures)<\\/strong><\\/p><p><strong>We help adults who have problems with their heart arteries, heart valves, or blood vessels in the body. Conditions include:<\\/strong><\\/p>\",\"ar\":\"<p><strong>\\u0648\\u062d\\u062f\\u0629 \\u0642\\u0633\\u0637\\u0631\\u0629 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0644\\u0644\\u0628\\u0627\\u0644\\u063a\\u064a\\u0646 (\\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0648\\u0627\\u0644\\u0623\\u0648\\u0639\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0645\\u0648\\u064a\\u0629 \\u0644\\u0644\\u0643\\u0628\\u0627\\u0631)<\\/strong><\\/p><p>\\u0646\\u0642\\u062f\\u0645 \\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0644\\u0644\\u0628\\u0627\\u0644\\u063a\\u064a\\u0646 \\u0627\\u0644\\u0630\\u064a\\u0646 \\u064a\\u0639\\u0627\\u0646\\u0648\\u0646 \\u0645\\u0646 \\u0645\\u0634\\u0627\\u0643\\u0644 \\u0641\\u064a \\u0634\\u0631\\u0627\\u064a\\u064a\\u0646 \\u0627\\u0644\\u0642\\u0644\\u0628\\u060c \\u0635\\u0645\\u0627\\u0645\\u0627\\u062a \\u0627\\u0644\\u0642\\u0644\\u0628\\u060c \\u0623\\u0648 \\u0627\\u0644\\u0623\\u0648\\u0639\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0645\\u0648\\u064a\\u0629 \\u0641\\u064a \\u0627\\u0644\\u062c\\u0633\\u0645. \\u0648\\u062a\\u0634\\u0645\\u0644 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0645\\u0627 \\u064a\\u0644\\u064a:<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Blocked or narrowed heart arteries (which can cause chest pain or heart attacks)\",\"ar\":\"\\u0627\\u0646\\u0633\\u062f\\u0627\\u062f \\u0623\\u0648 \\u0636\\u064a\\u0642 \\u0634\\u0631\\u0627\\u064a\\u064a\\u0646 \\u0627\\u0644\\u0642\\u0644\\u0628 (\\u0627\\u0644\\u0630\\u064a \\u0642\\u062f \\u064a\\u0633\\u0628\\u0628 \\u0622\\u0644\\u0627\\u0645 \\u0627\\u0644\\u0635\\u062f\\u0631 \\u0623\\u0648 \\u0627\\u0644\\u0646\\u0648\\u0628\\u0627\\u062a \\u0627\\u0644\\u0642\\u0644\\u0628\\u064a\\u0629)\"}},{\"text\":{\"en\":\"Valve problems (such as valves that are too tight or that leak)\",\"ar\":\"\\u0645\\u0634\\u0627\\u0643\\u0644 \\u0627\\u0644\\u0635\\u0645\\u0627\\u0645\\u0627\\u062a (\\u0645\\u062b\\u0644 \\u0627\\u0644\\u0635\\u0645\\u0627\\u0645\\u0627\\u062a \\u0627\\u0644\\u0636\\u064a\\u0642\\u0629 \\u062c\\u062f\\u064b\\u0627 \\u0623\\u0648 \\u0627\\u0644\\u0645\\u062a\\u0633\\u0631\\u0628\\u0629)\"}},{\"text\":{\"en\":\"Weak heart pumping or heart failure needing support with devices\",\"ar\":\"\\u0636\\u0639\\u0641 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0623\\u0648 \\u0641\\u0634\\u0644 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0627\\u0644\\u0630\\u064a \\u064a\\u062d\\u062a\\u0627\\u062c \\u0625\\u0644\\u0649 \\u062f\\u0639\\u0645 \\u0628\\u0623\\u062c\\u0647\\u0632\\u0629 \\u0645\\u0633\\u0627\\u0639\\u062f\\u0629\"}},{\"text\":{\"en\":\"Aneurysms of the aorta (bulges in large blood vessels)\",\"ar\":\"\\u062a\\u0645\\u062f\\u062f \\u0627\\u0644\\u0623\\u0648\\u0639\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0645\\u0648\\u064a\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0634\\u0631\\u064a\\u0627\\u0646 \\u0627\\u0644\\u0623\\u0628\\u0647\\u0631 (\\u0627\\u0646\\u062a\\u0641\\u0627\\u062e\\u0627\\u062a \\u0641\\u064a \\u0627\\u0644\\u0623\\u0648\\u0639\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0645\\u0648\\u064a\\u0629 \\u0627\\u0644\\u0643\\u0628\\u064a\\u0631\\u0629)\"}},{\"text\":{\"en\":\"Poor circulation in arms or legs\",\"ar\":\"\\u0636\\u0639\\u0641 \\u0627\\u0644\\u062f\\u0648\\u0631\\u0629 \\u0627\\u0644\\u062f\\u0645\\u0648\\u064a\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0630\\u0631\\u0627\\u0639\\u064a\\u0646 \\u0623\\u0648 \\u0627\\u0644\\u0633\\u0627\\u0642\\u064a\\u0646\"}},{\"text\":{\"en\":\"Carotid artery disease or blocked neck vessels that increase stroke risk\",\"ar\":\"\\u0645\\u0631\\u0636 \\u0627\\u0644\\u0634\\u0631\\u064a\\u0627\\u0646 \\u0627\\u0644\\u0633\\u0628\\u0627\\u062a\\u064a \\u0623\\u0648 \\u0627\\u0646\\u0633\\u062f\\u0627\\u062f \\u0627\\u0644\\u0623\\u0648\\u0639\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0645\\u0648\\u064a\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0631\\u0642\\u0628\\u0629 \\u0627\\u0644\\u0630\\u064a \\u064a\\u0632\\u064a\\u062f \\u0645\\u0646 \\u062e\\u0637\\u0631 \\u0627\\u0644\\u0633\\u0643\\u062a\\u0629 \\u0627\\u0644\\u062f\\u0645\\u0627\\u063a\\u064a\\u0629\"}},{\"text\":{\"en\":\"Blood clots in the body or brain\",\"ar\":\"\\u062c\\u0644\\u0637\\u0627\\u062a \\u0627\\u0644\\u062f\\u0645 \\u0641\\u064a \\u0627\\u0644\\u062c\\u0633\\u0645 \\u0623\\u0648 \\u0627\\u0644\\u062f\\u0645\\u0627\\u063a\"}},{\"text\":{\"en\":\"Chronic total occlusions (fully blocked arteries)\",\"ar\":\"\\u0627\\u0644\\u0627\\u0646\\u0633\\u062f\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0632\\u0645\\u0646\\u0629 (\\u0627\\u0644\\u0634\\u0631\\u0627\\u064a\\u064a\\u0646 \\u0627\\u0644\\u0645\\u0633\\u062f\\u0648\\u062f\\u0629 \\u0628\\u0627\\u0644\\u0643\\u0627\\u0645\\u0644)\"}},{\"text\":{\"en\":\"Fluid around the heart (pericardial effusion)\",\"ar\":\"\\u062a\\u062c\\u0645\\u0639 \\u0627\\u0644\\u0633\\u0648\\u0627\\u0626\\u0644 \\u062d\\u0648\\u0644 \\u0627\\u0644\\u0642\\u0644\\u0628 (\\u0627\\u0644\\u0627\\u0646\\u0635\\u0628\\u0627\\u0628 \\u0627\\u0644\\u062a\\u0627\\u0645\\u0648\\u0631\\u064a)\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":5,\"doctor_title\":{\"en\":\"consultant\",\"ar\":\" \\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u064a\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":null},\"doctors\":[{\"doctor\":11,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":7,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":6,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":9,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]}]', '[{\"text\":{\"en\":\"Documented high success rates in PCI and structural interventions.\",\"ar\":\"\\u062a\\u062d\\u0642\\u064a\\u0642 \\u0645\\u0639\\u062f\\u0644\\u0627\\u062a \\u0646\\u062c\\u0627\\u062d \\u0645\\u0648\\u062b\\u0642\\u0629 \\u0645\\u0631\\u062a\\u0641\\u0639\\u0629 \\u0641\\u064a \\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0627\\u0644\\u062a\\u062f\\u062e\\u0644 \\u0627\\u0644\\u062a\\u0627\\u062c\\u064a (PCI) \\u0648\\u0627\\u0644\\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0627\\u0644\\u0647\\u064a\\u0643\\u0644\\u064a\\u0629 \\u0644\\u0644\\u0642\\u0644\\u0628.\"}},{\"text\":{\"en\":\"PCI Protocol signature with Egypt Ministry of Health\",\"ar\":\"\\u062a\\u0648\\u0642\\u064a\\u0639 \\u0628\\u0631\\u0648\\u062a\\u0648\\u0643\\u0648\\u0644 \\u0627\\u0644\\u062a\\u062f\\u062e\\u0644 \\u0627\\u0644\\u062a\\u0627\\u062c\\u064a (PCI) \\u0645\\u0639 \\u0648\\u0632\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0635\\u062d\\u0629 \\u0627\\u0644\\u0645\\u0635\\u0631\\u064a\\u0629\"}},{\"text\":{\"en\":\"Annual increase of over 30% in catheterization procedures.\",\"ar\":\"\\u0632\\u064a\\u0627\\u062f\\u0629 \\u0633\\u0646\\u0648\\u064a\\u0629 \\u0628\\u0623\\u0643\\u062b\\u0631 \\u0645\\u0646 30\\u066a \\u0641\\u064a \\u0639\\u062f\\u062f \\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0627\\u0644\\u0642\\u0633\\u0637\\u0631\\u0629.\"}},{\"text\":{\"en\":\"Reduced door-to-balloon times in STEMI cases, meeting international benchmarks.\",\"ar\":\"\\u062a\\u0642\\u0644\\u064a\\u0644 \\u0627\\u0644\\u0648\\u0642\\u062a \\u0645\\u0646 \\u062f\\u062e\\u0648\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0625\\u0644\\u0649 \\u062a\\u0648\\u0633\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0631\\u064a\\u0627\\u0646 \\u0628\\u0627\\u0644\\u0628\\u0627\\u0644\\u0648\\u0646 \\u0641\\u064a \\u062d\\u0627\\u0644\\u0627\\u062a STEMI\\u060c \\u0628\\u0645\\u0627 \\u064a\\u062a\\u0648\\u0627\\u0641\\u0642 \\u0645\\u0639 \\u0627\\u0644\\u0645\\u0639\\u0627\\u064a\\u064a\\u0631 \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Patients\\u2019 testimonials highlighting rapid recovery and improved quality of life.\",\"ar\":\"\\u0634\\u0647\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0628\\u0631\\u0632 \\u0633\\u0631\\u0639\\u0629 \\u0627\\u0644\\u062a\\u0639\\u0627\\u0641\\u064a \\u0648\\u062a\\u062d\\u0633\\u0646 \\u062c\\u0648\\u062f\\u0629 \\u0627\\u0644\\u062d\\u064a\\u0627\\u0629.\"}},{\"text\":{\"en\":\"Participation in national community cardiac screening and emergency response convoys.\",\"ar\":\"\\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0641\\u064a \\u062d\\u0645\\u0644\\u0627\\u062a \\u0627\\u0644\\u0641\\u062d\\u0635 \\u0627\\u0644\\u0642\\u0644\\u0628\\u064a \\u0627\\u0644\\u0645\\u062c\\u062a\\u0645\\u0639\\u064a \\u0627\\u0644\\u0648\\u0637\\u0646\\u064a\\u0629 \\u0648\\u0642\\u0648\\u0627\\u0641\\u0644 \\u0627\\u0644\\u0627\\u0633\\u062a\\u062c\\u0627\\u0628\\u0629 \\u0627\\u0644\\u0637\\u0627\\u0631\\u0626\\u0629.\"}}]', '[{\"text\":{\"en\":\"Adoption of new technologies (drug-coated balloons, shockwave lithotripsy).\",\"ar\":\"\\u0627\\u0639\\u062a\\u0645\\u0627\\u062f \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u062d\\u062f\\u064a\\u062b\\u0629 (\\u0627\\u0644\\u0628\\u0627\\u0644\\u0648\\u0646\\u0627\\u062a \\u0627\\u0644\\u0645\\u0637\\u0644\\u064a\\u0629 \\u0628\\u0627\\u0644\\u0623\\u062f\\u0648\\u064a\\u0629\\u060c \\u062a\\u0643\\u0633\\u064a\\u0631 \\u0627\\u0644\\u062d\\u0635\\u064a\\u0627\\u062a \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0645\\u0648\\u062c\\u0627\\u062a \\u0627\\u0644\\u0635\\u062f\\u0645\\u0629 \\u2013 Shockwave Lithotripsy).\"}},{\"text\":{\"en\":\"Announcement of upcoming interventional cardiology symposia.\",\"ar\":\"\\u0627\\u0644\\u0625\\u0639\\u0644\\u0627\\u0646 \\u0639\\u0646 \\u0627\\u0644\\u0646\\u062f\\u0648\\u0627\\u062a \\u0627\\u0644\\u0642\\u0627\\u062f\\u0645\\u0629 \\u0641\\u064a \\u0645\\u062c\\u0627\\u0644 \\u0637\\u0628 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0627\\u0644\\u062a\\u062f\\u0627\\u062e\\u0644\\u064a.\"}},{\"text\":{\"en\":\"Community campaigns for heart attack awareness and prevention.\",\"ar\":\"\\u062d\\u0645\\u0644\\u0627\\u062a \\u0645\\u062c\\u062a\\u0645\\u0639\\u064a\\u0629 \\u0644\\u0644\\u062a\\u0648\\u0639\\u064a\\u0629 \\u0628\\u0627\\u0644\\u0646\\u0648\\u0628\\u0627\\u062a \\u0627\\u0644\\u0642\\u0644\\u0628\\u064a\\u0629 \\u0648\\u0633\\u0628\\u0644 \\u0627\\u0644\\u0648\\u0642\\u0627\\u064a\\u0629 \\u0645\\u0646\\u0647\\u0627\"}}]', '2025-12-26 06:33:44', '2026-02-05 13:23:19'),
(4, '{\"en\":\"Burn, Plastic & Reconstructive Surgery\",\"ar\":\" قسم الحروق وجراجة التجميل\"}', 7, '{\"en\":\"<p>The Burn Unit at Al Nas Hospital is a specialized center dedicated to the comprehensive management of patients with burn injuries, from acute emergency care to long-term rehabilitation. With a multidisciplinary team and state-of-the-art facilities, the unit provides life-saving interventions, advanced wound management, surgical reconstruction, and psychosocial and nutritional support. The unit’s mission is to deliver compassionate, evidence-based care that restores health, function, and quality of life for patients affected by burn trauma.</p>\",\"ar\":\"<p>تُعد وحدة الحروق بمستشفى الناس مركزًا متخصصًا في الرعاية الشاملة لمرضى إصابات الحروق، حيث تقدم خدمات متكاملة تبدأ من التدخلات الطارئة والعناية الحرجة وصولًا إلى إعادة التأهيل طويل الأمد. وتعتمد الوحدة على فريق طبي متعدد التخصصات مدعوم بأحدث التجهيزات الطبية، لتقديم تدخلات منقذة للحياة، وإدارة متقدمة للجروح، وجراحات ترميمية، إلى جانب الدعم النفسي والتغذوي.</p><p>وتتمثل رسالة الوحدة في تقديم رعاية إنسانية قائمة على الأدلة العلمية، بما يساهم في استعادة صحة المرضى ووظائفهم وجودة حياتهم بعد التعرض لإصابات الحروق.</p>\"}', '{\"en\":\"<p>The unit provides full-spectrum burn care, integrating medical, surgical, rehabilitative, and psychological support. Services extend from critical care management in the early stages to reconstructive surgery and long-term rehabilitation, ensuring patients receive interdisciplinary continuous care.</p><ul><li><p><strong>Acute Burn Care &amp; Emergency Response</strong>: Initial stabilization, airway management, and fluid resuscitation for all burn types and patient age groups.</p></li><li><p><strong>Burn Intensive Care Management</strong>: Continuous monitoring, ventilatory support, and resuscitation for critically ill burn patients.</p></li><li><p><strong>Anesthesia &amp; Sedation</strong>: Pain relief, sedation, and perioperative management tailored to burn care procedures.</p></li><li><p><strong>Bronchoscopy &amp; Inhalation Injury Care</strong>: Specialized interventions for airway assessment and treatment of inhalation injuries.</p></li><li><p><strong>Surgical &amp; Reconstructive Services</strong>: Excision, escharotomy, fasciotomy, skin grafts, flap coverage, contracture release, and reconstructive procedures to restore function and appearance.</p></li><li><p><strong>Wound Care &amp; Infection Control</strong>: Advanced dressings, biologic and synthetic skin substitutes, negative pressure wound therapy, and strict infection prevention protocols.</p></li><li><p><strong>Rehabilitation &amp; Physiotherapy</strong>: Physical and occupational therapy, mobility programs, and scar management to restore independence.</p></li><li><p><strong>Psychological &amp; Social Support</strong>: Counseling, peer support, and reintegration programs for patients and families coping with burn trauma.</p></li><li><p><strong>Nutritional Support &amp; Follow-Up</strong>: Tailored dietary management to support healing, recovery, and long-term health.</p></li></ul>\",\"ar\":\"<p>تقدم الوحدة رعاية متكاملة لمرضى الحروق، من خلال دمج الخدمات الطبية والجراحية وإعادة التأهيل والدعم النفسي. وتمتد هذه الرعاية من المراحل الحرجة الأولى إلى الجراحات الترميمية وإعادة التأهيل طويل الأمد، بما يضمن استمرارية الرعاية متعددة التخصصات لكل مريض.</p><p></p><p>مهام كل قسم</p><p></p><p>الرعاية الحادة للحروق والاستجابة الطارئة: تثبيت الحالة العامة، تأمين مجرى الهواء، وإنعاش السوائل لجميع أنواع الحروق ولمختلف الفئات العمرية.</p><p></p><p>العناية المركزة لمرضى الحروق: مراقبة مستمرة، دعم تنفسي، وإنعاش مكثف للحالات الحرجة.</p><p></p><p>التخدير والتسكين: تسكين الألم، التخدير، والرعاية المحيطة بالإجراءات الجراحية الخاصة بالحروق.</p><p></p><p>منظار الشعب الهوائية وإصابات الاستنشاق: تقييم وعلاج إصابات مجرى الهواء الناتجة عن استنشاق الدخان أو الغازات.</p><p></p><p>الخدمات الجراحية والترميمية: استئصال الأنسجة التالفة، شق القشور، شق اللفافات، ترقيع الجلد، تغطية السدائل، علاج التقلصات، والجراحات الترميمية لاستعادة الوظيفة والمظهر.</p><p></p><p>رعاية الجروح ومكافحة العدوى: استخدام الضمادات المتقدمة، بدائل الجلد الحيوية والصناعية، العلاج بالضغط السلبي، وتطبيق بروتوكولات صارمة للوقاية من العدوى.</p><p></p><p>إعادة التأهيل والعلاج الطبيعي: العلاج الطبيعي والوظيفي، برامج الحركة، وعلاج الندبات لاستعادة الاستقلالية.</p><p></p><p>الدعم النفسي والاجتماعي: جلسات إرشاد، دعم نفسي، وبرامج إعادة الاندماج للمصابين وأسرهم.</p><p></p><p>الدعم التغذوي والمتابعة: برامج تغذية مخصصة لدعم الالتئام والتعافي والصحة على المدى الطويل.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627\"},\"content\":{\"en\":\"<p>We provide comprehensive care for patients with burn injuries, delivering acute resuscitation, critical care, surgical reconstruction, advanced wound management, and multidisciplinary rehabilitation to restore function, prevent complications, and support long-term recovery:<\\/p>\",\"ar\":\"<p>\\u0646\\u0642\\u062f\\u0645 \\u0631\\u0639\\u0627\\u064a\\u0629 \\u0645\\u062a\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0645\\u0631\\u0636\\u0649 \\u0625\\u0635\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u062d\\u0631\\u0648\\u0642\\u060c \\u062a\\u0634\\u0645\\u0644 \\u0627\\u0644\\u0625\\u0646\\u0639\\u0627\\u0634 \\u0627\\u0644\\u062d\\u0627\\u062f\\u060c \\u0648\\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0627\\u0644\\u062d\\u0631\\u062c\\u0629\\u060c \\u0648\\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u062a\\u0631\\u0645\\u064a\\u0645\\u064a\\u0629\\u060c \\u0648\\u0627\\u0644\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u0629 \\u0644\\u0644\\u062c\\u0631\\u0648\\u062d\\u060c \\u0648\\u0625\\u0639\\u0627\\u062f\\u0629 \\u0627\\u0644\\u062a\\u0623\\u0647\\u064a\\u0644 \\u0645\\u062a\\u0639\\u062f\\u062f\\u0629 \\u0627\\u0644\\u062a\\u062e\\u0635\\u0635\\u0627\\u062a\\u060c \\u0628\\u0647\\u062f\\u0641 \\u0627\\u0633\\u062a\\u0639\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0648\\u0638\\u064a\\u0641\\u0629\\u060c \\u0648\\u0627\\u0644\\u0648\\u0642\\u0627\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0636\\u0627\\u0639\\u0641\\u0627\\u062a\\u060c \\u0648\\u062f\\u0639\\u0645 \\u0627\\u0644\\u062a\\u0639\\u0627\\u0641\\u064a \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u062f\\u0649 \\u0627\\u0644\\u0637\\u0648\\u064a\\u0644.<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Thermal burns (flame, scald, contact)\",\"ar\":\"\\u0627\\u0644\\u062d\\u0631\\u0648\\u0642 \\u0627\\u0644\\u062d\\u0631\\u0627\\u0631\\u064a\\u0629 (\\u0627\\u0644\\u0646\\u0627\\u062a\\u062c\\u0629 \\u0639\\u0646 \\u0627\\u0644\\u0644\\u0647\\u0628\\u060c \\u0627\\u0644\\u0633\\u0648\\u0627\\u0626\\u0644 \\u0627\\u0644\\u0633\\u0627\\u062e\\u0646\\u0629\\u060c \\u0623\\u0648 \\u0627\\u0644\\u062a\\u0644\\u0627\\u0645\\u0633 \\u0627\\u0644\\u0645\\u0628\\u0627\\u0634\\u0631)\"}},{\"text\":{\"en\":\"Chemical burns\",\"ar\":\"\\u0627\\u0644\\u062d\\u0631\\u0648\\u0642 \\u0627\\u0644\\u0643\\u064a\\u0645\\u064a\\u0627\\u0626\\u064a\\u0629\"}},{\"text\":{\"en\":\"Electrical burns\",\"ar\":\"\\u0627\\u0644\\u062d\\u0631\\u0648\\u0642 \\u0627\\u0644\\u0643\\u0647\\u0631\\u0628\\u0627\\u0626\\u064a\\u0629\"}},{\"text\":{\"en\":\"Inhalation injuries\",\"ar\":\"\\u0625\\u0635\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0627\\u0633\\u062a\\u0646\\u0634\\u0627\\u0642\"}},{\"text\":{\"en\":\"Post-burn contractures and deformities\",\"ar\":\"\\u0627\\u0644\\u062a\\u0642\\u0644\\u0635\\u0627\\u062a \\u0648\\u0627\\u0644\\u062a\\u0634\\u0648\\u0647\\u0627\\u062a \\u0645\\u0627 \\u0628\\u0639\\u062f \\u0627\\u0644\\u062d\\u0631\\u0648\\u0642\"}},{\"text\":{\"en\":\"Burn-related infections and sepsis\",\"ar\":\"\\u0627\\u0644\\u0639\\u062f\\u0648\\u0649 \\u0627\\u0644\\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0627\\u0644\\u062d\\u0631\\u0648\\u0642 \\u0648\\u0627\\u0644\\u0625\\u0646\\u062a\\u0627\\u0646 (\\u062a\\u0639\\u0641\\u0646 \\u0627\\u0644\\u062f\\u0645)\"}},{\"text\":{\"en\":\"Long-term scar and cosmetic deformities\",\"ar\":\"\\u0627\\u0644\\u0646\\u062f\\u0628\\u0627\\u062a \\u0637\\u0648\\u064a\\u0644\\u0629 \\u0627\\u0644\\u0623\\u0645\\u062f \\u0648\\u0627\\u0644\\u062a\\u0634\\u0648\\u0647\\u0627\\u062a \\u0627\\u0644\\u062a\\u062c\\u0645\\u064a\\u0644\\u064a\\u0629\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":68,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":16,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":null},\"doctors\":[]}]', '[{\"text\":{\"en\":\".\",\"ar\":\"88 ar\"}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '[]', '2025-12-26 06:33:44', '2026-02-05 13:44:55'),
(6, '{\"en\":\"Cardiac Surgery\",\"ar\":\"قسم جراحة القلب\"}', 2, '{\"en\":\"<p>The Cardiac Surgery Department provides advanced surgical care for both adult and pediatric patients with congenital and acquired heart diseases. The department delivers excellence through a multidisciplinary approach, integrating surgical expertise, perfusion technology, and critical care. It is committed to ensuring the highest standards of safety, precision, and patient-centered outcomes.</p>\",\"ar\":\"<p><strong>يقدم قسم جراحة القلب بمستشفى الناس رعاية جراحية متقدمة للبالغين والأطفال المصابين بأمراض القلب الخَلقية والمكتسبة. ويعتمد القسم على نهج متعدد التخصصات يجمع بين الخبرة الجراحية المتقدمة، وتقنيات الإرواء الدموي الحديثة، والرعاية الحرجة، بما يضمن أعلى معايير الأمان والدقة، مع التركيز الكامل على تحقيق أفضل النتائج العلاجية التي تتمحور حول المريض.</strong></p>\"}', '{\"en\":\"<p>The Cardiac Surgery Department delivers comprehensive operative care for patients with a wide range of congenital and acquired heart conditions, from routine procedures to highly complex and high-risk cases. Through close collaboration between surgeons, anesthesiologists, perfusionists and rehabilitation teams, the department ensures seamless care across the entire surgical pathway. Emphasis is placed on precision, safety, and innovation, with integrated perioperative planning, advanced intraoperative support, and structured postoperative recovery programs designed to optimize outcomes and support long-term cardiac health.</p>\",\"ar\":\"<p>يقدّم قسم جراحة القلب رعاية جراحية شاملة للمرضى المصابين بمجموعة واسعة من أمراض القلب الخلقية والمكتسبة، بدءًا من الإجراءات الروتينية وصولاً إلى الحالات عالية التعقيد وعالية المخاطر. من خلال التعاون الوثيق بين الجراحين وأطباء التخدير وفنيي الضخ وفرق التأهيل، يضمن القسم تقديم رعاية متكاملة على مدار كامل مسار العملية الجراحية. يُركز القسم على الدقة والسلامة والابتكار، مع تخطيط محيطي متكامل قبل العملية، ودعم متقدّم أثناء العملية، وبرامج منظمة للتعافي بعد الجراحة تهدف إلى تحسين النتائج ودعم صحة القلب على المدى الطويل.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627\"},\"content\":{\"en\":\"<p>Adult Cath (Adults \\u2013 Heart &amp; Vascular Procedures) We help adults who have problems with their heart arteries, heart valves, or blood vessels in the body. Conditions include:<\\/p>\",\"ar\":\"<p>\\u0646\\u0633\\u0627\\u0639\\u062f \\u0627\\u0644\\u0628\\u0627\\u0644\\u063a\\u064a\\u0646 \\u0627\\u0644\\u0630\\u064a\\u0646 \\u064a\\u0639\\u0627\\u0646\\u0648\\u0646 \\u0645\\u0646 \\u0645\\u0634\\u0627\\u0643\\u0644 \\u0641\\u064a \\u0634\\u0631\\u0627\\u064a\\u064a\\u0646 \\u0627\\u0644\\u0642\\u0644\\u0628\\u060c \\u0635\\u0645\\u0627\\u0645\\u0627\\u062a \\u0627\\u0644\\u0642\\u0644\\u0628\\u060c \\u0623\\u0648 \\u0627\\u0644\\u0623\\u0648\\u0639\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0645\\u0648\\u064a\\u0629 \\u0641\\u064a \\u0627\\u0644\\u062c\\u0633\\u0645. \\u0648\\u062a\\u0634\\u0645\\u0644 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0645\\u0627 \\u064a\\u0644\\u064a<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Fixing birth defects in children \\u2013 helping kids with congenital heart problems live normal, healthy lives.\",\"ar\":\"\\u0625\\u0635\\u0644\\u0627\\u062d \\u0627\\u0644\\u0639\\u064a\\u0648\\u0628 \\u0627\\u0644\\u062e\\u0644\\u0642\\u064a\\u0629 \\u0639\\u0646\\u062f \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644 \\u2013 \\u0645\\u0633\\u0627\\u0639\\u062f\\u0629 \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0635\\u0627\\u0628\\u064a\\u0646 \\u0628\\u0645\\u0634\\u0643\\u0644\\u0627\\u062a \\u0642\\u0644\\u0628\\u064a\\u0629 \\u062e\\u0644\\u0642\\u064a\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0639\\u064a\\u0634 \\u062d\\u064a\\u0627\\u0629 \\u0637\\u0628\\u064a\\u0639\\u064a\\u0629 \\u0648\\u0635\\u062d\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Improving blood flow \\u2013 by opening blocked arteries to reduce chest pain and prevent heart attacks.\",\"ar\":\"\\u062a\\u062d\\u0633\\u064a\\u0646 \\u062a\\u062f\\u0641\\u0642 \\u0627\\u0644\\u062f\\u0645 \\u2013 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0641\\u062a\\u062d \\u0627\\u0644\\u0634\\u0631\\u0627\\u064a\\u064a\\u0646 \\u0627\\u0644\\u0645\\u0633\\u062f\\u0648\\u062f\\u0629 \\u0644\\u062a\\u062e\\u0641\\u064a\\u0641 \\u0622\\u0644\\u0627\\u0645 \\u0627\\u0644\\u0635\\u062f\\u0631 \\u0648\\u0627\\u0644\\u0648\\u0642\\u0627\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0646\\u0648\\u0628\\u0627\\u062a \\u0627\\u0644\\u0642\\u0644\\u0628\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Repairing or replacing heart valves \\u2013 so the heart can pump blood more effectively.\",\"ar\":\"\\u0625\\u0635\\u0644\\u0627\\u062d \\u0623\\u0648 \\u0627\\u0633\\u062a\\u0628\\u062f\\u0627\\u0644 \\u0635\\u0645\\u0627\\u0645\\u0627\\u062a \\u0627\\u0644\\u0642\\u0644\\u0628 \\u2013 \\u0644\\u062a\\u0645\\u0643\\u064a\\u0646 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0645\\u0646 \\u0636\\u062e \\u0627\\u0644\\u062f\\u0645 \\u0628\\u0634\\u0643\\u0644 \\u0623\\u0643\\u062b\\u0631 \\u0641\\u0639\\u0627\\u0644\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Strengthening weak hearts \\u2013 surgeries can help patients with heart failure live longer and better.\",\"ar\":\"\\u062a\\u0642\\u0648\\u064a\\u0629 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0627\\u0644\\u0636\\u0639\\u064a\\u0641 \\u2013 \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0644\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0645\\u0633\\u0627\\u0639\\u062f\\u0629 \\u0645\\u0631\\u0636\\u0649 \\u0641\\u0634\\u0644 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0639\\u064a\\u0634 \\u0644\\u0641\\u062a\\u0631\\u0629 \\u0623\\u0637\\u0648\\u0644 \\u0648\\u0628\\u062c\\u0648\\u062f\\u0629 \\u062d\\u064a\\u0627\\u0629 \\u0623\\u0641\\u0636\\u0644.\"}},{\"text\":{\"en\":\"Correcting rhythm problems \\u2013 certain procedures help the heart beat regularly.\",\"ar\":\"\\u062a\\u0635\\u062d\\u064a\\u062d \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0646\\u0638\\u0645 \\u0627\\u0644\\u0642\\u0644\\u0628\\u064a \\u2013 \\u0628\\u0639\\u0636 \\u0627\\u0644\\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u062a\\u0633\\u0627\\u0639\\u062f \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0646\\u0628\\u0636 \\u0628\\u0634\\u0643\\u0644 \\u0645\\u0646\\u062a\\u0638\\u0645.\"}},{\"text\":{\"en\":\"Relieving breathing and chest problems \\u2013 some thoracic surgeries improve lung and chest wealth.\",\"ar\":\"\\u062a\\u062e\\u0641\\u064a\\u0641 \\u0645\\u0634\\u0627\\u0643\\u0644 \\u0627\\u0644\\u062a\\u0646\\u0641\\u0633 \\u0648\\u0627\\u0644\\u0635\\u062f\\u0631 \\u2013 \\u0628\\u0639\\u0636 \\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0635\\u062f\\u0631 \\u062a\\u0639\\u0645\\u0644 \\u0639\\u0644\\u0649 \\u062a\\u062d\\u0633\\u064a\\u0646 \\u0635\\u062d\\u0629 \\u0627\\u0644\\u0631\\u0626\\u062a\\u064a\\u0646 \\u0648\\u0627\\u0644\\u0635\\u062f\\u0631.\"}},{\"text\":{\"en\":\"Giving patients a new chance at life \\u2013 many people feel stronger, more active, and free of symptoms after recovery.\",\"ar\":\"\\u0645\\u0646\\u062d \\u0627\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0641\\u0631\\u0635\\u0629 \\u062c\\u062f\\u064a\\u062f\\u0629 \\u0644\\u0644\\u062d\\u064a\\u0627\\u0629 \\u2013 \\u064a\\u0634\\u0639\\u0631 \\u0627\\u0644\\u0643\\u062b\\u064a\\u0631\\u0648\\u0646 \\u0628\\u0627\\u0644\\u0642\\u0648\\u0629 \\u0648\\u0627\\u0644\\u0646\\u0634\\u0627\\u0637 \\u0623\\u0643\\u062b\\u0631 \\u0648\\u062e\\u0644\\u0648\\u0651\\u0647\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0639\\u0631\\u0627\\u0636 \\u0628\\u0639\\u062f \\u0627\\u0644\\u062a\\u0639\\u0627\\u0641\\u064a.\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":46,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649 \"}}]},{\"title\":{\"en\":\"Team\",\"ar\":null},\"doctors\":[{\"doctor\":50,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":51,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":52,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":53,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]}]', '[{\"text\":{\"en\":\"Documented high survival and recovery rates.\",\"ar\":\"\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0645\\u0639\\u062f\\u0644\\u0627\\u062a \\u0628\\u0642\\u0627\\u0621 \\u0648\\u062a\\u0639\\u0627\\u0641\\u064a \\u0645\\u0631\\u062a\\u0641\\u0639\\u0629.\"}},{\"text\":{\"en\":\"Annual increase in surgical volume and success.\",\"ar\":\"\\u0632\\u064a\\u0627\\u062f\\u0629 \\u0633\\u0646\\u0648\\u064a\\u0629 \\u0641\\u064a \\u062d\\u062c\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u064a\\u0629 \\u0648\\u0646\\u0633\\u0628 \\u0627\\u0644\\u0646\\u062c\\u0627\\u062d.\"}},{\"text\":{\"en\":\"Live case broadcasting for global medical education.\",\"ar\":\"\\u0628\\u062b \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u064a\\u0629 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0644\\u0623\\u063a\\u0631\\u0627\\u0636 \\u0627\\u0644\\u062a\\u0639\\u0644\\u064a\\u0645 \\u0627\\u0644\\u0637\\u0628\\u064a \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a.\"}},{\"text\":{\"en\":\"Participation in international humanitarian medical missions.\",\"ar\":\"\\u0627\\u0644\\u0645\\u0634\\u0627\\u0631\\u0643\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0628\\u0639\\u062b\\u0627\\u062a \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0627\\u0646\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Recognition for innovation in perfusion and surgical techniques.\",\"ar\":\"\\u0627\\u0644\\u0627\\u0639\\u062a\\u0631\\u0627\\u0641 \\u0628\\u0627\\u0644\\u0627\\u0628\\u062a\\u0643\\u0627\\u0631 \\u0641\\u064a \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0627\\u0644\\u0636\\u062e \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632\\u064a \\u0648\\u0627\\u0644\\u0623\\u0633\\u0627\\u0644\\u064a\\u0628 \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u064a\\u0629.\"}}]', '[{\"text\":{\"en\":\"Outreach Clinical programs to expand access to surgical care.\",\"ar\":\"\\u0628\\u0631\\u0627\\u0645\\u062c \\u0637\\u0628\\u064a\\u0629 \\u0645\\u064a\\u062f\\u0627\\u0646\\u064a\\u0629 \\u0644\\u062a\\u0648\\u0633\\u064a\\u0639 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Hands-on training workshops.\",\"ar\":\"\\u0648\\u0631\\u0634 \\u062a\\u062f\\u0631\\u064a\\u0628 \\u0639\\u0645\\u0644\\u064a.\"}}]', '2025-12-26 06:33:44', '2026-02-05 14:01:25');
INSERT INTO `department_sections` (`id`, `title`, `department_id`, `overview`, `scope_of_unit`, `what_we_treat`, `leadership`, `achievements`, `news`, `created_at`, `updated_at`) VALUES
(8, '{\"en\":\"Diabetes Education Unit\",\"ar\":\"وحدة التثقيف السكري – قسم السكري\"}', 6, '{\"en\":\"<p>The Diabetes Education Unit at Al Nas Hospital is a cornerstone of comprehensive diabetes care. It provides patients and their families with the knowledge, skills, and confidence needed to effectively manage diabetes. Through structured programs, hands-on training, and the integration of technology, the unit ensures patients are able to manage all their day events by effective plan respecting their diabetes conditions to achieve better treatment adherence, improved outcomes, and enhanced quality of life.</p>\",\"ar\":\"<p>تُعد وحدة التثقيف السكري بمستشفى الناس ركيزة أساسية في منظومة الرعاية الشاملة لمرضى السكري، حيث تهدف إلى تزويد المرضى وأسرهم بالمعرفة والمهارات والثقة اللازمة للإدارة الفعّالة للمرض. ومن خلال برامج تعليمية منظمة، وتدريب عملي تطبيقي، وتكامل مدروس مع التكنولوجيا الحديثة، تُمكّن الوحدة المرضى من تنظيم جميع أنشطتهم اليومية وفق خطة فعّالة تراعي حالتهم الصحية، بما يحقق التزامًا أفضل بالعلاج، ونتائج صحية محسّنة، وجودة حياة أعلى.</p>\"}', '{\"en\":\"<p>The unit specializes in empowering patients with both the understanding and the tools to manage their diabetes conditions daily. Education covers diabetes physiology, treatment regimens, blood glucose monitoring, carb counting, exercise, sick day management and complication prevention. The unit also supports families and caregivers, ensuring diabetes management extends beyond the hospital to everyday life.</p><ul><li><p>Patient Self-Management Education</p></li><li><p>Insulin &amp; Medication Training</p></li><li><p>Meal adjustment and dose calculations</p></li><li><p>Technology &amp; Devices Education</p></li><li><p>Family &amp; Community Education</p></li></ul>\",\"ar\":\"<p></p><p>تختص الوحدة بتمكين المرضى من الفهم العميق والأدوات العملية اللازمة للإدارة اليومية لمرض السكري. ويشمل التثقيف: فسيولوجيا السكري، أنظمة العلاج، مراقبة مستوى السكر في الدم، حساب الكربوهيدرات، النشاط البدني، التعامل مع أيام المرض، والوقاية من المضاعفات. كما تقدم الوحدة دعمًا متكاملًا للأسر ومقدمي الرعاية، لضمان استمرارية إدارة السكري خارج نطاق المستشفى وفي الحياة اليومية.</p><p></p><p>نطاق عمل كل قسم</p><p></p><p>التثقيف على الإدارة الذاتية للمريض: يركز على المراقبة اليومية، والتعرف على أعراض انخفاض وارتفاع السكر في الدم، وإدارة الكيتونات (الأسيتون)، وتبني نمط حياة صحي.</p><p></p><p>التدريب على الإنسولين والأدوية: تقديم إرشادات خطوة بخطوة لبدء الإنسولين وضبط جرعاته، وطرق التخزين والحقن الصحيحة، والالتزام بالعلاج الدوائي الفموي.</p><p></p><p>تعديل الوجبات وحساب الجرعات: تدريب المرضى ومقدمي الرعاية على حساب محتوى الوجبات من الكربوهيدرات، وتعديل جرعات الإنسولين وفقًا لمحتوى الوجبة من الكربوهيدرات والدهون والبروتينات.</p><p></p><p>التثقيف على التكنولوجيا والأجهزة: تدريب المرضى وأسرهم على استخدام مضخات الإنسولين، وأجهزة المراقبة المستمرة للسكر (CGM)، والأقلام الذكية، وتطبيقات الصحة الرقمية.</p><p></p><p>تثقيف الأسرة والمجتمع: إشراك مقدمي الرعاية والجمهور من خلال ورش العمل، والبرامج المدرسية، وحملات التوعية المجتمعية لتعزيز الوعي والدعم لمرضى السكري</p>\"}', '[{\"title\":{\"en\":\"Programs\",\"ar\":\"\\u0627\\u0644\\u0628\\u0631\\u0627\\u0645\\u062c\"},\"content\":{\"en\":\"<p>We support patients with diabetes and their families by providing structured education and training to improve self-management, treatment adherence, and daily decision-making. Programs include:<\\/p>\",\"ar\":\"<p>\\u0646\\u062f\\u0639\\u0645 \\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0648\\u0639\\u0627\\u0626\\u0644\\u0627\\u062a\\u0647\\u0645 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u062a\\u0642\\u062f\\u064a\\u0645 \\u0628\\u0631\\u0627\\u0645\\u062c \\u062a\\u0639\\u0644\\u064a\\u0645\\u064a\\u0629 \\u0648\\u062a\\u062f\\u0631\\u064a\\u0628\\u064a\\u0629 \\u0645\\u0646\\u0638\\u0645\\u0629 \\u062a\\u0647\\u062f\\u0641 \\u0625\\u0644\\u0649 \\u062a\\u062d\\u0633\\u064a\\u0646 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0630\\u0627\\u062a \\u0644\\u0644\\u0645\\u0631\\u0636\\u060c \\u0648\\u0627\\u0644\\u0627\\u0644\\u062a\\u0632\\u0627\\u0645 \\u0628\\u0627\\u0644\\u0639\\u0644\\u0627\\u062c\\u060c \\u0648\\u0627\\u062a\\u062e\\u0627\\u0630 \\u0627\\u0644\\u0642\\u0631\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u064a\\u0648\\u0645\\u064a\\u0629 \\u0628\\u0634\\u0643\\u0644 \\u0623\\u0641\\u0636\\u0644. \\u0648\\u062a\\u0634\\u0645\\u0644 \\u0627\\u0644\\u0628\\u0631\\u0627\\u0645\\u062c \\u0645\\u0627 \\u064a\\u0644\\u064a:<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Structured individual and group diabetes education programs.\",\"ar\":\"\\u0628\\u0631\\u0627\\u0645\\u062c \\u062a\\u062b\\u0642\\u064a\\u0641\\u064a\\u0629 \\u0645\\u0646\\u0638\\u0645\\u0629 \\u0641\\u0631\\u062f\\u064a\\u0629 \\u0648\\u062c\\u0645\\u0627\\u0639\\u064a\\u0629 \\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a.\"}},{\"text\":{\"en\":\"Insulin initiation and optimization workshops.\",\"ar\":\"\\u0648\\u0631\\u0634 \\u0639\\u0645\\u0644 \\u0644\\u0628\\u062f\\u0621 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0648\\u062a\\u062d\\u0633\\u064a\\u0646 \\u0636\\u0628\\u0637 \\u0627\\u0644\\u062c\\u0631\\u0639\\u0627\\u062a.\"}},{\"text\":{\"en\":\"Carbohydrate counting and advanced nutrition education.\",\"ar\":\"\\u0628\\u0631\\u0627\\u0645\\u062c \\u0645\\u062a\\u0642\\u062f\\u0645\\u0629 \\u0644\\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0643\\u0631\\u0628\\u0648\\u0647\\u064a\\u062f\\u0631\\u0627\\u062a \\u0648\\u0627\\u0644\\u062a\\u063a\\u0630\\u064a\\u0629 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Technology-driven education for insulin pumps and CGM.\",\"ar\":\"\\u0628\\u0631\\u0627\\u0645\\u062c \\u062a\\u0639\\u0644\\u064a\\u0645\\u064a\\u0629 \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 \\u0644\\u0645\\u0636\\u062e\\u0627\\u062a \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0648\\u0623\\u0646\\u0638\\u0645\\u0629 CGM.\"}},{\"text\":{\"en\":\"Complication-prevention programs (foot care, eye health, kidney health).\",\"ar\":\"\\u0628\\u0631\\u0627\\u0645\\u062c \\u0627\\u0644\\u0648\\u0642\\u0627\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0636\\u0627\\u0639\\u0641\\u0627\\u062a (\\u0627\\u0644\\u0639\\u0646\\u0627\\u064a\\u0629 \\u0628\\u0627\\u0644\\u0642\\u062f\\u0645\\u060c \\u0635\\u062d\\u0629 \\u0627\\u0644\\u0639\\u064a\\u0646\\u060c \\u0635\\u062d\\u0629 \\u0627\\u0644\\u0643\\u0644\\u0649).\"}},{\"text\":{\"en\":\"Preconception and pregnancy-focused diabetes education.\",\"ar\":\"\\u0628\\u0631\\u0627\\u0645\\u062c \\u062a\\u062b\\u0642\\u064a\\u0641\\u064a\\u0629 \\u0644\\u0645\\u0631\\u062d\\u0644\\u0629 \\u0645\\u0627 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u062d\\u0645\\u0644 \\u0648\\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u062d\\u0645\\u0644.\"}},{\"text\":{\"en\":\"Family-centered workshops and community awareness campaigns.\",\"ar\":\"\\u0648\\u0631\\u0634 \\u0639\\u0645\\u0644 \\u062a\\u0631\\u0643\\u0632 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0633\\u0631\\u0629 \\u0648\\u062d\\u0645\\u0644\\u0627\\u062a \\u062a\\u0648\\u0639\\u064a\\u0629 \\u0645\\u062c\\u062a\\u0645\\u0639\\u064a\\u0629.\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":56,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":null},\"doctors\":[{\"doctor\":72,\"doctor_title\":{\"en\":\"DR\",\"ar\":\"\\u062f\\u0643\\u062a\\u0648\\u0631\"}},{\"doctor\":81,\"doctor_title\":{\"en\":\"DR\",\"ar\":\"\\u062f\\u0643\\u062a\\u0648\\u0631\"}}]}]', '[{\"text\":{\"en\":\"An 11-year-old child was diagnosed with diabetes 2 years ago. His mother was in a state of shock and deeply wished that her child did not have diabetes, as she found it very difficult to manage his condition. The child was experiencing frequent episodes of hypoglycemia and unexplained high blood sugar, both for the mother and the child. Since the diagnosis, he had been unable to live a normal daily life. After coming to Al-Nas Hospital and attending the Diabetes Education Clinic, we worked together to identify several errors that were contributing to the fluctuations. The most important of these included injecting insulin into areas of hardened tissue, inaccurate carbohydrate counting, incorrect treatment of low blood sugar, and raising blood glucose levels beyond the appropriate target after a hypoglycemic episode. With continuous follow-up, these mistakes were corrected. The child no longer experiences unexplained hypoglycemia, and with treatment of the injection-sites, accurate meal calculations, and regular rotation of injection sites, he no longer has unexplained high blood sugar. Today, the child is living a calm and normal life without constant stress. He is able to return to school after a period of avoiding many daily activities due to fear of low blood sugar episodes.\",\"ar\":\"\\u062a\\u0645 \\u062a\\u0634\\u062e\\u064a\\u0635 \\u0637\\u0641\\u0644 \\u064a\\u0628\\u0644\\u063a \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0631 11 \\u0639\\u0627\\u0645\\u064b\\u0627 \\u0628\\u0645\\u0631\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0645\\u0646\\u0630 \\u0639\\u0627\\u0645\\u064a\\u0646. \\u0643\\u0627\\u0646\\u062a \\u0648\\u0627\\u0644\\u062f\\u062a\\u0647 \\u0641\\u064a \\u062d\\u0627\\u0644\\u0629 \\u0635\\u062f\\u0645\\u0629\\u060c \\u0648\\u062a\\u062a\\u0645\\u0646\\u0649 \\u0628\\u0634\\u062f\\u0629 \\u0623\\u0644\\u0627 \\u064a\\u0643\\u0648\\u0646 \\u0637\\u0641\\u0644\\u0647\\u0627 \\u0645\\u0635\\u0627\\u0628\\u064b\\u0627 \\u0628\\u0627\\u0644\\u0633\\u0643\\u0631\\u064a\\u060c \\u0625\\u0630 \\u0648\\u062c\\u062f\\u062a \\u0635\\u0639\\u0648\\u0628\\u0629 \\u0643\\u0628\\u064a\\u0631\\u0629 \\u0641\\u064a \\u0625\\u062f\\u0627\\u0631\\u0629 \\u062d\\u0627\\u0644\\u062a\\u0647. \\u0643\\u0627\\u0646 \\u0627\\u0644\\u0637\\u0641\\u0644 \\u064a\\u0639\\u0627\\u0646\\u064a \\u0645\\u0646 \\u0646\\u0648\\u0628\\u0627\\u062a \\u0645\\u062a\\u0643\\u0631\\u0631\\u0629 \\u0645\\u0646 \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631\\u060c \\u0648\\u0627\\u0631\\u062a\\u0641\\u0627\\u0639 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u063a\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0641\\u0633\\u0631\\u060c \\u0645\\u0645\\u0627 \\u0633\\u0628\\u0628 \\u0642\\u0644\\u0642\\u064b\\u0627 \\u0644\\u0643\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0645 \\u0648\\u0627\\u0644\\u0637\\u0641\\u0644. \\u0645\\u0646\\u0630 \\u0627\\u0644\\u062a\\u0634\\u062e\\u064a\\u0635\\u060c \\u0644\\u0645 \\u064a\\u062a\\u0645\\u0643\\u0646 \\u0627\\u0644\\u0637\\u0641\\u0644 \\u0645\\u0646 \\u0645\\u0645\\u0627\\u0631\\u0633\\u0629 \\u062d\\u064a\\u0627\\u062a\\u0647 \\u0627\\u0644\\u064a\\u0648\\u0645\\u064a\\u0629 \\u0628\\u0634\\u0643\\u0644 \\u0637\\u0628\\u064a\\u0639\\u064a.  \\u0628\\u0639\\u062f \\u0642\\u062f\\u0648\\u0645\\u0647\\u0645 \\u0625\\u0644\\u0649 \\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0648\\u062d\\u0636\\u0648\\u0631 \\u0639\\u064a\\u0627\\u062f\\u0629 \\u062a\\u0639\\u0644\\u064a\\u0645 \\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a\\u060c \\u0639\\u0645\\u0644\\u0646\\u0627 \\u0645\\u0639\\u064b\\u0627 \\u0639\\u0644\\u0649 \\u062a\\u062d\\u062f\\u064a\\u062f \\u0639\\u062f\\u0629 \\u0623\\u062e\\u0637\\u0627\\u0621 \\u0643\\u0627\\u0646\\u062a \\u0627\\u0644\\u0633\\u0628\\u0628 \\u0641\\u064a \\u062a\\u0642\\u0644\\u0628\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631. \\u0645\\u0646 \\u0623\\u0647\\u0645 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u0623\\u062e\\u0637\\u0627\\u0621: \\u062d\\u0642\\u0646 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0641\\u064a \\u0645\\u0646\\u0627\\u0637\\u0642 \\u0630\\u0627\\u062a \\u0646\\u0633\\u064a\\u062c \\u0645\\u062a\\u0635\\u0644\\u0628\\u060c \\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0643\\u0631\\u0628\\u0648\\u0647\\u064a\\u062f\\u0631\\u0627\\u062a \\u0628\\u0634\\u0643\\u0644 \\u063a\\u064a\\u0631 \\u062f\\u0642\\u064a\\u0642\\u060c \\u0627\\u0644\\u062a\\u0639\\u0627\\u0645\\u0644 \\u0627\\u0644\\u062e\\u0627\\u0637\\u0626 \\u0645\\u0639 \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631\\u060c \\u0648\\u0631\\u0641\\u0639 \\u0645\\u0633\\u062a\\u0648\\u0649 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0628\\u0639\\u062f \\u0646\\u0648\\u0628\\u0629 \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636\\u0647 \\u0625\\u0644\\u0649 \\u0645\\u0627 \\u064a\\u062a\\u062c\\u0627\\u0648\\u0632 \\u0627\\u0644\\u0647\\u062f\\u0641 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628.  \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631\\u0629\\u060c \\u062a\\u0645 \\u062a\\u0635\\u062d\\u064a\\u062d \\u0647\\u0630\\u0647 \\u0627\\u0644\\u0623\\u062e\\u0637\\u0627\\u0621. \\u0644\\u0645 \\u064a\\u0639\\u062f \\u0627\\u0644\\u0637\\u0641\\u0644 \\u064a\\u0639\\u0627\\u0646\\u064a \\u0645\\u0646 \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u063a\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0641\\u0633\\u0631\\u060c \\u0648\\u0645\\u0639 \\u0639\\u0644\\u0627\\u062c \\u0645\\u0646\\u0627\\u0637\\u0642 \\u0627\\u0644\\u062d\\u0642\\u0646\\u060c \\u0648\\u0627\\u0644\\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642 \\u0644\\u0644\\u0648\\u062c\\u0628\\u0627\\u062a\\u060c \\u0648\\u062a\\u0646\\u0627\\u0648\\u0628 \\u0645\\u0648\\u0627\\u0642\\u0639 \\u0627\\u0644\\u062d\\u0642\\u0646 \\u0628\\u0627\\u0646\\u062a\\u0638\\u0627\\u0645\\u060c \\u0644\\u0645 \\u062a\\u0639\\u062f \\u0647\\u0646\\u0627\\u0643 \\u0627\\u0631\\u062a\\u0641\\u0627\\u0639\\u0627\\u062a \\u063a\\u064a\\u0631 \\u0645\\u0641\\u0633\\u0631\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0633\\u0643\\u0631. \\u0627\\u0644\\u064a\\u0648\\u0645\\u060c \\u064a\\u0639\\u064a\\u0634 \\u0627\\u0644\\u0637\\u0641\\u0644 \\u062d\\u064a\\u0627\\u0629 \\u0647\\u0627\\u062f\\u0626\\u0629 \\u0648\\u0637\\u0628\\u064a\\u0639\\u064a\\u0629 \\u062f\\u0648\\u0646 \\u062a\\u0648\\u062a\\u0631 \\u0645\\u0633\\u062a\\u0645\\u0631\\u060c \\u0648\\u062a\\u0645\\u0643\\u0651\\u0646 \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0648\\u062f\\u0629 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0645\\u062f\\u0631\\u0633\\u0629 \\u0628\\u0639\\u062f \\u0641\\u062a\\u0631\\u0629 \\u0643\\u0627\\u0646 \\u064a\\u062a\\u062c\\u0646\\u0628 \\u0641\\u064a\\u0647\\u0627 \\u0627\\u0644\\u0639\\u062f\\u064a\\u062f \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0646\\u0634\\u0637\\u0629 \\u0627\\u0644\\u064a\\u0648\\u0645\\u064a\\u0629 \\u062e\\u0648\\u0641\\u064b\\u0627 \\u0645\\u0646 \\u0646\\u0648\\u0628\\u0627\\u062a \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631.\"}},{\"text\":{\"en\":\"A 12-year-old girl from Upper Egypt had been experiencing frequent nighttime hypoglycemic episodes for eight months. Her family felt anxious and unprepared to handle diabetes emergencies, especially due to limited access to experienced care in their local hospitals. The medical team trained the family on how to manage common emergencies at home and provided direct contact numbers for ongoing support. Daily phone follow-ups and glucose monitoring revealed that the girl had been secretly administering extra insulin, which was the true cause of the repeated low blood sugar episodes. The team spoke directly with her, understood her concerns, and supported her emotionally. Gradually, she began following her correct treatment plan, her readings improved significantly, and accurate insulin ratios were finally established after the underlying cause was identified.\",\"ar\":\"\\u0643\\u0627\\u0646\\u062a \\u0641\\u062a\\u0627\\u0629 \\u062a\\u0628\\u0644\\u063a \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0631 12 \\u0639\\u0627\\u0645\\u064b\\u0627 \\u0645\\u0646 \\u0635\\u0639\\u064a\\u062f \\u0645\\u0635\\u0631 \\u062a\\u0639\\u0627\\u0646\\u064a \\u0645\\u0646 \\u0646\\u0648\\u0628\\u0627\\u062a \\u0645\\u062a\\u0643\\u0631\\u0631\\u0629 \\u0645\\u0646 \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0627\\u0644\\u0644\\u064a\\u0644\\u064a \\u0644\\u0645\\u062f\\u0629 \\u062b\\u0645\\u0627\\u0646\\u064a\\u0629 \\u0623\\u0634\\u0647\\u0631. \\u0634\\u0639\\u0631\\u062a \\u0623\\u0633\\u0631\\u062a\\u0647\\u0627 \\u0628\\u0627\\u0644\\u0642\\u0644\\u0642 \\u0648\\u0639\\u062f\\u0645 \\u0627\\u0644\\u062c\\u0627\\u0647\\u0632\\u064a\\u0629 \\u0644\\u0644\\u062a\\u0639\\u0627\\u0645\\u0644 \\u0645\\u0639 \\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0637\\u0648\\u0627\\u0631\\u0626 \\u0627\\u0644\\u0646\\u0627\\u062a\\u062c\\u0629 \\u0639\\u0646 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a\\u060c \\u062e\\u0627\\u0635\\u0629 \\u0628\\u0633\\u0628\\u0628 \\u0645\\u062d\\u062f\\u0648\\u062f\\u064a\\u0629 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0631\\u0639\\u0627\\u064a\\u0629 \\u062e\\u0628\\u064a\\u0631\\u0629 \\u0641\\u064a \\u0645\\u0633\\u062a\\u0634\\u0641\\u064a\\u0627\\u062a\\u0647\\u0645 \\u0627\\u0644\\u0645\\u062d\\u0644\\u064a\\u0629. \\u0642\\u0627\\u0645 \\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a \\u0628\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0627\\u0644\\u0623\\u0633\\u0631\\u0629 \\u0639\\u0644\\u0649 \\u0643\\u064a\\u0641\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0639\\u0627\\u0645\\u0644 \\u0645\\u0639 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0637\\u0627\\u0631\\u0626\\u0629 \\u0627\\u0644\\u0634\\u0627\\u0626\\u0639\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0646\\u0632\\u0644\\u060c \\u0648\\u0648\\u0641\\u0651\\u0631 \\u0644\\u0647\\u0645 \\u0623\\u0631\\u0642\\u0627\\u0645 \\u0627\\u062a\\u0635\\u0627\\u0644 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629 \\u0644\\u0644\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631.  \\u0643\\u0634\\u0641\\u062a \\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0627\\u062a \\u0627\\u0644\\u064a\\u0648\\u0645\\u064a\\u0629 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641 \\u0648\\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u0645\\u0633\\u062a\\u0648\\u0649 \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645 \\u0623\\u0646 \\u0627\\u0644\\u0641\\u062a\\u0627\\u0629 \\u0643\\u0627\\u0646\\u062a \\u062a\\u0639\\u0637\\u064a \\u0646\\u0641\\u0633\\u0647\\u0627 \\u062c\\u0631\\u0639\\u0627\\u062a \\u0625\\u0636\\u0627\\u0641\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0633\\u0631\\u064b\\u0627\\u060c \\u0648\\u0647\\u0648 \\u0627\\u0644\\u0633\\u0628\\u0628 \\u0627\\u0644\\u062d\\u0642\\u064a\\u0642\\u064a \\u0648\\u0631\\u0627\\u0621 \\u062a\\u0643\\u0631\\u0627\\u0631 \\u0646\\u0648\\u0628\\u0627\\u062a \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631. \\u062a\\u062d\\u062f\\u062b \\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0645\\u0639\\u0647\\u0627 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629\\u060c \\u0648\\u0627\\u0633\\u062a\\u0645\\u0639 \\u0644\\u0645\\u062e\\u0627\\u0648\\u0641\\u0647\\u0627\\u060c \\u0648\\u0642\\u062f\\u0645 \\u0644\\u0647\\u0627 \\u0627\\u0644\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a. \\u062a\\u062f\\u0631\\u064a\\u062c\\u064a\\u064b\\u0627\\u060c \\u0628\\u062f\\u0623\\u062a \\u0627\\u0644\\u0641\\u062a\\u0627\\u0629 \\u0628\\u0627\\u062a\\u0628\\u0627\\u0639 \\u062e\\u0637\\u0629 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u0635\\u062d\\u064a\\u062d\\u0629\\u060c \\u0648\\u062a\\u062d\\u0633\\u0646\\u062a \\u0642\\u0631\\u0627\\u0621\\u0627\\u062a\\u0647\\u0627 \\u0628\\u0634\\u0643\\u0644 \\u0645\\u0644\\u062d\\u0648\\u0638\\u060c \\u0648\\u062a\\u0645 \\u062a\\u062d\\u062f\\u064a\\u062f \\u0646\\u0633\\u0628 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642\\u0629 \\u0628\\u0639\\u062f \\u0627\\u0644\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0633\\u0628\\u0628 \\u0627\\u0644\\u0623\\u0633\\u0627\\u0633\\u064a \\u0644\\u0644\\u0645\\u0634\\u0643\\u0644\\u0629.\"}}]', '[{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '2025-12-26 06:33:44', '2026-02-05 14:27:01'),
(9, '{\"en\":\"Diabetes Nutrition Unit\",\"ar\":\"وحدة تغذية مرضى السكري\"}', 6, '{\"en\":\"<p>The Clinical Nutrition Unit at Al Nas Hospital’s Endocrinology &amp; Diabetes Department is dedicated to providing specialized nutritional care for patients with diabetes. Recognizing that diet plays a central role in diabetes management, the unit develops individualized dietary plans that optimize blood glucose control, prevent complications, and support overall health and wellbeing. The team works closely with endocrinologists, diabetes educators, and psychological support specialists to deliver a comprehensive and patient-centered approach.</p>\",\"ar\":\"<p>تُعنى وحدة التغذية العلاجية بقسم الغدد الصماء والسكري في مستشفى الناس بتقديم رعاية غذائية متخصصة لمرضى السكري. وإدراكًا للدور المحوري الذي يلعبه النظام الغذائي في إدارة مرض السكري، تعمل الوحدة على إعداد خطط غذائية فردية تهدف إلى تحسين التحكم في مستويات السكر بالدم، والوقاية من المضاعفات، ودعم الصحة العامة وجودة الحياة.</p><p></p><p>ويعمل فريق الوحدة بالتعاون الوثيق مع أطباء الغدد الصماء، ومثقفي السكري، وأخصائيي الدعم النفسي، لتقديم نموذج رعاية شامل يتمحور حول المريض.</p><p></p>\"}', '{\"en\":\"<p>The Clinical Nutrition Unit focuses on translating medical and dietary knowledge into practical solutions for daily life. Patients receive ongoing guidance on healthy eating, meal planning, carbohydrate counting, and portion control, with a strong emphasis on sustainability and long-term success. The unit also addresses special populations such as children, pregnant women with gestational diabetes, and patients with obesity or lipid disorders.</p><ul><li><p>Nutritional Assessment &amp; Planning: Comprehensive evaluation of dietary habits, caloric needs, and nutrient intake, followed by tailored meal planning.</p></li><li><p>Diet Therapy &amp; Counseling: Individual and group counseling sessions for managing blood glucose levels, dyslipidemia, obesity, and complications related to diabetes.</p></li><li><p>Lifestyle &amp; Weight Management: Programs designed to support weight loss, improve insulin sensitivity, and promote healthy physical activity.</p></li><li><p>Education &amp; Support Programs: Structured workshops on carbohydrate counting, food label reading, and practical cooking skills to empower patients and families.</p></li></ul>\",\"ar\":\"<p>التقييم الغذائي والتخطيط: تقييم شامل للعادات الغذائية، والاحتياجات الحرارية، وتناول العناصر الغذائية، يعقبه إعداد خطط وجبات مخصصة تناسب احتياجات كل مريض.</p><p></p><p>العلاج الغذائي والإرشاد: جلسات إرشاد فردية وجماعية للتحكم في مستويات السكر بالدم، واضطرابات الدهون، والسمنة، والمضاعفات المرتبطة بمرض السكري.</p><p></p><p>نمط الحياة وإدارة الوزن: برامج مصممة لدعم فقدان الوزن، وتحسين حساسية الإنسولين، وتعزيز ممارسة النشاط البدني الصحي.</p><p></p><p>برامج التثقيف والدعم: ورش عمل منظمة حول حساب الكربوهيدرات، وقراءة الملصقات الغذائية، ومهارات الطهي الصحي، لتمكين المرضى وأسرهم.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627\"},\"content\":{\"en\":\"<p>We support patients with diabetes through individualized medical nutrition therapy aimed at optimizing glycemic control, supporting weight management, and reducing cardiometabolic risk, including:<\\/p>\",\"ar\":\"<p>\\u0646\\u062f\\u0639\\u0645 \\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u063a\\u0630\\u0627\\u0626\\u064a \\u0627\\u0644\\u0637\\u0628\\u064a \\u0627\\u0644\\u0641\\u0631\\u062f\\u064a\\u060c \\u0627\\u0644\\u0630\\u064a \\u064a\\u0647\\u062f\\u0641 \\u0625\\u0644\\u0649 \\u062a\\u062d\\u0633\\u064a\\u0646 \\u0627\\u0644\\u0633\\u064a\\u0637\\u0631\\u0629 \\u0639\\u0644\\u0649 \\u0645\\u0633\\u062a\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645\\u060c \\u0648\\u062f\\u0639\\u0645 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0648\\u0632\\u0646\\u060c \\u0648\\u062a\\u0642\\u0644\\u064a\\u0644 \\u0627\\u0644\\u0645\\u062e\\u0627\\u0637\\u0631 \\u0627\\u0644\\u0642\\u0644\\u0628\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0645\\u062b\\u064a\\u0644 \\u0627\\u0644\\u063a\\u0630\\u0627\\u0626\\u064a\\u060c \\u0648\\u064a\\u0634\\u0645\\u0644 \\u0630\\u0644\\u0643:<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Diabetes nutrition (Type 1, Type 2, Gestational, Pre diabetes)\",\"ar\":\"\\u0627\\u0644\\u062a\\u063a\\u0630\\u064a\\u0629 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c\\u064a\\u0629 \\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a (\\u0627\\u0644\\u0646\\u0648\\u0639 \\u0627\\u0644\\u0623\\u0648\\u0644\\u060c \\u0627\\u0644\\u0646\\u0648\\u0639 \\u0627\\u0644\\u062b\\u0627\\u0646\\u064a\\u060c \\u0633\\u0643\\u0631\\u064a \\u0627\\u0644\\u062d\\u0645\\u0644\\u060c \\u0648\\u0645\\u0627 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a).\"}},{\"text\":{\"en\":\"Obesity and metabolic syndrome\",\"ar\":\"\\u0627\\u0644\\u0633\\u0645\\u0646\\u0629 \\u0648\\u0645\\u062a\\u0644\\u0627\\u0632\\u0645\\u0629 \\u0627\\u0644\\u0623\\u064a\\u0636.\"}},{\"text\":{\"en\":\"Dyslipidemia (high cholesterol and triglycerides)\",\"ar\":\"\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u062f\\u0647\\u0648\\u0646 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645 (\\u0627\\u0631\\u062a\\u0641\\u0627\\u0639 \\u0627\\u0644\\u0643\\u0648\\u0644\\u064a\\u0633\\u062a\\u0631\\u0648\\u0644 \\u0648\\u0627\\u0644\\u062f\\u0647\\u0648\\u0646 \\u0627\\u0644\\u062b\\u0644\\u0627\\u062b\\u064a\\u0629).\"}},{\"text\":{\"en\":\"Hypertension-related dietary needs\",\"ar\":\"\\u0627\\u0644\\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a \\u0627\\u0644\\u063a\\u0630\\u0627\\u0626\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0627\\u0631\\u062a\\u0641\\u0627\\u0639 \\u0636\\u063a\\u0637 \\u0627\\u0644\\u062f\\u0645.\"}},{\"text\":{\"en\":\"Micronutrient deficiencies common in diabetes\",\"ar\":\"\\u0646\\u0642\\u0635 \\u0627\\u0644\\u0639\\u0646\\u0627\\u0635\\u0631 \\u0627\\u0644\\u063a\\u0630\\u0627\\u0626\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0634\\u0627\\u0626\\u0639 \\u0644\\u062f\\u0649 \\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a.\"}},{\"text\":{\"en\":\"Complication-related dietary modifications (renal nutrition, liver health, wound healing)\",\"ar\":\"\\u0627\\u0644\\u062a\\u0639\\u062f\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u063a\\u0630\\u0627\\u0626\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0645\\u0636\\u0627\\u0639\\u0641\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a (\\u062a\\u063a\\u0630\\u064a\\u0629 \\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0643\\u0644\\u0649\\u060c \\u0635\\u062d\\u0629 \\u0627\\u0644\\u0643\\u0628\\u062f\\u060c \\u0627\\u0644\\u062a\\u0626\\u0627\\u0645 \\u0627\\u0644\\u062c\\u0631\\u0648\\u062d).\"}},{\"text\":{\"en\":\"Binge eating disorders\",\"ar\":\"\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0646\\u0648\\u0628\\u0627\\u062a \\u0627\\u0644\\u0623\\u0643\\u0644 \\u0627\\u0644\\u0634\\u0631\\u0647.\"}},{\"text\":{\"en\":\"Nutrition of athletes with diabetes\",\"ar\":\"\\u0627\\u0644\\u062a\\u063a\\u0630\\u064a\\u0629 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0627\\u0644\\u0631\\u064a\\u0627\\u0636\\u064a\\u064a\\u0646 \\u0627\\u0644\\u0645\\u0635\\u0627\\u0628\\u064a\\u0646 \\u0628\\u0627\\u0644\\u0633\\u0643\\u0631\\u064a.\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":56,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u064a\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":null},\"doctors\":[{\"doctor\":75,\"doctor_title\":{\"en\":\"DR\",\"ar\":\"\\u062f\"}}]}]', '[{\"text\":{\"en\":\"An 8-year-old girl was consistently experiencing high blood sugar levels. After taking a detailed nutritional and medical history, it became clear that she was staying up very late at night and not getting enough sleep. Her meal times were irregular, she struggled with accurate carbohydrate counting, and she frequently ate large amounts of chips and sweets during the day. She was taught how to count carbohydrates properly, the importance of maintaining regular sleep and meal schedules, and when it is appropriate to eat snacks such as chips. Her daily intake of carbohydrates, protein, and fats was also carefully tailored to suit her needs throughout the day. With her commitment and continuous follow-up, her blood sugar readings improved significantly. Over time, she found it easier to calculate her meals and began to choose healthier options most of the time.\",\"ar\":\"\\u0643\\u0627\\u0646\\u062a \\u0641\\u062a\\u0627\\u0629 \\u062a\\u0628\\u0644\\u063a \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0631 8 \\u0633\\u0646\\u0648\\u0627\\u062a \\u062a\\u0639\\u0627\\u0646\\u064a \\u0628\\u0627\\u0633\\u062a\\u0645\\u0631\\u0627\\u0631 \\u0645\\u0646 \\u0627\\u0631\\u062a\\u0641\\u0627\\u0639 \\u0645\\u0633\\u062a\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645. \\u0628\\u0639\\u062f \\u0623\\u062e\\u0630 \\u062a\\u0627\\u0631\\u064a\\u062e \\u063a\\u0630\\u0627\\u0626\\u064a \\u0648\\u0637\\u0628\\u064a \\u0645\\u0641\\u0635\\u0644\\u060c \\u062a\\u0628\\u064a\\u0646 \\u0623\\u0646\\u0647\\u0627 \\u062a\\u0633\\u0647\\u0631 \\u0644\\u0648\\u0642\\u062a \\u0645\\u062a\\u0623\\u062e\\u0631 \\u062c\\u062f\\u064b\\u0627 \\u0644\\u064a\\u0644\\u0627\\u064b \\u0648\\u0644\\u0627 \\u062a\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0642\\u0633\\u0637 \\u0643\\u0627\\u0641\\u064d \\u0645\\u0646 \\u0627\\u0644\\u0646\\u0648\\u0645. \\u0643\\u0627\\u0646\\u062a \\u0623\\u0648\\u0642\\u0627\\u062a \\u0648\\u062c\\u0628\\u0627\\u062a\\u0647\\u0627 \\u063a\\u064a\\u0631 \\u0645\\u0646\\u062a\\u0638\\u0645\\u0629\\u060c \\u0648\\u062a\\u0648\\u0627\\u062c\\u0647 \\u0635\\u0639\\u0648\\u0628\\u0629 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0643\\u0631\\u0628\\u0648\\u0647\\u064a\\u062f\\u0631\\u0627\\u062a \\u0628\\u062f\\u0642\\u0629\\u060c \\u0648\\u0643\\u0627\\u0646\\u062a \\u062a\\u062a\\u0646\\u0627\\u0648\\u0644 \\u0643\\u0645\\u064a\\u0627\\u062a \\u0643\\u0628\\u064a\\u0631\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0634\\u064a\\u0628\\u0633 \\u0648\\u0627\\u0644\\u062d\\u0644\\u0648\\u064a\\u0627\\u062a \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u064a\\u0648\\u0645.  \\u062a\\u0645 \\u062a\\u0639\\u0644\\u064a\\u0645\\u0647\\u0627 \\u0643\\u064a\\u0641\\u064a\\u0629 \\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0643\\u0631\\u0628\\u0648\\u0647\\u064a\\u062f\\u0631\\u0627\\u062a \\u0628\\u0634\\u0643\\u0644 \\u0635\\u062d\\u064a\\u062d\\u060c \\u0648\\u0623\\u0647\\u0645\\u064a\\u0629 \\u0627\\u0644\\u062d\\u0641\\u0627\\u0638 \\u0639\\u0644\\u0649 \\u0645\\u0648\\u0627\\u0639\\u064a\\u062f \\u0646\\u0648\\u0645 \\u0648\\u0648\\u062c\\u0628\\u0627\\u062a \\u0645\\u0646\\u062a\\u0638\\u0645\\u0629\\u060c \\u0648\\u0645\\u0639\\u0631\\u0641\\u0629 \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628 \\u0644\\u062a\\u0646\\u0627\\u0648\\u0644 \\u0627\\u0644\\u0648\\u062c\\u0628\\u0627\\u062a \\u0627\\u0644\\u062e\\u0641\\u064a\\u0641\\u0629 \\u0645\\u062b\\u0644 \\u0627\\u0644\\u0634\\u064a\\u0628\\u0633. \\u0643\\u0645\\u0627 \\u062a\\u0645 \\u0636\\u0628\\u0637 \\u0643\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0643\\u0631\\u0628\\u0648\\u0647\\u064a\\u062f\\u0631\\u0627\\u062a \\u0648\\u0627\\u0644\\u0628\\u0631\\u0648\\u062a\\u064a\\u0646\\u0627\\u062a \\u0648\\u0627\\u0644\\u062f\\u0647\\u0648\\u0646 \\u0627\\u0644\\u064a\\u0648\\u0645\\u064a\\u0629 \\u0628\\u0639\\u0646\\u0627\\u064a\\u0629 \\u0644\\u062a\\u062a\\u0646\\u0627\\u0633\\u0628 \\u0645\\u0639 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a\\u0647\\u0627 \\u0637\\u0648\\u0627\\u0644 \\u0627\\u0644\\u064a\\u0648\\u0645.  \\u0645\\u0639 \\u0627\\u0644\\u062a\\u0632\\u0627\\u0645\\u0647\\u0627 \\u0648\\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631\\u0629\\u060c \\u062a\\u062d\\u0633\\u0646\\u062a \\u0642\\u0631\\u0627\\u0621\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645 \\u0628\\u0634\\u0643\\u0644 \\u0643\\u0628\\u064a\\u0631. \\u0648\\u0645\\u0639 \\u0645\\u0631\\u0648\\u0631 \\u0627\\u0644\\u0648\\u0642\\u062a\\u060c \\u0623\\u0635\\u0628\\u062d \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0633\\u0647\\u0644 \\u0639\\u0644\\u064a\\u0647\\u0627 \\u062d\\u0633\\u0627\\u0628 \\u0648\\u062c\\u0628\\u0627\\u062a\\u0647\\u0627 \\u0648\\u0628\\u062f\\u0623\\u062a \\u062a\\u062e\\u062a\\u0627\\u0631 \\u0627\\u0644\\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0635\\u062d\\u064a\\u0629 \\u0641\\u064a \\u0645\\u0639\\u0638\\u0645 \\u0627\\u0644\\u0623\\u0648\\u0642\\u0627\\u062a.\"}},{\"text\":{\"en\":\"An 8-year-old girl was experiencing persistent high blood sugar levels. A detailed nutritional and lifestyle assessment revealed irregular sleep patterns, late nights, inconsistent meal times, difficulty counting carbohydrates, and frequent consumption of chips and sweets throughout the day. She and her family were educated on carbohydrate counting, the importance of consistent sleep and meal schedules, and appropriate timing and portion sizes for snacks. A balanced daily plan for carbohydrates, proteins, and fats was created. With commitment and ongoing follow-up, her blood sugar readings improved significantly. She became confident in calculating her meals and began making healthier food choices most of the time.\",\"ar\":\"\\u0643\\u0627\\u0646\\u062a \\u0641\\u062a\\u0627\\u0629 \\u062a\\u0628\\u0644\\u063a \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0631 8 \\u0633\\u0646\\u0648\\u0627\\u062a \\u062a\\u0639\\u0627\\u0646\\u064a \\u0645\\u0646 \\u0627\\u0631\\u062a\\u0641\\u0627\\u0639 \\u0645\\u0633\\u062a\\u0645\\u0631 \\u0641\\u064a \\u0645\\u0633\\u062a\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645. \\u0623\\u0638\\u0647\\u0631 \\u0627\\u0644\\u062a\\u0642\\u064a\\u064a\\u0645 \\u0627\\u0644\\u063a\\u0630\\u0627\\u0626\\u064a \\u0648\\u0646\\u0645\\u0637 \\u0627\\u0644\\u062d\\u064a\\u0627\\u0629 \\u0627\\u0644\\u0645\\u0641\\u0635\\u0644 \\u0623\\u0646 \\u0646\\u0648\\u0645\\u0647\\u0627 \\u063a\\u064a\\u0631 \\u0645\\u0646\\u062a\\u0638\\u0645\\u060c \\u0648\\u0643\\u0627\\u0646\\u062a \\u062a\\u0633\\u0647\\u0631 \\u0644\\u0648\\u0642\\u062a \\u0645\\u062a\\u0623\\u062e\\u0631\\u060c \\u0648\\u062a\\u062a\\u0631\\u0627\\u0648\\u062d \\u0623\\u0648\\u0642\\u0627\\u062a \\u0648\\u062c\\u0628\\u0627\\u062a\\u0647\\u0627 \\u0628\\u0634\\u0643\\u0644 \\u063a\\u064a\\u0631 \\u0645\\u0646\\u062a\\u0638\\u0645\\u060c \\u0648\\u062a\\u0648\\u0627\\u062c\\u0647 \\u0635\\u0639\\u0648\\u0628\\u0629 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0643\\u0631\\u0628\\u0648\\u0647\\u064a\\u062f\\u0631\\u0627\\u062a\\u060c \\u0648\\u062a\\u062a\\u0646\\u0627\\u0648\\u0644 \\u0627\\u0644\\u0634\\u064a\\u0628\\u0633 \\u0648\\u0627\\u0644\\u062d\\u0644\\u0648\\u064a\\u0627\\u062a \\u0628\\u0634\\u0643\\u0644 \\u0645\\u062a\\u0643\\u0631\\u0631 \\u0637\\u0648\\u0627\\u0644 \\u0627\\u0644\\u064a\\u0648\\u0645.  \\u062a\\u0645 \\u062a\\u0648\\u0639\\u064a\\u0629 \\u0627\\u0644\\u0641\\u062a\\u0627\\u0629 \\u0648\\u0639\\u0627\\u0626\\u0644\\u062a\\u0647\\u0627 \\u0628\\u0643\\u064a\\u0641\\u064a\\u0629 \\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0643\\u0631\\u0628\\u0648\\u0647\\u064a\\u062f\\u0631\\u0627\\u062a\\u060c \\u0648\\u0623\\u0647\\u0645\\u064a\\u0629 \\u0627\\u0644\\u062d\\u0641\\u0627\\u0638 \\u0639\\u0644\\u0649 \\u0645\\u0648\\u0627\\u0639\\u064a\\u062f \\u0646\\u0648\\u0645 \\u0648\\u0648\\u062c\\u0628\\u0627\\u062a \\u062b\\u0627\\u0628\\u062a\\u0629\\u060c \\u0648\\u062a\\u062d\\u062f\\u064a\\u062f \\u0627\\u0644\\u062a\\u0648\\u0642\\u064a\\u062a \\u0648\\u0627\\u0644\\u062d\\u0635\\u0635 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0648\\u062c\\u0628\\u0627\\u062a \\u0627\\u0644\\u062e\\u0641\\u064a\\u0641\\u0629. \\u0643\\u0645\\u0627 \\u062a\\u0645 \\u0648\\u0636\\u0639 \\u062e\\u0637\\u0629 \\u064a\\u0648\\u0645\\u064a\\u0629 \\u0645\\u062a\\u0648\\u0627\\u0632\\u0646\\u0629 \\u0644\\u0644\\u0643\\u0631\\u0628\\u0648\\u0647\\u064a\\u062f\\u0631\\u0627\\u062a \\u0648\\u0627\\u0644\\u0628\\u0631\\u0648\\u062a\\u064a\\u0646\\u0627\\u062a \\u0648\\u0627\\u0644\\u062f\\u0647\\u0648\\u0646.  \\u0645\\u0639 \\u0627\\u0644\\u062a\\u0632\\u0627\\u0645\\u0647\\u0627 \\u0648\\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631\\u0629\\u060c \\u062a\\u062d\\u0633\\u0646\\u062a \\u0642\\u0631\\u0627\\u0621\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645 \\u0628\\u0634\\u0643\\u0644 \\u0643\\u0628\\u064a\\u0631. \\u0648\\u0627\\u0643\\u062a\\u0633\\u0628\\u062a \\u0627\\u0644\\u062b\\u0642\\u0629 \\u0641\\u064a \\u062d\\u0633\\u0627\\u0628 \\u0648\\u062c\\u0628\\u0627\\u062a\\u0647\\u0627\\u060c \\u0648\\u0628\\u062f\\u0623\\u062a \\u0641\\u064a \\u0627\\u062e\\u062a\\u064a\\u0627\\u0631 \\u062e\\u064a\\u0627\\u0631\\u0627\\u062a \\u063a\\u0630\\u0627\\u0626\\u064a\\u0629 \\u0623\\u0643\\u062b\\u0631 \\u0635\\u062d\\u0629 \\u0641\\u064a \\u0645\\u0639\\u0638\\u0645 \\u0627\\u0644\\u0623\\u0648\\u0642\\u0627\\u062a.\"}}]', '[{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '2025-12-26 06:33:44', '2026-02-05 15:03:28');
INSERT INTO `department_sections` (`id`, `title`, `department_id`, `overview`, `scope_of_unit`, `what_we_treat`, `leadership`, `achievements`, `news`, `created_at`, `updated_at`) VALUES
(10, '{\"en\":\"Diabetes Psychological Support Unit\",\"ar\":\"وحدة الدعم النفسي – قسم السكري\"}', 6, '{\"en\":\"<p>The Psychological Support Unit at Al Nas Hospital’s Diabetes Department is dedicated to addressing the emotional and mental health needs of diabetic patients. Recognizing the strong link between mental wellbeing and physical health, the unit provides individualized counseling, stress management strategies, and coping mechanisms that help patients and their families adapt to the challenges of diabetes care. By fostering resilience and emotional balance, the unit enhances adherence to treatment, improves quality of life, and reduces the risk of diabetes-related distress.</p>\",\"ar\":\"<h1>تُعنى وحدة الدعم النفسي بقسم السكري في مستشفى الناس بتلبية الاحتياجات النفسية والانفعالية لمرضى السكري. وانطلاقًا من إدراكها للعلاقة الوثيقة بين الصحة النفسية والصحة الجسدية، تقدم الوحدة خدمات الإرشاد النفسي الفردي، واستراتيجيات إدارة الضغوط، وآليات التكيف التي تساعد المرضى وأسرهم على التعامل مع تحديات التعايش مع مرض السكري. ومن خلال تعزيز الصلابة النفسية والتوازن الانفعالي، تسهم الوحدة في تحسين الالتزام بالعلاج، والارتقاء بجودة الحياة، والحد من الضغوط النفسية المرتبطة بالسكري.</h1>\"}', '{\"en\":\"<p>The Psychological Support Unit provides comprehensive psychosocial care, working hand-in-hand with endocrinology, nutrition, and diabetes education teams. Its scope covers screening for psychological distress, structured therapy sessions, and emotional support throughout the patient journey from diagnosis to long-term management.</p><ul><li><p>Individual Counseling: One-on-one sessions to screen anxiety, depression, adjustment disorder, personality disorders and treatment-related stress.</p></li><li><p>Family &amp; Caregiver Support: Counseling sessions for families to strengthen support systems and improve diabetes management at home.</p></li><li><p>Group Therapy: Peer support groups that allow patients to share experiences, build coping strategies, and reduce stigma.</p></li><li><p>Stress &amp; Lifestyle Management Programs: Techniques such as relaxation therapy, mindfulness, and problem-solving strategies to reduce stress and enhance daily living.</p></li></ul>\",\"ar\":\"<p>توفر <strong>وحدة الدعم النفسي</strong> رعاية نفسية واجتماعية شاملة، وتعمل بالتعاون الوثيق مع فرق الغدد الصماء والتغذية وتعليم مرضى السكري. وتشمل مهام الوحدة فحص الضغوط النفسية، وجلسات علاج منظمة، والدعم العاطفي طوال رحلة المريض من التشخيص وحتى الإدارة طويلة المدى للمرض.</p><p><strong>الإرشاد الفردي:</strong> جلسات شخصية لفحص القلق، والاكتئاب، واضطرابات التكيف، واضطرابات الشخصية، والضغوط المتعلقة بالعلاج.</p><p><strong>دعم الأسرة ومقدمي الرعاية:</strong> جلسات استشارية للعائلات لتعزيز نظم الدعم وتحسين إدارة مرض السكري في المنزل.</p><p><strong>العلاج الجماعي:</strong> مجموعات دعم الأقران التي تتيح للمرضى تبادل الخبرات، وبناء استراتيجيات التأقلم، وتقليل الوصمة الاجتماعية.</p><p><strong>برامج إدارة التوتر ونمط الحياة:</strong> تقنيات مثل العلاج بالاسترخاء، والوعي الذهني (Mindfulness)، واستراتيجيات حل المشكلات لتقليل التوتر وتحسين جودة الحياة اليومية.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627\"},\"content\":{\"en\":\"<p>We support patients living with diabetes who experience emotional, behavioral, or psychosocial challenges related to their condition, providing psychological assessment and evidence-based interventions to improve coping, treatment adherence, and overall quality of life:<\\/p>\",\"ar\":\"<p>\\u0646\\u062f\\u0639\\u0645 \\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0627\\u0644\\u0630\\u064a\\u0646 \\u064a\\u0648\\u0627\\u062c\\u0647\\u0648\\u0646 \\u062a\\u062d\\u062f\\u064a\\u0627\\u062a \\u0639\\u0627\\u0637\\u0641\\u064a\\u0629 \\u0623\\u0648 \\u0633\\u0644\\u0648\\u0643\\u064a\\u0629 \\u0623\\u0648 \\u0646\\u0641\\u0633\\u064a\\u0629 \\u0627\\u062c\\u062a\\u0645\\u0627\\u0639\\u064a\\u0629 \\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u062d\\u0627\\u0644\\u062a\\u0647\\u0645\\u060c \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u062a\\u0642\\u062f\\u064a\\u0645 \\u0627\\u0644\\u062a\\u0642\\u064a\\u064a\\u0645 \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a \\u0648\\u062a\\u0637\\u0628\\u064a\\u0642 \\u062a\\u062f\\u062e\\u0644\\u0627\\u062a \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u062f\\u0644\\u0629 \\u062a\\u0647\\u062f\\u0641 \\u0625\\u0644\\u0649 \\u062a\\u062d\\u0633\\u064a\\u0646 \\u0627\\u0644\\u0642\\u062f\\u0631\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0643\\u064a\\u0641\\u060c \\u0648\\u0627\\u0644\\u0627\\u0644\\u062a\\u0632\\u0627\\u0645 \\u0628\\u0627\\u0644\\u0639\\u0644\\u0627\\u062c\\u060c \\u0648\\u062c\\u0648\\u062f\\u0629 \\u0627\\u0644\\u062d\\u064a\\u0627\\u0629 \\u0628\\u0634\\u0643\\u0644 \\u0639\\u0627\\u0645.<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Diabetes-related stress\",\"ar\":\"\\u0627\\u0644\\u0636\\u063a\\u0648\\u0637 \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0645\\u0631\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a\"}},{\"text\":{\"en\":\"Depression and anxiety associated with chronic illness\",\"ar\":\"\\u0627\\u0644\\u0627\\u0643\\u062a\\u0626\\u0627\\u0628 \\u0648\\u0627\\u0644\\u0642\\u0644\\u0642 \\u0627\\u0644\\u0645\\u0635\\u0627\\u062d\\u0628\\u0627\\u0646 \\u0644\\u0644\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0645\\u0632\\u0645\\u0646\\u0629\"}},{\"text\":{\"en\":\"Eating behaviors and emotional eating patterns\",\"ar\":\"\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0633\\u0644\\u0648\\u0643 \\u0627\\u0644\\u063a\\u0630\\u0627\\u0626\\u064a \\u0648\\u0627\\u0644\\u0623\\u0643\\u0644 \\u0627\\u0644\\u0639\\u0627\\u0637\\u0641\\u064a\"}},{\"text\":{\"en\":\"Coping challenges in pediatric and adolescent patients\",\"ar\":\"\\u0635\\u0639\\u0648\\u0628\\u0627\\u062a \\u0627\\u0644\\u062a\\u0643\\u064a\\u0641 \\u0644\\u062f\\u0649 \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644 \\u0648\\u0627\\u0644\\u0645\\u0631\\u0627\\u0647\\u0642\\u064a\\u0646\"}},{\"text\":{\"en\":\"Caregiver stress and family communication issues\",\"ar\":\"\\u0636\\u063a\\u0648\\u0637 \\u0645\\u0642\\u062f\\u0645\\u064a \\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0648\\u0645\\u0634\\u0643\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0627\\u0644\\u0623\\u0633\\u0631\\u064a\"}},{\"text\":{\"en\":\"Some serious behavioral issues\",\"ar\":\"\\u0628\\u0639\\u0636 \\u0627\\u0644\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0633\\u0644\\u0648\\u0643\\u064a\\u0629 \\u0627\\u0644\\u0634\\u062f\\u064a\\u062f\\u0629\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":69,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":null},\"doctors\":[{\"doctor\":73,\"doctor_title\":{\"en\":\"DR\",\"ar\":\"\\u062f\"}}]}]', '[{\"text\":{\"en\":\"A 15-year-old teenager began secretly taking household items and selling them to obtain money, which he used to buy snacks and sweets that were restricted at home. Over time, this behavior escalated, and he even sold electrical appliances without his parents\\u2019 knowledge. Once his family discovered what was happening, they shared their concerns during therapy sessions. Together, we addressed the underlying causes of his stealing behavior and guided both the adolescent and his parents on how to handle the situation effectively. Over the course of therapy, the stealing stopped, the teenager was able to rebuild trust, sincerely apologize to his parents, and restore a healthier relationship within the family.\",\"ar\":\"88 ar\"}},{\"text\":{\"en\":\"A 15-year-old girl presented with suicidal thoughts and feelings of hopelessness, believing that she would never be able to control her diabetes and that her life would ultimately end in suffering and death. She often refused insulin and glucose monitoring, expressed thoughts of harming herself and her family, and struggled with inappropriate social interactions. Her condition was worsened by family stress, including her father\\u2019s work-related pressures and his negative comments regarding her illness. Through a series of psychological sessions, we addressed her distress, improved family communication, and supported her in rebuilding confidence and healthier coping strategies. Over time, she began to re-engage with her diabetes care, resumed monitoring and insulin use, expressed her emotions more openly, and showed a new sense of hope and motivation for the future.\",\"ar\":\"\\u0628\\u062f\\u0623 \\u0645\\u0631\\u0627\\u0647\\u0642 \\u064a\\u0628\\u0644\\u063a \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0631 15 \\u0639\\u0627\\u0645\\u064b\\u0627 \\u0628\\u0623\\u062e\\u0630 \\u0623\\u0634\\u064a\\u0627\\u0621 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0646\\u0632\\u0644 \\u0648\\u0628\\u064a\\u0639\\u0647\\u0627 \\u0633\\u0631\\u064b\\u0627 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0627\\u0644\\u060c \\u0627\\u0644\\u0630\\u064a \\u0643\\u0627\\u0646 \\u064a\\u0633\\u062a\\u062e\\u062f\\u0645\\u0647 \\u0644\\u0634\\u0631\\u0627\\u0621 \\u0627\\u0644\\u0648\\u062c\\u0628\\u0627\\u062a \\u0627\\u0644\\u062e\\u0641\\u064a\\u0641\\u0629 \\u0648\\u0627\\u0644\\u062d\\u0644\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0645\\u062d\\u0638\\u0648\\u0631\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0646\\u0632\\u0644. \\u0648\\u0645\\u0639 \\u0645\\u0631\\u0648\\u0631 \\u0627\\u0644\\u0648\\u0642\\u062a\\u060c \\u062a\\u0635\\u0627\\u0639\\u062f \\u0647\\u0630\\u0627 \\u0627\\u0644\\u0633\\u0644\\u0648\\u0643 \\u062d\\u062a\\u0649 \\u0648\\u0635\\u0644 \\u0625\\u0644\\u0649 \\u0628\\u064a\\u0639 \\u0627\\u0644\\u0623\\u062c\\u0647\\u0632\\u0629 \\u0627\\u0644\\u0643\\u0647\\u0631\\u0628\\u0627\\u0626\\u064a\\u0629 \\u062f\\u0648\\u0646 \\u0639\\u0644\\u0645 \\u0648\\u0627\\u0644\\u062f\\u064a\\u0647.  \\u0639\\u0646\\u062f\\u0645\\u0627 \\u0627\\u0643\\u062a\\u0634\\u0641\\u062a \\u0627\\u0644\\u0639\\u0627\\u0626\\u0644\\u0629 \\u0645\\u0627 \\u064a\\u062d\\u062f\\u062b\\u060c \\u0634\\u0627\\u0631\\u0643\\u0648\\u0627 \\u0645\\u062e\\u0627\\u0648\\u0641\\u0647\\u0645 \\u062e\\u0644\\u0627\\u0644 \\u062c\\u0644\\u0633\\u0627\\u062a \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a. \\u0645\\u0639\\u064b\\u0627\\u060c \\u062a\\u0646\\u0627\\u0648\\u0644\\u0646\\u0627 \\u0627\\u0644\\u0623\\u0633\\u0628\\u0627\\u0628 \\u0627\\u0644\\u0643\\u0627\\u0645\\u0646\\u0629 \\u0648\\u0631\\u0627\\u0621 \\u0633\\u0644\\u0648\\u0643 \\u0627\\u0644\\u0633\\u0631\\u0642\\u0629\\u060c \\u0648\\u0648\\u062c\\u0647\\u0646\\u0627 \\u0627\\u0644\\u0645\\u0631\\u0627\\u0647\\u0642 \\u0648\\u0648\\u0627\\u0644\\u062f\\u064a\\u0647 \\u062d\\u0648\\u0644 \\u0643\\u064a\\u0641\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0639\\u0627\\u0645\\u0644 \\u0645\\u0639 \\u0627\\u0644\\u0645\\u0648\\u0642\\u0641 \\u0628\\u0634\\u0643\\u0644 \\u0641\\u0639\\u0651\\u0627\\u0644.  \\u062e\\u0644\\u0627\\u0644 \\u0641\\u062a\\u0631\\u0629 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c\\u060c \\u062a\\u0648\\u0642\\u0641 \\u0627\\u0644\\u0633\\u0644\\u0648\\u0643 \\u0639\\u0646 \\u0627\\u0644\\u0633\\u0631\\u0642\\u0629\\u060c \\u0648\\u062a\\u0645\\u0643\\u0646 \\u0627\\u0644\\u0645\\u0631\\u0627\\u0647\\u0642 \\u0645\\u0646 \\u0627\\u0633\\u062a\\u0639\\u0627\\u062f\\u0629 \\u0627\\u0644\\u062b\\u0642\\u0629\\u060c \\u0648\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0627\\u0639\\u062a\\u0630\\u0627\\u0631 \\u0635\\u0627\\u062f\\u0642 \\u0644\\u0648\\u0627\\u0644\\u062f\\u064a\\u0647\\u060c \\u0648\\u0625\\u0639\\u0627\\u062f\\u0629 \\u0628\\u0646\\u0627\\u0621 \\u0639\\u0644\\u0627\\u0642\\u0629 \\u0623\\u0633\\u0631\\u064a\\u0629 \\u0635\\u062d\\u064a\\u0629 \\u0623\\u0643\\u062b\\u0631.\"}},{\"text\":{\"en\":\"A 16-year-old girl from a culturally underprivileged background initially had no understanding of emotions and expressed all feelings in the same way, often laughing even in sad situations. She also struggled with severe social shyness, leaving her distant from her own siblings as she did not know how to communicate or interact with them. Through a series of psychological sessions, she gradually developed emotional awareness, filling over twelve pages with reflections on her feelings and related memories. Over time, she learned to express herself more clearly, engage meaningfully with others, and even participated in a behavioral exercise\\u2014successfully initiating a conversation with the diabetes clinic nurse and confidently handing over her file under our supervision. She is now more socially interactive, adherent to her insulin regimen, and actively working to better control her diabetes.\",\"ar\":\"\\u0643\\u0627\\u0646\\u062a \\u0641\\u062a\\u0627\\u0629 \\u062a\\u0628\\u0644\\u063a \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0631 16 \\u0639\\u0627\\u0645\\u064b\\u0627 \\u0645\\u0646 \\u062e\\u0644\\u0641\\u064a\\u0629 \\u062b\\u0642\\u0627\\u0641\\u064a\\u0629 \\u0645\\u062d\\u0631\\u0648\\u0645\\u0629\\u060c \\u0648\\u0644\\u0645 \\u062a\\u0643\\u0646 \\u062a\\u0645\\u062a\\u0644\\u0643 \\u0641\\u0647\\u0645\\u064b\\u0627 \\u0644\\u0645\\u0634\\u0627\\u0639\\u0631\\u0647\\u0627 \\u0641\\u064a \\u0627\\u0644\\u0628\\u062f\\u0627\\u064a\\u0629\\u060c \\u0641\\u0643\\u0627\\u0646\\u062a \\u062a\\u0639\\u0628\\u0651\\u0631 \\u0639\\u0646 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0623\\u062d\\u0627\\u0633\\u064a\\u0633 \\u0628\\u0646\\u0641\\u0633 \\u0627\\u0644\\u0637\\u0631\\u064a\\u0642\\u0629\\u060c \\u0648\\u063a\\u0627\\u0644\\u0628\\u064b\\u0627 \\u0645\\u0627 \\u0643\\u0627\\u0646\\u062a \\u062a\\u0636\\u062d\\u0643 \\u062d\\u062a\\u0649 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0648\\u0627\\u0642\\u0641 \\u0627\\u0644\\u062d\\u0632\\u064a\\u0646\\u0629. \\u0643\\u0645\\u0627 \\u0643\\u0627\\u0646\\u062a \\u062a\\u0639\\u0627\\u0646\\u064a \\u0645\\u0646 \\u062e\\u062c\\u0644 \\u0627\\u062c\\u062a\\u0645\\u0627\\u0639\\u064a \\u0634\\u062f\\u064a\\u062f\\u060c \\u0645\\u0645\\u0627 \\u062c\\u0639\\u0644\\u0647\\u0627 \\u0628\\u0639\\u064a\\u062f\\u0629 \\u0639\\u0646 \\u0623\\u0634\\u0642\\u0627\\u0626\\u0647\\u0627 \\u0644\\u0623\\u0646\\u0647\\u0627 \\u0644\\u0645 \\u062a\\u0643\\u0646 \\u062a\\u0639\\u0631\\u0641 \\u0643\\u064a\\u0641\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0623\\u0648 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0639\\u0644 \\u0645\\u0639\\u0647\\u0645.  \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0633\\u0644\\u0633\\u0644\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u062c\\u0644\\u0633\\u0627\\u062a \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a\\u0629\\u060c \\u0637\\u0648\\u0631\\u062a \\u062a\\u062f\\u0631\\u064a\\u062c\\u064a\\u064b\\u0627 \\u0648\\u0639\\u064a\\u064b\\u0627 \\u0639\\u0627\\u0637\\u0641\\u064a\\u064b\\u0627\\u060c \\u0648\\u0645\\u0644\\u0623\\u062a \\u0623\\u0643\\u062b\\u0631 \\u0645\\u0646 \\u0627\\u062b\\u0646\\u062a\\u064a \\u0639\\u0634\\u0631\\u0629 \\u0635\\u0641\\u062d\\u0629 \\u0628\\u062a\\u0623\\u0645\\u0644\\u0627\\u062a \\u062d\\u0648\\u0644 \\u0645\\u0634\\u0627\\u0639\\u0631\\u0647\\u0627 \\u0648\\u0627\\u0644\\u0630\\u0643\\u0631\\u064a\\u0627\\u062a \\u0627\\u0644\\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0647\\u0627. \\u0645\\u0639 \\u0645\\u0631\\u0648\\u0631 \\u0627\\u0644\\u0648\\u0642\\u062a\\u060c \\u062a\\u0639\\u0644\\u0645\\u062a \\u0627\\u0644\\u062a\\u0639\\u0628\\u064a\\u0631 \\u0639\\u0646 \\u0646\\u0641\\u0633\\u0647\\u0627 \\u0628\\u0634\\u0643\\u0644 \\u0623\\u0648\\u0636\\u062d\\u060c \\u0648\\u0627\\u0644\\u062a\\u0641\\u0627\\u0639\\u0644 \\u0645\\u0639 \\u0627\\u0644\\u0622\\u062e\\u0631\\u064a\\u0646 \\u0628\\u0634\\u0643\\u0644 \\u0645\\u0644\\u0645\\u0648\\u0633\\u060c \\u0648\\u0634\\u0627\\u0631\\u0643\\u062a \\u062d\\u062a\\u0649 \\u0641\\u064a \\u062a\\u0645\\u0631\\u064a\\u0646 \\u0633\\u0644\\u0648\\u0643\\u064a \\u2013 \\u062d\\u064a\\u062b \\u0628\\u0627\\u062f\\u0631\\u062a \\u0628\\u0646\\u062c\\u0627\\u062d \\u0628\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0645\\u062d\\u0627\\u062f\\u062b\\u0629 \\u0645\\u0639 \\u0645\\u0645\\u0631\\u0636\\u0629 \\u0639\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0648\\u0633\\u0644\\u0645\\u062a \\u0645\\u0644\\u0641\\u0647\\u0627 \\u0628\\u062b\\u0642\\u0629 \\u062a\\u062d\\u062a \\u0625\\u0634\\u0631\\u0627\\u0641\\u0646\\u0627.  \\u0623\\u0635\\u0628\\u062d\\u062a \\u0627\\u0644\\u0622\\u0646 \\u0623\\u0643\\u062b\\u0631 \\u062a\\u0641\\u0627\\u0639\\u0644\\u064b\\u0627 \\u0627\\u062c\\u062a\\u0645\\u0627\\u0639\\u064a\\u064b\\u0627\\u060c \\u0645\\u0644\\u062a\\u0632\\u0645\\u0629 \\u0628\\u062e\\u0637\\u0629 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0647\\u0627\\u060c \\u0648\\u062a\\u0639\\u0645\\u0644 \\u0628\\u0646\\u0634\\u0627\\u0637 \\u0639\\u0644\\u0649 \\u062a\\u062d\\u0633\\u064a\\u0646 \\u0627\\u0644\\u0633\\u064a\\u0637\\u0631\\u0629 \\u0639\\u0644\\u0649 \\u0645\\u0631\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a \\u0644\\u062f\\u064a\\u0647\\u0627.\"}}]', '[]', '2025-12-26 06:33:44', '2026-02-05 15:22:14'),
(11, '{\"en\":\"Diabetes Technology Unit\",\"ar\":\"وحدة تقنيات السكري\"}', 6, '{\"en\":\"<p>The Diabetes Technology Unit provides advanced solutions for diabetes management through modern devices such as Continuous Glucose Monitoring (CGM) systems and insulin pumps. By leveraging technology, the unit empowers patients to achieve tighter glucose control, reduce complications, and improve quality of life.</p>\",\"ar\":\"<p><br>توفر وحدة تكنولوجيا السكري حلولًا متقدمة لإدارة مرض السكري من خلال أحدث الأجهزة الطبية، مثل أنظمة المراقبة المستمرة للجلوكوز (CGM) ومضخات الأنسولين. ومن خلال توظيف التكنولوجيا الحديثة، تمكّن الوحدة المرضى من تحقيق تحكم أدق في مستويات السكر بالدم، والحد من المضاعفات، وتحسين جودة الحياة.</p>\"}', '{\"en\":\"<p>The unit ensures patients receive comprehensive support from device initiation to continuous follow-up. It integrates seamlessly with endocrinology, nutrition, education, and psychology services to provide holistic care.</p>\",\"ar\":\"<p><strong>نطاق عمل الوحدة</strong><br>تضمن الوحدة حصول المرضى على دعم شامل يبدأ من تركيب الجهاز وحتى المتابعة المستمرة. كما تتكامل خدماتها بسلاسة مع أقسام الغدد الصماء، والتغذية العلاجية، والتثقيف الصحي، والدعم النفسي، لتقديم رعاية متكاملة وشاملة.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627\"},\"content\":{\"en\":\"<p>We support patients who require advanced, technology-based diabetes management using continuous glucose monitoring and insulin pump systems, including those with difficult-to-control glucose levels or high-risk care needs, including those who:<\\/p>\",\"ar\":\"<p>\\u0646\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0630\\u064a\\u0646 \\u064a\\u062d\\u062a\\u0627\\u062c\\u0648\\u0646 \\u0625\\u0644\\u0649 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0645\\u062a\\u0642\\u062f\\u0645\\u0629 \\u0644\\u0644\\u0633\\u0643\\u0631\\u064a \\u062a\\u0639\\u062a\\u0645\\u062f \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0627\\u062a\\u060c \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0623\\u0646\\u0638\\u0645\\u0629 \\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u0627\\u0644\\u062c\\u0644\\u0648\\u0643\\u0648\\u0632 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631\\u0629 \\u0648\\u0623\\u062c\\u0647\\u0632\\u0629 \\u0636\\u062e \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646\\u060c \\u0628\\u0645\\u0627 \\u0641\\u064a \\u0630\\u0644\\u0643 \\u0627\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0630\\u064a\\u0646 \\u064a\\u0635\\u0639\\u0628 \\u0627\\u0644\\u0633\\u064a\\u0637\\u0631\\u0629 \\u0639\\u0644\\u0649 \\u0645\\u0633\\u062a\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0644\\u062f\\u064a\\u0647\\u0645 \\u0623\\u0648 \\u064a\\u062d\\u062a\\u0627\\u062c\\u0648\\u0646 \\u0625\\u0644\\u0649 \\u0631\\u0639\\u0627\\u064a\\u0629 \\u0639\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062e\\u0627\\u0637\\u0631\\u060c \\u0648\\u064a\\u0634\\u0645\\u0644 \\u0630\\u0644\\u0643 \\u0645\\u0646:<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Experience fluctuating glucose levels or hypoglycemia unawareness.\",\"ar\":\"\\t\\u064a\\u0639\\u0627\\u0646\\u0648\\u0646 \\u0645\\u0646 \\u062a\\u0642\\u0644\\u0628\\u0627\\u062a \\u062d\\u0627\\u062f\\u0629 \\u0641\\u064a \\u0645\\u0633\\u062a\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0623\\u0648 \\u0639\\u062f\\u0645 \\u0627\\u0644\\u0625\\u062d\\u0633\\u0627\\u0633 \\u0628\\u0646\\u0648\\u0628\\u0627\\u062a \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631.\"}},{\"text\":{\"en\":\"Struggle with poor control despite multiple daily injections.\",\"ar\":\"\\t\\u0644\\u0627 \\u064a\\u062d\\u0642\\u0642\\u0648\\u0646 \\u062a\\u062d\\u0643\\u0645\\u064b\\u0627 \\u062c\\u064a\\u062f\\u064b\\u0627 \\u0641\\u064a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0631\\u063a\\u0645 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0627\\u0644\\u062d\\u0642\\u0646 \\u0627\\u0644\\u064a\\u0648\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062a\\u0639\\u062f\\u062f\\u0629.\"}},{\"text\":{\"en\":\"Seek advanced, flexible, and precise management tools.\",\"ar\":\"\\t\\u064a\\u0628\\u062d\\u062b\\u0648\\u0646 \\u0639\\u0646 \\u0623\\u062f\\u0648\\u0627\\u062a \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0645\\u062a\\u0642\\u062f\\u0645\\u0629 \\u0648\\u0645\\u0631\\u0646\\u0629 \\u0648\\u0639\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0642\\u0629.\"}},{\"text\":{\"en\":\"Require close glucose monitoring for pregnancy, children, or high-risk cases.\",\"ar\":\"\\t\\u064a\\u062d\\u062a\\u0627\\u062c\\u0648\\u0646 \\u0625\\u0644\\u0649 \\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u062f\\u0642\\u064a\\u0642\\u0629 \\u0644\\u0645\\u0633\\u062a\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631\\u060c \\u0645\\u062b\\u0644 \\u0627\\u0644\\u062d\\u0648\\u0627\\u0645\\u0644 \\u0648\\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644 \\u0648\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0639\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062e\\u0637\\u0648\\u0631\\u0629.\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":69,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":\"\\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\"},\"doctors\":[{\"doctor\":69,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]}]', '[{\"text\":{\"en\":\"Over [X] patients initiated on insulin pumps with excellent outcomes.\",\"ar\":\"\\t\\u0628\\u062f\\u0621 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0628\\u0645\\u0636\\u062e\\u0627\\u062a \\u0627\\u0644\\u0623\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0644\\u0623\\u0643\\u062b\\u0631 \\u0645\\u0646 [X] \\u0645\\u0631\\u064a\\u0636 \\u0645\\u0639 \\u062a\\u062d\\u0642\\u064a\\u0642 \\u0646\\u062a\\u0627\\u0626\\u062c \\u0645\\u0645\\u062a\\u0627\\u0632\\u0629.\"}},{\"text\":{\"en\":\"Successful integration of CGM data into nutrition and endocrinology care plans.\",\"ar\":\"\\u0627\\u0644\\u062f\\u0645\\u062c \\u0627\\u0644\\u0646\\u0627\\u062c\\u062d \\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u0645\\u0631\\u0627\\u0642\\u0628\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0645\\u0631\\u0629 \\u0644\\u0644\\u062c\\u0644\\u0648\\u0643\\u0648\\u0632 \\u0636\\u0645\\u0646 \\u062e\\u0637\\u0637 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u063a\\u0630\\u0627\\u0626\\u064a\\u0629 \\u0648\\u0627\\u0644\\u063a\\u062f\\u062f \\u0627\\u0644\\u0635\\u0645\\u0627\\u0621.\"}},{\"text\":{\"en\":\"Documented reduction in hospital admissions for uncontrolled diabetes.\",\"ar\":\"\\t\\u062a\\u0648\\u062b\\u064a\\u0642 \\u0627\\u0646\\u062e\\u0641\\u0627\\u0636 \\u0645\\u0639\\u062f\\u0644\\u0627\\u062a \\u062f\\u062e\\u0648\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0628\\u0633\\u0628\\u0628 \\u0639\\u062f\\u0645 \\u0627\\u0644\\u062a\\u062d\\u0643\\u0645 \\u0641\\u064a \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a.\"}},{\"text\":{\"en\":\"Patient testimonials showing improved lifestyle flexibility and emotional well-being.\",\"ar\":\"\\t\\u0634\\u0647\\u0627\\u062f\\u0627\\u062a \\u0645\\u0631\\u0636\\u0649 \\u062a\\u0624\\u0643\\u062f \\u062a\\u062d\\u0633\\u0646 \\u0645\\u0631\\u0648\\u0646\\u0629 \\u0646\\u0645\\u0637 \\u0627\\u0644\\u062d\\u064a\\u0627\\u0629 \\u0648\\u0627\\u0644\\u062d\\u0627\\u0644\\u0629 \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a\\u0629.\"}}]', '[{\"text\":{\"en\":\" Adoption of new technologies (drug-coated balloons, shockwave lithotripsy). \",\"ar\":\"\\u0627\\u0639\\u062a\\u0645\\u0627\\u062f \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0627\\u0644\\u062c\\u062f\\u064a\\u062f\\u0629 (\\u0627\\u0644\\u0628\\u0627\\u0644\\u0648\\u0646\\u0627\\u062a \\u0627\\u0644\\u0645\\u0637\\u0644\\u064a\\u0629 \\u0628\\u0627\\u0644\\u0623\\u062f\\u0648\\u064a\\u0629\\u060c \\u0648\\u0645\\u0639\\u0627\\u0644\\u062c\\u0629 \\u0627\\u0644\\u062a\\u0643\\u0644\\u0633 \\u0628\\u0627\\u0644\\u0645\\u0648\\u062c\\u0627\\u062a \\u0627\\u0644\\u0635\\u062f\\u0645\\u064a\\u0629).\"}},{\"text\":{\"en\":\" Announcement of upcoming interventional symposia. \",\"ar\":\"\\u0627\\u0644\\u0625\\u0639\\u0644\\u0627\\u0646 \\u0639\\u0646 \\u0646\\u062f\\u0648\\u0627\\u062a \\u0642\\u0627\\u062f\\u0645\\u0629\"}}]', '2025-12-26 06:33:44', '2026-02-05 15:33:15'),
(13, '{\"en\":\"Psychiatry & Behavioral Sciences \",\"ar\":\"قسم الطب النفسي \"}', 10, '{\"en\":\"<p>The Psychiatry Department at Al Nas Hospital provides specialized mental health care for patients with other medical conditions and their families, recognizing the critical role mental well-being plays in recovery and quality of life. The department integrates psychiatric expertise into the hospital’s multidisciplinary care model, supporting patients across all clinical departments including cardiology, burn, liver transplant, and intensive care through tailored evaluations, therapeutic interventions, and ongoing support.</p>\",\"ar\":\"<p><strong>نظرة عامة</strong><br>يقدّم قسم الطب النفسي في مستشفى الناس رعاية متخصصة للصحة النفسية للمرضى الذين يعانون من حالات طبية أخرى ولأسرهم، مع إدراك الدور الحيوي الذي تلعبه الصحة النفسية في التعافي وجودة الحياة. يدمج القسم الخبرة النفسية ضمن نموذج الرعاية متعددة التخصصات في المستشفى، داعماً المرضى في جميع الأقسام السريرية بما في ذلك أمراض القلب، وحدة الحروق، زراعة الكبد، والعناية المركزة، من خلال تقييمات، تدخلات علاجية، ودعم مستمر.</p>\"}', '{\"en\":\"<p>The Psychiatry Department focuses on prevention, early detection, and management of mental health issues in patients with other medical conditions. The team works hand-in-hand with other specialties to ensure holistic patient management.</p><ul><li><p><strong>Inpatient Consultation &amp; Liaison Services:</strong> Daily rounds to provide psychiatric assessments for hospitalized patients, with interventions tailored to complex medical and surgical cases.</p></li><li><p><strong>Outpatient Psychiatric Care:</strong> Follow-up clinics for patients with ongoing psychiatric needs, including mood disorders, anxiety, and adjustment issues.</p></li><li><p><strong>Psychological Counseling &amp; Therapy Programs:</strong> Individual and family therapy to support coping strategies, stress management, and adjustment to chronic illness.</p></li><li><p><strong>Research, Training &amp; Education:</strong> Academic contributions in hospital psychiatry, training for healthcare providers on mental health integration, and community awareness programs.</p></li></ul>\",\"ar\":\"<p><strong>نطاق عمل القسم</strong><br>يركز قسم الطب النفسي على الوقاية، الكشف المبكر، وإدارة المشكلات النفسية لدى المرضى الذين يعانون من حالات طبية أخرى. ويعمل الفريق جنباً إلى جنب مع التخصصات الأخرى لضمان إدارة شاملة للمرضى.</p><ul><li><p><strong>خدمات الاستشارة النفسية للمرضى الداخليين والتواصل بين الأقسام:</strong> جولات يومية لتقديم تقييمات نفسية للمرضى الداخليين، مع تدخلات مخصصة للحالات الطبية والجراحية المعقدة.</p></li><li><p><strong>الرعاية النفسية للمرضى الخارجيين:</strong> عيادات متابعة للمرضى الذين يحتاجون إلى رعاية نفسية مستمرة، بما في ذلك اضطرابات المزاج، القلق، ومشكلات التكيف.</p></li><li><p><strong>برامج الإرشاد النفسي والعلاج النفسي:</strong> جلسات علاج فردية وعائلية لدعم استراتيجيات التكيف، إدارة التوتر، والتكيف مع الأمراض المزمنة.</p></li><li><p><strong>البحث، التدريب والتعليم:</strong> مساهمات أكاديمية في الطب النفسي بالمستشفيات، تدريب مقدمي الرعاية الصحية على دمج الصحة النفسية، وبرامج التوعية المجتمعية.</p></li></ul>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u0646\\u0639\\u0627\\u0644\\u062c\\u0647\\u0627\"},\"content\":{\"en\":\"<p>We assess and manage mental health and psychiatric conditions through comprehensive diagnostic evaluation and evidence-based therapeutic interventions, supporting emotional well-being, functional recovery, and long-term mental health stability:<\\/p>\",\"ar\":\"<p>\\u0646\\u0642\\u0648\\u0645 \\u0628\\u062a\\u0642\\u064a\\u064a\\u0645 \\u0648\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0639\\u0642\\u0644\\u064a\\u0629 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u062a\\u0642\\u064a\\u064a\\u0645 \\u062a\\u0634\\u062e\\u064a\\u0635\\u064a \\u0634\\u0627\\u0645\\u0644 \\u0648\\u062a\\u0637\\u0628\\u064a\\u0642 \\u062a\\u062f\\u062e\\u0644\\u0627\\u062a \\u0639\\u0644\\u0627\\u062c\\u064a\\u0629 \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u062f\\u0644\\u0629\\u060c \\u0628\\u0647\\u062f\\u0641 \\u062f\\u0639\\u0645 \\u0627\\u0644\\u0635\\u062d\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0637\\u0641\\u064a\\u0629\\u060c \\u0648\\u062a\\u0639\\u0627\\u0641\\u064a \\u0627\\u0644\\u0648\\u0638\\u0627\\u0626\\u0641\\u060c \\u0648\\u062a\\u062d\\u0642\\u064a\\u0642 \\u0627\\u0633\\u062a\\u0642\\u0631\\u0627\\u0631 \\u0627\\u0644\\u0635\\u062d\\u0629 \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u062f\\u0649 \\u0627\\u0644\\u0637\\u0648\\u064a\\u0644.<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Depression, anxiety, and mood disorders.\",\"ar\":\"\\u0627\\u0644\\u0627\\u0643\\u062a\\u0626\\u0627\\u0628\\u060c \\u0627\\u0644\\u0642\\u0644\\u0642\\u060c \\u0648\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0645\\u0632\\u0627\\u062c.\"}},{\"text\":{\"en\":\"Stress-related and adjustment disorders in patients with other medical conditions.\",\"ar\":\"\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u062a\\u0648\\u062a\\u0631 \\u0648\\u0627\\u0644\\u062a\\u0643\\u064a\\u0641 \\u0644\\u062f\\u0649 \\u0627\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0630\\u064a\\u0646 \\u064a\\u0639\\u0627\\u0646\\u0648\\u0646 \\u0645\\u0646 \\u062d\\u0627\\u0644\\u0627\\u062a \\u0637\\u0628\\u064a\\u0629 \\u0623\\u062e\\u0631\\u0649.\"}},{\"text\":{\"en\":\"Delirium, cognitive impairment, and behavioral changes during hospitalization.\",\"ar\":\"\\t\\u0627\\u0644\\u0647\\u0630\\u064a\\u0627\\u0646\\u060c \\u0636\\u0639\\u0641 \\u0627\\u0644\\u0625\\u062f\\u0631\\u0627\\u0643\\u060c \\u0648\\u0627\\u0644\\u062a\\u063a\\u064a\\u0631\\u0627\\u062a \\u0627\\u0644\\u0633\\u0644\\u0648\\u0643\\u064a\\u0629 \\u0623\\u062b\\u0646\\u0627\\u0621 \\u0627\\u0644\\u062a\\u0646\\u0648\\u064a\\u0645.\"}},{\"text\":{\"en\":\"Substance use disorders.\",\"ar\":\"\\t\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u062a\\u0639\\u0627\\u0637\\u064a \\u0627\\u0644\\u0645\\u0648\\u0627\\u062f \\u0627\\u0644\\u0645\\u062e\\u062f\\u0631\\u0629.\"}},{\"text\":{\"en\":\"Psychiatric complications associated with chronic disease, surgery and drug induced psychiatric disorders.\",\"ar\":\"\\u2022\\t\\u0627\\u0644\\u0645\\u0636\\u0627\\u0639\\u0641\\u0627\\u062a \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0631\\u062a\\u0628\\u0637\\u0629 \\u0628\\u0627\\u0644\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0645\\u0632\\u0645\\u0646\\u0629\\u060c \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u0629\\u060c \\u0648\\u0627\\u0644\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a\\u0629 \\u0627\\u0644\\u0646\\u0627\\u062a\\u062c\\u0629 \\u0639\\u0646 \\u0627\\u0644\\u0623\\u062f\\u0648\\u064a\\u0629.\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":69,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":\"\\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\"},\"doctors\":[{\"doctor\":73,\"doctor_title\":{\"en\":\"DR\",\"ar\":\"\\u062f\"}}]}]', '[{\"text\":{\"en\":\".\",\"ar\":\"88 ar\"}},{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '[{\"text\":{\"en\":\"Holistic screening for psychiatric disorders especially depression for newly admitted patients in the hospital.\",\"ar\":\"\\t\\u0641\\u062d\\u0635 \\u0634\\u0627\\u0645\\u0644 \\u0644\\u0644\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a\\u0629\\u060c \\u062e\\u0627\\u0635\\u0629 \\u0627\\u0644\\u0627\\u0643\\u062a\\u0626\\u0627\\u0628\\u060c \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u062c\\u062f\\u062f \\u0628\\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649.\"}},{\"text\":{\"en\":\"Autism unit under construction\",\"ar\":\"\\t\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0648\\u062d\\u062f\\u0629 \\u0627\\u0644\\u062a\\u0648\\u062d\\u062f\"}},{\"text\":{\"en\":\"Launch of hospital-wide mental health awareness campaigns.\",\"ar\":\"\\u0637\\u0644\\u0627\\u0642 \\u062d\\u0645\\u0644\\u0627\\u062a \\u062a\\u0648\\u0639\\u064a\\u0629 \\u0628\\u0627\\u0644\\u0635\\u062d\\u0629 \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a\\u0629 \\u0639\\u0644\\u0649 \\u0645\\u0633\\u062a\\u0648\\u0649 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649.\"}},{\"text\":{\"en\":\"Expansion of consultation services to all inpatient wards.\",\"ar\":\"\\u062a\\u0648\\u0633\\u064a\\u0639 \\u062e\\u062f\\u0645\\u0627\\u062a \\u0627\\u0644\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0629 \\u0644\\u062a\\u0634\\u0645\\u0644 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0623\\u0642\\u0633\\u0627\\u0645 \\u0627\\u0644\\u062f\\u0627\\u062e\\u0644\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Introduction of structured caregiver support programs.\",\"ar\":\"\\t\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0628\\u0631\\u0627\\u0645\\u062c \\u062f\\u0639\\u0645 \\u0645\\u0646\\u0638\\u0645\\u0629 \\u0644\\u0645\\u0642\\u062f\\u0645\\u064a \\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Upcoming training courses on psychosomatic medicine and hospital psychiatry.\",\"ar\":\"\\t\\u062a\\u0646\\u0638\\u064a\\u0645 \\u062f\\u0648\\u0631\\u0627\\u062a \\u062a\\u062f\\u0631\\u064a\\u0628\\u064a\\u0629 \\u0642\\u0627\\u062f\\u0645\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0637\\u0628 \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a \\u0627\\u0644\\u062c\\u0633\\u062f\\u064a \\u0648\\u0627\\u0644\\u0637\\u0628 \\u0627\\u0644\\u0646\\u0641\\u0633\\u064a \\u0628\\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649.\"}}]', '2025-12-26 06:33:44', '2026-02-05 15:42:00'),
(14, '{\"en\":\"Adult Medical Unit\",\"ar\":\"وحدة الجهاز الهضمي للكبار\"}', 9, '{\"en\":\"<p>The Adult Medical Unit provides comprehensive, non-surgical care for adults with a wide range of gastrointestinal, hepatic, and pancreatic conditions. The unit focuses on advanced diagnostics, evidence-based medical management, and long-term disease monitoring, including inflammatory bowel disease, functional disorders, and complex nutritional needs, ensuring personalized treatment plans and coordinated multidisciplinary care.</p>\",\"ar\":\"<p>تُقدم وحدة الجهاز الهضمي للكبار رعاية طبية متكاملة غير جراحية للبالغين المصابين بمختلف أمراض الجهاز الهضمي والكبد والبنكرياس. وتركز الوحدة على التشخيص المتقدم، والعلاج الطبي القائم على الأدلة العلمية، والمتابعة طويلة الأمد للأمراض المزمنة، بما في ذلك أمراض الأمعاء الالتهابية، والاضطرابات الوظيفية، والحالات الغذائية المعقدة، مع توفير خطط علاجية مخصصة ورعاية متعددة التخصصات منسقة.</p>\"}', '{\"en\":\"<p>This unit delivers in-depth assessment and non-operative management for adults with disorders of the digestive system, liver, and pancreas. Services encompass the care of chronic inflammatory and immune-related conditions, functional and motility disorders, and long-term nutritional challenges, supported by advanced testing, individualized therapy plans, and coordinated follow-up across multiple specialties.</p>\",\"ar\":\"<p>تختص الوحدة بالتقييم الدقيق والعلاج غير الجراحي لاضطرابات الجهاز الهضمي والكبد والبنكرياس لدى البالغين. وتشمل الخدمات علاج الأمراض الالتهابية والمناعية المزمنة، واضطرابات الحركة والوظيفة الهضمية، ومشكلات التغذية طويلة الأمد، مدعومة بفحوصات تشخيصية متقدمة، وخطط علاج فردية، ومتابعة منسقة بين مختلف التخصصات الطبية.تختص الوحدة بالتقييم الدقيق والعلاج غير الجراحي لاضطرابات الجهاز الهضمي والكبد والبنكرياس لدى البالغين. وتشمل الخدمات علاج الأمراض الالتهابية والمناعية المزمنة، واضطرابات الحركة والوظيفة الهضمية، ومشكلات التغذية طويلة الأمد، مدعومة بفحوصات تشخيصية متقدمة، وخطط علاج فردية، ومتابعة منسقة بين مختلف التخصصات الطبية.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\" \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627\"},\"content\":{\"en\":\"<p>Comprehensive medical care for complex gastrointestinal, hepatic, and pancreatic conditions through advanced diagnostics, evidence-based treatment, and long-term disease management.<\\/p>\",\"ar\":\"<p>\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0637\\u0628\\u064a\\u0629 \\u0634\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u0642\\u062f\\u0629 \\u0644\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a \\u0648\\u0627\\u0644\\u0643\\u0628\\u062f \\u0648\\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u062a\\u0634\\u062e\\u064a\\u0635 \\u0645\\u062a\\u0642\\u062f\\u0645\\u060c \\u0648\\u0639\\u0644\\u0627\\u062c \\u0637\\u0628\\u064a \\u0642\\u0627\\u0626\\u0645 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u062f\\u0644\\u0629\\u060c \\u0648\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0637\\u0648\\u064a\\u0644\\u0629 \\u0627\\u0644\\u0623\\u0645\\u062f \\u0644\\u0644\\u0645\\u0631\\u0636.<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Hereditary, congenital, autoimmune, and malignant disorders (e.g., Crohn\\u2019s disease, ulcerative colitis, GI tumors).\",\"ar\":\"\\t\\u0627\\u0644\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0648\\u0631\\u0627\\u062b\\u064a\\u0629\\u060c \\u0627\\u0644\\u062e\\u0650\\u0644\\u0642\\u064a\\u0629\\u060c \\u0627\\u0644\\u0645\\u0646\\u0627\\u0639\\u064a\\u0629\\u060c \\u0648\\u0627\\u0644\\u0623\\u0648\\u0631\\u0627\\u0645 (\\u0645\\u062b\\u0644 \\u062f\\u0627\\u0621 \\u0643\\u0631\\u0648\\u0646\\u060c \\u0627\\u0644\\u062a\\u0647\\u0627\\u0628 \\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 \\u0627\\u0644\\u062a\\u0642\\u0631\\u062d\\u064a\\u060c \\u0623\\u0648\\u0631\\u0627\\u0645 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a).\"}},{\"text\":{\"en\":\"Gut dysmotility syndromes and rare GI disorders.\",\"ar\":\"\\t\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u062d\\u0631\\u0643\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 \\u0648\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0646\\u0627\\u062f\\u0631\\u0629.\"}},{\"text\":{\"en\":\"Gallbladder and pancreatic conditions: gallstones, cholecystitis, obstructive jaundice, pancreatitis, pancreatic cysts, pancreatic cancer.\",\"ar\":\"\\t\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0645\\u0631\\u0627\\u0631\\u0629 \\u0648\\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633: \\u062d\\u0635\\u0648\\u0627\\u062a \\u0627\\u0644\\u0645\\u0631\\u0627\\u0631\\u0629\\u060c \\u0627\\u0644\\u062a\\u0647\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0631\\u0627\\u0631\\u0629\\u060c \\u0627\\u0644\\u064a\\u0631\\u0642\\u0627\\u0646 \\u0627\\u0644\\u0627\\u0646\\u0633\\u062f\\u0627\\u062f\\u064a\\u060c \\u0627\\u0644\\u062a\\u0647\\u0627\\u0628 \\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633\\u060c \\u0623\\u0643\\u064a\\u0627\\u0633 \\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633\\u060c \\u0633\\u0631\\u0637\\u0627\\u0646 \\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633.\"}},{\"text\":{\"en\":\"Esophageal and gastric diseases: GERD, dysphagia, strictures, peptic ulcer disease, gastritis, H. pylori infection, non-variceal upper GI bleeding.\",\"ar\":\"\\t\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621 \\u0648\\u0627\\u0644\\u0645\\u0639\\u062f\\u0629: \\u0627\\u0644\\u0627\\u0631\\u062a\\u062c\\u0627\\u0639 \\u0627\\u0644\\u0645\\u0639\\u062f\\u064a \\u0627\\u0644\\u0645\\u0631\\u064a\\u0626\\u064a\\u060c \\u0639\\u0633\\u0631 \\u0627\\u0644\\u0628\\u0644\\u0639\\u060c \\u0627\\u0644\\u062a\\u0636\\u064a\\u0642\\u0627\\u062a\\u060c \\u0642\\u0631\\u062d\\u0629 \\u0627\\u0644\\u0645\\u0639\\u062f\\u0629 \\u0648\\u0627\\u0644\\u0627\\u062b\\u0646\\u064a \\u0639\\u0634\\u0631\\u060c \\u0627\\u0644\\u062a\\u0647\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0639\\u062f\\u0629\\u060c \\u0639\\u062f\\u0648\\u0649 \\u0627\\u0644\\u062c\\u0631\\u062b\\u0648\\u0645\\u0629 \\u0627\\u0644\\u062d\\u0644\\u0632\\u0648\\u0646\\u064a\\u0629\\u060c \\u0627\\u0644\\u0646\\u0632\\u064a\\u0641 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a \\u0627\\u0644\\u0639\\u0644\\u0648\\u064a \\u063a\\u064a\\u0631 \\u0627\\u0644\\u062f\\u0648\\u0627\\u0644\\u064a.\"}},{\"text\":{\"en\":\"Intestinal and colonic diseases: chronic diarrhea, malabsorption, GI allergies, constipation, colonic inertia, gut dysmotility, diverticular disease, obstruction, IBD, vascular bowel disease, short bowel syndrome, bacterial overgrowth, celiac disease, CRC screening, colorectal cancer, fecal incontinence, pelvic floor dyssynergia.\",\"ar\":\"\\u2022\\t\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646: \\u0627\\u0644\\u0625\\u0633\\u0647\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0632\\u0645\\u0646\\u060c \\u0633\\u0648\\u0621 \\u0627\\u0644\\u0627\\u0645\\u062a\\u0635\\u0627\\u0635\\u060c \\u062d\\u0633\\u0627\\u0633\\u064a\\u0629 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a\\u060c \\u0627\\u0644\\u0625\\u0645\\u0633\\u0627\\u0643\\u060c \\u062e\\u0645\\u0648\\u0644 \\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646\\u060c \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u062d\\u0631\\u0643\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0648\\u064a\\u0629\\u060c \\u0645\\u0631\\u0636 \\u0627\\u0644\\u0631\\u062a\\u0648\\u062c\\u060c \\u0627\\u0644\\u0627\\u0646\\u0633\\u062f\\u0627\\u062f \\u0627\\u0644\\u0645\\u0639\\u0648\\u064a\\u060c \\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 \\u0627\\u0644\\u0627\\u0644\\u062a\\u0647\\u0627\\u0628\\u064a\\u0629\\u060c \\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0623\\u0648\\u0639\\u064a\\u0629 \\u0627\\u0644\\u062f\\u0645\\u0648\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0648\\u064a\\u0629\\u060c \\u0645\\u062a\\u0644\\u0627\\u0632\\u0645\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 \\u0627\\u0644\\u0642\\u0635\\u064a\\u0631\\u0629\\u060c \\u0641\\u0631\\u0637 \\u0627\\u0644\\u0646\\u0645\\u0648 \\u0627\\u0644\\u0628\\u0643\\u062a\\u064a\\u0631\\u064a\\u060c \\u0627\\u0644\\u062f\\u0627\\u0621 \\u0627\\u0644\\u0628\\u0637\\u0646\\u064a (\\u0627\\u0644\\u0633\\u064a\\u0644\\u064a\\u0627\\u0643)\\u060c \\u0641\\u062d\\u0648\\u0635\\u0627\\u062a \\u0633\\u0631\\u0637\\u0627\\u0646 \\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 \\u0648\\u0627\\u0644\\u0645\\u0633\\u062a\\u0642\\u064a\\u0645\\u060c \\u0633\\u0631\\u0637\\u0627\\u0646 \\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 \\u0648\\u0627\\u0644\\u0645\\u0633\\u062a\\u0642\\u064a\\u0645\\u060c \\u0633\\u0644\\u0633 \\u0627\\u0644\\u0628\\u0631\\u0627\\u0632\\u060c \\u0648\\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u0627\\u062a \\u0639\\u0636\\u0644\\u0627\\u062a \\u0642\\u0627\\u0639 \\u0627\\u0644\\u062d\\u0648\\u0636.\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":31,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":35,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":\"\\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\"},\"doctors\":[]}]', '[{\"text\":{\"en\":\".\",\"ar\":\"88 ar\"}},{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '[{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '2025-12-26 06:33:44', '2026-02-12 15:23:32');
INSERT INTO `department_sections` (`id`, `title`, `department_id`, `overview`, `scope_of_unit`, `what_we_treat`, `leadership`, `achievements`, `news`, `created_at`, `updated_at`) VALUES
(15, '{\"en\":\"Adult Surgical Unit\",\"ar\":\"وحدة جراحة الجهاز الهضمى للكبار\"}', 9, '{\"en\":\"<p>The Adult Surgical Unit delivers specialized surgical care for complex gastrointestinal, hepatobiliary, and pancreatic disorders. The unit is equipped to manage both benign and malignant conditions through advanced open and minimally invasive techniques, offering precision-driven interventions, postoperative rehabilitation, and integrated follow-up to support optimal recovery and long-term outcomes.</p>\",\"ar\":\"<p>تُقدم وحدة الجراحة للكبار رعاية جراحية متخصصة للحالات المعقدة لأمراض الجهاز الهضمي والكبد والقنوات المرارية والبنكرياس. وتعتمد الوحدة على أحدث التقنيات الجراحية المفتوحة والجراحات محدودة التدخل لعلاج الحالات الحميدة والخبيثة، مع توفير رعاية ما بعد الجراحة، وإعادة التأهيل، والمتابعة المتكاملة لضمان أفضل النتائج على المدى القريب والبعيد.</p>\"}', '{\"en\":\"<p>The Adult Surgical Unit addresses complex conditions requiring operative intervention within the gastrointestinal, biliary, and pancreatic systems. Its remit includes major resections, corrective and restorative procedures, management of abdominal wall and intestinal failure cases, and comprehensive perioperative care, reinforced by integrated anesthesia services and critical-care support.</p>\",\"ar\":\"<p>تتعامل الوحدة مع الحالات المعقدة التي تتطلب تدخلاً جراحيًا في الجهاز الهضمي والمرارة والبنكرياسي، وتشمل عمليات الاستئصال الكبرى، والإجراءات التصحيحية والترميمية، وحالات فشل الأمعاء وجدار البطن، إضافة إلى رعاية شاملة خلال فترة ما قبل وبعد الجراحة بدعم من خدمات التخدير والعناية المركزة.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627 \"},\"content\":{\"en\":\"<p>Specialized surgical solutions for benign and malignant gastrointestinal, hepatobiliary, and pancreatic disorders using advanced operative and reconstructive techniques.<\\/p>\",\"ar\":\"<p>\\u062d\\u0644\\u0648\\u0644 \\u062c\\u0631\\u0627\\u062d\\u064a\\u0629 \\u0645\\u062a\\u0642\\u062f\\u0645\\u0629 \\u0644\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062d\\u0645\\u064a\\u062f\\u0629 \\u0648\\u0627\\u0644\\u062e\\u0628\\u064a\\u062b\\u0629 \\u0644\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a \\u0648\\u0627\\u0644\\u0643\\u0628\\u062f \\u0648\\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0623\\u062d\\u062f\\u062b \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0631\\u0645\\u064a\\u0645\\u064a\\u0629.<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Esophageal Surgery: reconstruction, esophagectomy and replacement (gastric pull-up, colon interposition), Heller myotomy, fundoplication (Nissen, Toupet), redo complex reconstructions.\",\"ar\":\"\\t\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621: \\u0625\\u0639\\u0627\\u062f\\u0629 \\u0628\\u0646\\u0627\\u0621 \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621\\u060c \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621 \\u0648\\u062a\\u0639\\u0648\\u064a\\u0636\\u0647 (\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0645\\u0639\\u062f\\u0629 \\u0623\\u0648 \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646)\\u060c \\u0634\\u0642 \\u0639\\u0636\\u0644\\u0629 \\u0647\\u064a\\u0644\\u0631\\u060c \\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u062a\\u062b\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0642\\u0627\\u0639 (\\u0646\\u064a\\u0633\\u0646\\u060c \\u062a\\u0648\\u0628\\u064a\\u0647)\\u060c \\u0648\\u0625\\u0639\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0642\\u062f\\u0629.\"}},{\"text\":{\"en\":\"Gastric & Duodenal Surgery: gastrectomy (total, partial, sleeve, Roux-en-Y), bariatric revision procedures, pyloroplasty, pyloromyotomy.\",\"ar\":\"\\t\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u062f\\u0629 \\u0648\\u0627\\u0644\\u0627\\u062b\\u0646\\u064a \\u0639\\u0634\\u0631: \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0639\\u062f\\u0629 (\\u0643\\u0644\\u064a\\/\\u062c\\u0632\\u0626\\u064a\\/\\u062a\\u0643\\u0645\\u064a\\u0645\\u064a\\/\\u062a\\u062d\\u0648\\u064a\\u0644 \\u0645\\u0633\\u0627\\u0631)\\u060c \\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0633\\u0645\\u0646\\u0629 \\u0627\\u0644\\u062a\\u0635\\u062d\\u064a\\u062d\\u064a\\u0629\\u060c \\u062a\\u0648\\u0633\\u064a\\u0639 \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u060c \\u0634\\u0642 \\u0639\\u0636\\u0644\\u0629 \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628.\"}},{\"text\":{\"en\":\"Intestinal & Colorectal Surgery: total\\/partial colectomy (open\\/laparoscopic), procto-colectomy, low\\/ultra-low anterior resection, abdominoperineal resection (intersphincteric), colon pull-through, bowel lengthening (STEP), resections for IBD and tumors.\",\"ar\":\"\\t\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 \\u0648\\u0627\\u0644\\u0645\\u0633\\u062a\\u0642\\u064a\\u0645: \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 \\u0627\\u0644\\u0643\\u0644\\u064a \\u0623\\u0648 \\u0627\\u0644\\u062c\\u0632\\u0626\\u064a (\\u0645\\u0641\\u062a\\u0648\\u062d \\u0623\\u0648 \\u0628\\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631)\\u060c \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 \\u0648\\u0627\\u0644\\u0645\\u0633\\u062a\\u0642\\u064a\\u0645\\u060c \\u0627\\u0644\\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0627\\u0645\\u064a \\u0627\\u0644\\u0645\\u0646\\u062e\\u0641\\u0636\\u060c \\u0627\\u0644\\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0628\\u0637\\u0646\\u064a \\u0627\\u0644\\u0639\\u062c\\u0627\\u0646\\u064a\\u060c \\u0633\\u062d\\u0628 \\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646\\u060c \\u0625\\u0637\\u0627\\u0644\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 (STEP)\\u060c \\u0648\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0623\\u0648\\u0631\\u0627\\u0645 \\u0648\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 \\u0627\\u0644\\u0627\\u0644\\u062a\\u0647\\u0627\\u0628\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Hepatobiliary & Pancreatic Surgery: Whipple\\u2019s procedure, distal pancreatectomy, hepatectomy (segmental\\/extended), bile duct exploration, reconstruction.\",\"ar\":\"\\t\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0643\\u0628\\u062f \\u0648\\u0627\\u0644\\u0645\\u0631\\u0627\\u0631\\u0629 \\u0648\\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633: \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0648\\u064a\\u0628\\u0644\\u060c \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633 \\u0627\\u0644\\u0628\\u0639\\u064a\\u062f\\u060c \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0643\\u0628\\u062f \\u0627\\u0644\\u062c\\u0632\\u0626\\u064a \\u0623\\u0648 \\u0627\\u0644\\u0645\\u0648\\u0633\\u0639\\u060c \\u0627\\u0633\\u062a\\u0643\\u0634\\u0627\\u0641 \\u0648\\u0625\\u0639\\u0627\\u062f\\u0629 \\u0628\\u0646\\u0627\\u0621 \\u0627\\u0644\\u0642\\u0646\\u0648\\u0627\\u062a \\u0627\\u0644\\u0645\\u0631\\u0627\\u0631\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Abdominal Wall & Hernia Surgery: open\\/laparoscopic hernia repairs (inguinal, umbilical, incisional, femoral), abdominal wall\\/peritoneal tumor resections.\",\"ar\":\"\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u062c\\u062f\\u0627\\u0631 \\u0627\\u0644\\u0628\\u0637\\u0646 \\u0648\\u0627\\u0644\\u0641\\u062a\\u0648\\u0642: \\u0625\\u0635\\u0644\\u0627\\u062d \\u0627\\u0644\\u0641\\u062a\\u0648\\u0642 \\u0627\\u0644\\u0645\\u0641\\u062a\\u0648\\u062d\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631\\u064a\\u0629 (\\u0627\\u0644\\u0625\\u0631\\u0628\\u064a\\u0629\\u060c \\u0627\\u0644\\u0633\\u064f\\u0631\\u064a\\u0629\\u060c \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u064a\\u0629\\u060c \\u0627\\u0644\\u0641\\u062e\\u0630\\u064a\\u0629)\\u060c \\u0648\\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0623\\u0648\\u0631\\u0627\\u0645 \\u062c\\u062f\\u0627\\u0631 \\u0627\\u0644\\u0628\\u0637\\u0646 \\u0648\\u0627\\u0644\\u0635\\u0641\\u0627\\u0642.\"}},{\"text\":{\"en\":\"Vascular Surgery: esophageal varices management (portovenous shunts).\",\"ar\":\"\\t\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0623\\u0648\\u0639\\u064a\\u0629: \\u0639\\u0644\\u0627\\u062c \\u062f\\u0648\\u0627\\u0644\\u064a \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621 (\\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0627\\u0644\\u0628\\u0627\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0648\\u0631\\u064a\\u062f\\u064a\\u0629).\"}},{\"text\":{\"en\":\"Other: splenectomy, adrenalectomy, diaphragmatic hernia repair, adhesiolysis, advanced laparoscopic resections.\",\"ar\":\"\\t\\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0623\\u062e\\u0631\\u0649: \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0637\\u062d\\u0627\\u0644\\u060c \\u0627\\u0644\\u063a\\u062f\\u0629 \\u0627\\u0644\\u0643\\u0638\\u0631\\u064a\\u0629\\u060c \\u0625\\u0635\\u0644\\u0627\\u062d \\u0641\\u062a\\u0642 \\u0627\\u0644\\u062d\\u062c\\u0627\\u0628 \\u0627\\u0644\\u062d\\u0627\\u062c\\u0632\\u060c \\u0641\\u0643 \\u0627\\u0644\\u0627\\u0644\\u062a\\u0635\\u0627\\u0642\\u0627\\u062a\\u060c \\u0648\\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u0629 \\u0628\\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631\"}},{\"text\":{\"en\":\"Future Expansion: intestinal transplantation programs.\",\"ar\":\"\\t\\u062e\\u0637\\u0637 \\u0645\\u0633\\u062a\\u0642\\u0628\\u0644\\u064a\\u0629: \\u0628\\u0631\\u0627\\u0645\\u062c \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621.\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":31,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":28,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":\"\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0639\\u0645\\u0644\"},\"doctors\":[{\"doctor\":29,\"doctor_title\":{\"en\":\"Associate Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u064a \\u0645\\u0633\\u0627\\u0639\\u062f\"}},{\"doctor\":30,\"doctor_title\":{\"en\":\"Associate Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u064a \\u0645\\u0633\\u0627\\u0639\\u062f\"}}]}]', '[{\"text\":{\"en\":\".\",\"ar\":\"88 ar\"}},{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '[{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '2025-12-26 06:33:44', '2026-02-12 15:35:14'),
(16, '{\"en\":\"Pediatric Medical Unit\",\"ar\":\"وحدة الجهاز الهضمي للأطفال\"}', 9, '{\"en\":\"<p>The Pediatric Medical Unit is dedicated to the medical management of gastrointestinal and nutritional disorders in infants, children, and adolescents. The unit provides family-centered care through early diagnosis, tailored medical therapies, and continuous monitoring for congenital, autoimmune, and chronic digestive conditions, with a strong emphasis on growth, development, and quality of life.</p>\",\"ar\":\"<p>تختص وحدة الجهاز الهضمي للأطفال بالإدارة الطبية لأمراض الجهاز الهضمي والتغذية لدى الرضع والأطفال والمراهقين. وتُقدم الوحدة رعاية شاملة قائمة على إشراك الأسرة، من خلال التشخيص المبكر، والعلاجات الطبية المصممة خصيصًا لكل حالة، والمتابعة المستمرة للأمراض الخِلقية والمناعية والمزمنة، مع التركيز على النمو والتطور وجودة الحياة.</p>\"}', '{\"en\":\"<p>This unit focuses on the evaluation and medical treatment of digestive and nutritional conditions affecting infants, children, and adolescents. Care extends to congenital and inherited disorders, long-standing inflammatory diseases, and feeding or absorption challenges, with an emphasis on developmental monitoring, tailored therapies, and continuous family engagement.</p>\",\"ar\":\"<p>تركز الوحدة على تقييم وعلاج أمراض الجهاز الهضمي والتغذية التي تصيب الرضع والأطفال والمراهقين، وتشمل الاضطرابات الخِلقية والوراثية، والأمراض الالتهابية المزمنة، ومشكلات التغذية والامتصاص، مع متابعة دقيقة للنمو والتطور وتواصل مستمر مع الأسرة.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627\"},\"content\":{\"en\":\"<p>Family-centered medical care for congenital, hereditary, and chronic digestive conditions in children, with a focus on early diagnosis, growth, and long-term health.<\\/p>\",\"ar\":\"<p>\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0637\\u0628\\u064a\\u0629 \\u0645\\u062a\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0635\\u0627\\u0628\\u064a\\u0646 \\u0628\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a \\u0627\\u0644\\u062e\\u0650\\u0644\\u0642\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0648\\u0631\\u0627\\u062b\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0632\\u0645\\u0646\\u0629\\u060c \\u0645\\u0639 \\u0627\\u0644\\u062a\\u0631\\u0643\\u064a\\u0632 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0634\\u062e\\u064a\\u0635 \\u0627\\u0644\\u0645\\u0628\\u0643\\u0631 \\u0648\\u0627\\u0644\\u0646\\u0645\\u0648 \\u0627\\u0644\\u0635\\u062d\\u064a \\u0637\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0645\\u062f.<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Covers neonates (0\\u201328 days), pediatrics (1 month\\u201313 years), adolescents (13-18 years).\",\"ar\":\"\\u062a\\u0634\\u0645\\u0644 \\u0627\\u0644\\u0641\\u0626\\u0627\\u062a \\u0627\\u0644\\u0639\\u0645\\u0631\\u064a\\u0629: \\u062d\\u062f\\u064a\\u062b\\u064a \\u0627\\u0644\\u0648\\u0644\\u0627\\u062f\\u0629 (0\\u201328 \\u064a\\u0648\\u0645\\u064b\\u0627)\\u060c \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644 (\\u0634\\u0647\\u0631\\u201313 \\u0633\\u0646\\u0629)\\u060c \\u0627\\u0644\\u0645\\u0631\\u0627\\u0647\\u0642\\u064a\\u0646 (13\\u201318 \\u0633\\u0646\\u0629).\"}},{\"text\":{\"en\":\"Congenital GI and hepatobiliary disorders.\",\"ar\":\"\\t\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a \\u0648\\u0627\\u0644\\u0643\\u0628\\u062f \\u0648\\u0627\\u0644\\u0645\\u0631\\u0627\\u0631\\u0629 \\u0627\\u0644\\u062e\\u0650\\u0644\\u0642\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Pediatric liver diseases: neonatal cholestasis, biliary atresia, autoimmune hepatitis, acute\\/chronic liver failure, cirrhosis, metabolic liver disease.\",\"ar\":\"\\t\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0643\\u0628\\u062f \\u0644\\u062f\\u0649 \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644: \\u0627\\u0644\\u0631\\u0643\\u0648\\u062f \\u0627\\u0644\\u0635\\u0641\\u0631\\u0627\\u0648\\u064a \\u0627\\u0644\\u0648\\u0644\\u064a\\u062f\\u064a\\u060c \\u0631\\u062a\\u0642 \\u0627\\u0644\\u0642\\u0646\\u0648\\u0627\\u062a \\u0627\\u0644\\u0645\\u0631\\u0627\\u0631\\u064a\\u0629\\u060c \\u0627\\u0644\\u062a\\u0647\\u0627\\u0628 \\u0627\\u0644\\u0643\\u0628\\u062f \\u0627\\u0644\\u0645\\u0646\\u0627\\u0639\\u064a\\u060c \\u0627\\u0644\\u0641\\u0634\\u0644 \\u0627\\u0644\\u0643\\u0628\\u062f\\u064a \\u0627\\u0644\\u062d\\u0627\\u062f \\u0648\\u0627\\u0644\\u0645\\u0632\\u0645\\u0646\\u060c \\u0627\\u0644\\u062a\\u0644\\u064a\\u0641 \\u0627\\u0644\\u0643\\u0628\\u062f\\u064a\\u060c \\u0648\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0643\\u0628\\u062f \\u0627\\u0644\\u0623\\u064a\\u0636\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Pediatric GI conditions: GERD, esophageal strictures, dysphagia, gastritis, peptic ulcer, gastroenteritis, food allergy, intolerance, celiac disease, chronic diarrhea, malabsorption, pediatric IBD (Crohn\\u2019s, UC).\",\"ar\":\"\\t\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a \\u0644\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644: \\u0627\\u0644\\u0627\\u0631\\u062a\\u062c\\u0627\\u0639 \\u0627\\u0644\\u0645\\u0639\\u062f\\u064a \\u0627\\u0644\\u0645\\u0631\\u064a\\u0626\\u064a\\u060c \\u062a\\u0636\\u064a\\u0642 \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621\\u060c \\u0639\\u0633\\u0631 \\u0627\\u0644\\u0628\\u0644\\u0639\\u060c \\u0627\\u0644\\u062a\\u0647\\u0627\\u0628 \\u0627\\u0644\\u0645\\u0639\\u062f\\u0629\\u060c \\u0627\\u0644\\u0642\\u0631\\u062d\\u0629 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a\\u0629\\u060c \\u0627\\u0644\\u0646\\u0632\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u0648\\u064a\\u0629\\u060c \\u062d\\u0633\\u0627\\u0633\\u064a\\u0629 \\u0627\\u0644\\u0637\\u0639\\u0627\\u0645\\u060c \\u0639\\u062f\\u0645 \\u0627\\u0644\\u062a\\u062d\\u0645\\u0644 \\u0627\\u0644\\u063a\\u0630\\u0627\\u0626\\u064a\\u060c \\u0627\\u0644\\u0633\\u064a\\u0644\\u064a\\u0627\\u0643\\u060c \\u0627\\u0644\\u0625\\u0633\\u0647\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0632\\u0645\\u0646\\u060c \\u0633\\u0648\\u0621 \\u0627\\u0644\\u0627\\u0645\\u062a\\u0635\\u0627\\u0635\\u060c \\u0648\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 \\u0627\\u0644\\u0627\\u0644\\u062a\\u0647\\u0627\\u0628\\u064a\\u0629 \\u0644\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644.\"}},{\"text\":{\"en\":\"Nutritional support: TPN and enteral feeding for neonates and children.\",\"ar\":\"\\t\\u0627\\u0644\\u062f\\u0639\\u0645 \\u0627\\u0644\\u063a\\u0630\\u0627\\u0626\\u064a: \\u0627\\u0644\\u062a\\u063a\\u0630\\u064a\\u0629 \\u0627\\u0644\\u0648\\u0631\\u064a\\u062f\\u064a\\u0629 \\u0627\\u0644\\u0643\\u0627\\u0645\\u0644\\u0629 (TPN) \\u0648\\u0627\\u0644\\u062a\\u063a\\u0630\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0648\\u064a\\u0629 \\u0644\\u0644\\u0631\\u0636\\u0639 \\u0648\\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644.\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":31,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":34,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":\"\\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u0649\"},\"doctors\":[]}]', '[{\"text\":{\"en\":\".\",\"ar\":\"88 ar\"}},{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '[{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '2025-12-26 06:33:44', '2026-02-12 17:35:37'),
(17, '{\"en\":\"Pediatric Surgical Unit\",\"ar\":\"وحدة جراحة الجهاز الهضمي للاطفال\"}', 9, '{\"en\":\"<p>The Pediatric Surgical Unit specializes in the surgical treatment of complex congenital and acquired gastrointestinal conditions in children. The unit offers advanced reconstructive and corrective procedures, supported by pediatric anesthesia and intensive care services, ensuring safe, age-appropriate surgical care and comprehensive postoperative follow-up.</p>\",\"ar\":\"<p>تتخصص وحدة الجراحة للأطفال في العلاج الجراحي للحالات الخِلقية والمكتسبة المعقدة للجهاز الهضمي لدى الأطفال. وتُقدم الوحدة أحدث الإجراءات الجراحية التصحيحية والترميمية، بدعم من تخدير الأطفال والعناية المركزة، لضمان رعاية جراحية آمنة ومناسبة لكل مرحلة عمرية مع متابعة شاملة بعد الجراحة.</p>\"}', '{\"en\":\"<p>The Pediatric Surgical Unit provides operative care for congenital anomalies and acquired gastrointestinal conditions in young patients. Its scope includes reconstructive and corrective interventions, tumor removal, and management of complex abdominal abnormalities, delivered alongside specialized pediatric anesthesia, neonatal and pediatric intensive care, and structured recovery programs.</p>\",\"ar\":\"<p>توفر الوحدة الرعاية الجراحية للتشوهات الخِلقية وأمراض الجهاز الهضمي المكتسبة لدى الأطفال، وتشمل العمليات التصحيحية والترميمية، واستئصال الأورام، وعلاج تشوهات البطن المعقدة، مع دعم متكامل من العناية المركزة لحديثي الولادة والأطفال.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627\"},\"content\":{\"en\":\"<p>Advanced pediatric surgical care for complex gastrointestinal and abdominal conditions, combining precision techniques with comprehensive perioperative support.<\\/p>\",\"ar\":\"<p>\\u0631\\u0639\\u0627\\u064a\\u0629 \\u062c\\u0631\\u0627\\u062d\\u064a\\u0629 \\u0645\\u062a\\u0642\\u062f\\u0645\\u0629 \\u0644\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644 \\u0644\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u0642\\u062f\\u0629 \\u0644\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a \\u0648\\u0627\\u0644\\u0628\\u0637\\u0646\\u060c \\u062a\\u062c\\u0645\\u0639 \\u0628\\u064a\\u0646 \\u0627\\u0644\\u062f\\u0642\\u0629 \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0645\\u062a\\u0643\\u0627\\u0645\\u0644 \\u0642\\u0628\\u0644 \\u0648\\u0628\\u0639\\u062f \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u0629.<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Pediatric surgery encompasses a wide range of specialized procedures. Congenital and neonatal surgery includes correction of gut malrotation and volvulus, repair of tracheoesophageal fistula (TEF) and esophageal atresia, congenital diaphragmatic hernia repair, Kasai portoenterostomy for biliary atresia, management of neonatal intestinal atresias (duodenal, jejunoileal, and colonic), closure of gastroschisis and omphalocele, and pyloromyotomy for neonatal pyloric stenosis. \",\"ar\":\"\\u2022\\t\\u062a\\u0634\\u0645\\u0644 \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u062e\\u0650\\u0644\\u0642\\u064a\\u0629 \\u0648\\u062d\\u062f\\u064a\\u062b\\u064a \\u0627\\u0644\\u0648\\u0644\\u0627\\u062f\\u0629: \\u062a\\u0635\\u062d\\u064a\\u062d \\u062f\\u0648\\u0631\\u0627\\u0646 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0627\\u0644\\u062a\\u0648\\u0627\\u0621\\u060c \\u0625\\u0635\\u0644\\u0627\\u062d \\u0627\\u0644\\u0646\\u0627\\u0633\\u0648\\u0631 \\u0627\\u0644\\u0631\\u063a\\u0627\\u0645\\u064a \\u0627\\u0644\\u0645\\u0631\\u064a\\u0626\\u064a \\u0648\\u0631\\u062a\\u0642 \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621\\u060c \\u0625\\u0635\\u0644\\u0627\\u062d \\u0641\\u062a\\u0642 \\u0627\\u0644\\u062d\\u062c\\u0627\\u0628 \\u0627\\u0644\\u062d\\u0627\\u062c\\u0632 \\u0627\\u0644\\u062e\\u0650\\u0644\\u0642\\u064a\\u060c \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0643\\u0627\\u0633\\u0627\\u064a \\u0644\\u0631\\u062a\\u0642 \\u0627\\u0644\\u0642\\u0646\\u0648\\u0627\\u062a \\u0627\\u0644\\u0645\\u0631\\u0627\\u0631\\u064a\\u0629\\u060c \\u0639\\u0644\\u0627\\u062c \\u0631\\u062a\\u0642 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 \\u0627\\u0644\\u0648\\u0644\\u064a\\u062f\\u064a\\u060c \\u063a\\u0644\\u0642 \\u0639\\u064a\\u0648\\u0628 \\u062c\\u062f\\u0627\\u0631 \\u0627\\u0644\\u0628\\u0637\\u0646 (\\u0627\\u0646\\u0634\\u0642\\u0627\\u0642 \\u0627\\u0644\\u0628\\u0637\\u0646 \\u0648\\u0627\\u0644\\u0642\\u064a\\u0644\\u0629 \\u0627\\u0644\\u0633\\u064f\\u0631\\u064a\\u0629)\\u060c \\u0648\\u0634\\u0642 \\u0639\\u0636\\u0644\\u0629 \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628.\"}},{\"text\":{\"en\":\"In the field of anorectal and colorectal surgery, procedures such as posterior sagittal anorectoplasty (PSARP), anoplasty for low anorectal malformations, rectal biopsies and pull-through procedures for Hirschsprung\\u2019s disease, colorectal resections with re-anastomosis, and the management of cloacal malformations are performed. Esophageal and upper gastrointestinal surgery involves esophagectomy with replacement techniques (gastric pull-up, colon interposition), fundoplication for severe reflux, Heller myotomy for achalasia, and hiatal hernia repair.\",\"ar\":\"\\u2022\\t\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0634\\u0631\\u062c \\u0648\\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 \\u0648\\u0627\\u0644\\u0645\\u0633\\u062a\\u0642\\u064a\\u0645: \\u0639\\u0645\\u0644\\u064a\\u0629 PSARP\\u060c \\u0625\\u0635\\u0644\\u0627\\u062d \\u0627\\u0644\\u062a\\u0634\\u0648\\u0647\\u0627\\u062a \\u0627\\u0644\\u0634\\u0631\\u062c\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0646\\u062e\\u0641\\u0636\\u0629\\u060c \\u062e\\u0632\\u0639\\u0627\\u062a \\u0648\\u0633\\u062d\\u0628 \\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 \\u0644\\u0645\\u0631\\u0636 \\u0647\\u064a\\u0631\\u0634\\u0633\\u0628\\u0631\\u0648\\u0646\\u063a\\u060c \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 \\u0645\\u0639 \\u0625\\u0639\\u0627\\u062f\\u0629 \\u0627\\u0644\\u062a\\u0648\\u0635\\u064a\\u0644\\u060c \\u0648\\u0639\\u0644\\u0627\\u062c \\u062a\\u0634\\u0648\\u0647\\u0627\\u062a \\u0627\\u0644\\u0645\\u0630\\u0631\\u0642.\"}},{\"text\":{\"en\":\"Gastric, intestinal, and advanced colorectal surgery covers partial or total colectomy, small bowel resections with anastomoses, bowel lengthening procedures (such as STEP and LILT) for short bowel syndrome, intestinal stoma creation and closure, and management of complex adhesive intestinal obstruction. \",\"ar\":\" \\u2022\\t\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u062f\\u0629 \\u0648\\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 \\u0648\\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u0629: \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 \\u0627\\u0644\\u062c\\u0632\\u0626\\u064a \\u0623\\u0648 \\u0627\\u0644\\u0643\\u0644\\u064a\\u060c \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642\\u0629\\u060c \\u0625\\u0637\\u0627\\u0644\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0639\\u0627\\u0621 (STEP \\u0648LILT)\\u060c \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0648\\u063a\\u0644\\u0642 \\u0627\\u0644\\u0641\\u062a\\u062d\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u0648\\u064a\\u0629\\u060c \\u0648\\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u0627\\u0646\\u0633\\u062f\\u0627\\u062f \\u0627\\u0644\\u0645\\u0639\\u0648\\u064a \\u0627\\u0644\\u0645\\u0639\\u0642\\u062f.\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621 \\u0648\\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a \\u0627\\u0644\\u0639\\u0644\\u0648\\u064a: \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621 \\u0645\\u0639 \\u0627\\u0644\\u062a\\u0639\\u0648\\u064a\\u0636\\u060c \\u062a\\u062b\\u0646\\u064a\\u0629 \\u0627\\u0644\\u0642\\u0627\\u0639 \\u0644\\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u0627\\u0631\\u062a\\u062c\\u0627\\u0639 \\u0627\\u0644\\u0634\\u062f\\u064a\\u062f\\u060c \\u0634\\u0642 \\u0639\\u0636\\u0644\\u0629 \\u0647\\u064a\\u0644\\u0631\\u060c \\u0648\\u0625\\u0635\\u0644\\u0627\\u062d \\u0641\\u062a\\u0642 \\u0627\\u0644\\u062d\\u062c\\u0627\\u0628 \\u0627\\u0644\\u062d\\u0627\\u062c\\u0632.\"}},{\"text\":{\"en\":\"In the area of hepatobiliary and pancreatic surgery, key interventions include the pediatric Whipple\\u2019s procedure, liver resections for tumors or congenital lesions, pancreatic tumor resections, biliary and pancreatic duct reconstruction, and choledochal cyst excision. \",\"ar\":\"\\t\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0627\\u0644\\u0643\\u0628\\u062f \\u0648\\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633: \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0648\\u064a\\u0628\\u0644 \\u0644\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644\\u060c \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0623\\u0648\\u0631\\u0627\\u0645 \\u0627\\u0644\\u0643\\u0628\\u062f\\u060c \\u0623\\u0648\\u0631\\u0627\\u0645 \\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633\\u060c \\u0625\\u0639\\u0627\\u062f\\u0629 \\u0628\\u0646\\u0627\\u0621 \\u0627\\u0644\\u0642\\u0646\\u0648\\u0627\\u062a \\u0627\\u0644\\u0635\\u0641\\u0631\\u0627\\u0648\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633\\u064a\\u0629\\u060c \\u0648\\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0643\\u064a\\u0627\\u0633 \\u0627\\u0644\\u0635\\u0641\\u0631\\u0627\\u0648\\u064a\\u0629 \\u0627\\u0644\\u062e\\u0650\\u0644\\u0642\\u064a\\u0629.\"}},{\"text\":{\"en\":\"Pediatric oncologic and solid organ surgery addresses the resection of abdominal wall tumors, Wilms\\u2019 tumor, and neuroblastoma, along with splenectomy for trauma or hematological disease, adrenalectomy for tumors or congenital hyperplasia, and surgery for renal tumors. \",\"ar\":\"\\t\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0623\\u0648\\u0631\\u0627\\u0645 \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644 \\u0648\\u0627\\u0644\\u0623\\u0639\\u0636\\u0627\\u0621 \\u0627\\u0644\\u0635\\u0644\\u0628\\u0629: \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0623\\u0648\\u0631\\u0627\\u0645 \\u062c\\u062f\\u0627\\u0631 \\u0627\\u0644\\u0628\\u0637\\u0646\\u060c \\u0648\\u0631\\u0645 \\u0648\\u064a\\u0644\\u0645\\u0632\\u060c \\u0627\\u0644\\u0648\\u0631\\u0645 \\u0627\\u0644\\u0623\\u0631\\u0648\\u0645\\u064a \\u0627\\u0644\\u0639\\u0635\\u0628\\u064a\\u060c \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0637\\u062d\\u0627\\u0644\\u060c \\u0627\\u0644\\u063a\\u062f\\u0629 \\u0627\\u0644\\u0643\\u0638\\u0631\\u064a\\u0629\\u060c \\u0648\\u062c\\u0631\\u0627\\u062d\\u0627\\u062a \\u0623\\u0648\\u0631\\u0627\\u0645 \\u0627\\u0644\\u0643\\u0644\\u0649.\"}},{\"text\":{\"en\":\"Finally, general pediatric surgery involves procedures such as inguinal and umbilical hernia repair, hydrocele correction, orchidopexy for undescended testes, appendectomy, and abdominal wall reconstruction.\",\"ar\":\"\\t\\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629 \\u0644\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644: \\u0625\\u0635\\u0644\\u0627\\u062d \\u0627\\u0644\\u0641\\u062a\\u0648\\u0642 \\u0627\\u0644\\u0625\\u0631\\u0628\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0633\\u064f\\u0631\\u064a\\u0629\\u060c \\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u0642\\u064a\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0627\\u0626\\u064a\\u0629\\u060c \\u062a\\u062b\\u0628\\u064a\\u062a \\u0627\\u0644\\u062e\\u0635\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0642\\u0629\\u060c \\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0632\\u0627\\u0626\\u062f\\u0629 \\u0627\\u0644\\u062f\\u0648\\u062f\\u064a\\u0629\\u060c \\u0648\\u0625\\u0639\\u0627\\u062f\\u0629 \\u0628\\u0646\\u0627\\u0621 \\u062c\\u062f\\u0627\\u0631 \\u0627\\u0644\\u0628\\u0637\\u0646.\"}},{\"text\":{\"en\":\"Providing comprehensive, specialized, and free-of-charge care for children with complex congenital and acquired surgical conditions.\",\"ar\":\"\\t\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0631\\u0639\\u0627\\u064a\\u0629 \\u0645\\u062a\\u062e\\u0635\\u0635\\u0629 \\u0648\\u0634\\u0627\\u0645\\u0644\\u0629 \\u0648\\u0645\\u062c\\u0627\\u0646\\u064a\\u0629 \\u0644\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0635\\u0627\\u0628\\u064a\\u0646 \\u0628\\u0623\\u0645\\u0631\\u0627\\u0636 \\u062c\\u0631\\u0627\\u062d\\u064a\\u0629 \\u0645\\u0639\\u0642\\u062f\\u0629.\"}},{\"text\":{\"en\":\"Reducing neonatal and infant mortality from congenital anomalies through early intervention, advanced perioperative support, and family-centered care.\",\"ar\":\"\\t\\u062e\\u0641\\u0636 \\u0645\\u0639\\u062f\\u0644\\u0627\\u062a \\u0648\\u0641\\u064a\\u0627\\u062a \\u062d\\u062f\\u064a\\u062b\\u064a \\u0627\\u0644\\u0648\\u0644\\u0627\\u062f\\u0629 \\u0646\\u062a\\u064a\\u062c\\u0629 \\u0627\\u0644\\u062a\\u0634\\u0648\\u0647\\u0627\\u062a \\u0627\\u0644\\u062e\\u0650\\u0644\\u0642\\u064a\\u0629 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u062a\\u062f\\u062e\\u0644 \\u0627\\u0644\\u0645\\u0628\\u0643\\u0631 \\u0648\\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u0629.\"}},{\"text\":{\"en\":\"Establishing Egypt\\u2019s leading surgical-NICU model, integrating high-level neonatal intensive care with advanced surgical expertise.\",\"ar\":\"\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0646\\u0645\\u0648\\u0630\\u062c \\u0631\\u0627\\u0626\\u062f \\u0641\\u064a \\u0645\\u0635\\u0631 \\u0644\\u0644\\u062c\\u0631\\u0627\\u062d\\u0629 \\u0627\\u0644\\u0645\\u062a\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u0639\\u0646\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0643\\u0632\\u0629 \\u0644\\u062d\\u062f\\u064a\\u062b\\u064a \\u0627\\u0644\\u0648\\u0644\\u0627\\u062f\\u0629\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":31,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":32,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":\"\\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\"},\"doctors\":[]}]', '[{\"text\":{\"en\":\".\",\"ar\":\"88 ar\"}},{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '[{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '2025-12-26 06:33:44', '2026-02-12 17:56:12'),
(18, '{\"en\":\"Endoscopy Unit\",\"ar\":\"وحدة المناظير\"}', 9, '{\"en\":\"<p>The Endoscopy Unit provides state-of-the-art diagnostic and therapeutic endoscopic services for both adults and children. The unit performs advanced procedures including screening, minimally invasive interventions, and precision-guided treatments, supporting early detection, accurate diagnosis, and effective management of a wide range of gastrointestinal conditions.</p>\",\"ar\":\"<p>توفر وحدة المناظير خدمات تشخيصية وعلاجية متطورة للبالغين والأطفال، باستخدام أحدث تقنيات المناظير الطبية. وتشمل الوحدة الفحوصات الوقائية، والتدخلات محدودة التدخل، والعلاجات الدقيقة الموجهة، بما يضمن الاكتشاف المبكر، والتشخيص الدقيق، والعلاج الفعّال لمجموعة واسعة من أمراض الجهاز الهضمي.</p>\"}', '{\"en\":\"<p>This unit offers a full spectrum of minimally invasive visual and interventional procedures for the examination and treatment of the digestive tract. Services include preventive screening, targeted therapeutic techniques, management of gastrointestinal bleeding, tissue removal and sampling, and precision-guided interventions that support timely and informed clinical decision-making.</p>\",\"ar\":\"<p>تُقدم الوحدة مجموعة متكاملة من الإجراءات التشخيصية والعلاجية بالمناظير لفحص وعلاج الجهاز الهضمي، وتشمل الفحوصات الوقائية، وإيقاف النزيف الهضمي، وأخذ العينات، واستئصال الأنسجة، والتدخلات الدقيقة الموجهة لدعم اتخاذ القرار الطبي السليم في الوقت المناسب.</p>\"}', '[{\"title\":{\"en\":\"What we treat\",\"ar\":\"\\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u0649 \\u064a\\u062a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0647\\u0627\"},\"content\":{\"en\":\"<p>State-of-the-art diagnostic and therapeutic endoscopic services for early detection, precise intervention, and comprehensive gastrointestinal care.<\\/p>\",\"ar\":\"<p>\\u062e\\u062f\\u0645\\u0627\\u062a \\u0645\\u0646\\u0627\\u0638\\u064a\\u0631 \\u062a\\u0634\\u062e\\u064a\\u0635\\u064a\\u0629 \\u0648\\u0639\\u0644\\u0627\\u062c\\u064a\\u0629 \\u0645\\u062a\\u0642\\u062f\\u0645\\u0629 \\u0644\\u0644\\u0627\\u0643\\u062a\\u0634\\u0627\\u0641 \\u0627\\u0644\\u0645\\u0628\\u0643\\u0631\\u060c \\u0648\\u0627\\u0644\\u062a\\u062f\\u062e\\u0644 \\u0627\\u0644\\u062f\\u0642\\u064a\\u0642\\u060c \\u0648\\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0634\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a.<\\/p>\"},\"bullets\":[{\"text\":{\"en\":\"Upper and lower GI endoscopy\",\"ar\":\"\\t\\u0645\\u0646\\u0627\\u0638\\u064a\\u0631 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a \\u0627\\u0644\\u0639\\u0644\\u0648\\u064a \\u0648\\u0627\\u0644\\u0633\\u0641\\u0644\\u064a\"}},{\"text\":{\"en\":\"ERCP (Endoscopic Retrograde Cholangiopancreatography)\",\"ar\":\"\\t\\u0645\\u0646\\u0638\\u0627\\u0631 \\u0627\\u0644\\u0642\\u0646\\u0648\\u0627\\u062a \\u0627\\u0644\\u0635\\u0641\\u0631\\u0627\\u0648\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0628\\u0646\\u0643\\u0631\\u064a\\u0627\\u0633 (ERCP)\"}},{\"text\":{\"en\":\"EUS (Endoscopic Ultrasound)\",\"ar\":\"\\t\\u0627\\u0644\\u0645\\u0648\\u062c\\u0627\\u062a \\u0641\\u0648\\u0642 \\u0627\\u0644\\u0635\\u0648\\u062a\\u064a\\u0629 \\u0628\\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631 (EUS)\"}},{\"text\":{\"en\":\"Endoscopic biopsy and polypectomy\",\"ar\":\"\\t\\u0623\\u062e\\u0630 \\u0627\\u0644\\u062e\\u0632\\u0639\\u0627\\u062a \\u0648\\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u0632\\u0648\\u0627\\u0626\\u062f \\u0627\\u0644\\u0644\\u062d\\u0645\\u064a\\u0629\"}},{\"text\":{\"en\":\"Variceal band ligation, sclerotherapy, APC\",\"ar\":\"\\t\\u0631\\u0628\\u0637 \\u062f\\u0648\\u0627\\u0644\\u064a \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621\\u060c \\u0627\\u0644\\u062d\\u0642\\u0646\\u060c \\u0648\\u0627\\u0644\\u0640 APC\"}},{\"text\":{\"en\":\"Esophageal\\/colonic dilation (balloon, Savary)\",\"ar\":\"\\t\\u062a\\u0648\\u0633\\u064a\\u0639 \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621 \\u0648\\u0627\\u0644\\u0642\\u0648\\u0644\\u0648\\u0646 (\\u0628\\u0627\\u0644\\u0628\\u0627\\u0644\\u0648\\u0646 \\u0623\\u0648 \\u0627\\u0644\\u0633\\u0627\\u0641\\u0627\\u0631\\u064a)\"}},{\"text\":{\"en\":\"PEG (Percutaneous Endoscopic Gastrostomy)\",\"ar\":\"\\t\\u0627\\u0644\\u062a\\u063a\\u0630\\u064a\\u0629 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631 (PEG)\"}},{\"text\":{\"en\":\"Hemostasis: clips, loops, Endoclot\",\"ar\":\"\\t\\u0625\\u064a\\u0642\\u0627\\u0641 \\u0627\\u0644\\u0646\\u0632\\u064a\\u0641: \\u0627\\u0644\\u0645\\u0634\\u0627\\u0628\\u0643\\u060c \\u0627\\u0644\\u062d\\u0644\\u0642\\u0627\\u062a\\u060c Endoclot\"}},{\"text\":{\"en\":\"Stent placement and retrieval\",\"ar\":\"\\t\\u062a\\u0631\\u0643\\u064a\\u0628 \\u0648\\u0625\\u0632\\u0627\\u0644\\u0629 \\u0627\\u0644\\u062f\\u0639\\u0627\\u0645\\u0627\\u062a\"}},{\"text\":{\"en\":\"ERCP with sphincterotomy, stenting, stone extraction\",\"ar\":\"\\tERCP \\u0645\\u0639 \\u0634\\u0642 \\u0627\\u0644\\u0645\\u0635\\u0631\\u0629\\u060c \\u0648\\u062a\\u0631\\u0643\\u064a\\u0628 \\u0627\\u0644\\u062f\\u0639\\u0627\\u0645\\u0627\\u062a\\u060c \\u0648\\u0627\\u0633\\u062a\\u062e\\u0631\\u0627\\u062c \\u0627\\u0644\\u062d\\u0635\\u0648\\u0627\\u062a\"}},{\"text\":{\"en\":\"EUS-guided FNA and FNB\",\"ar\":\"\\t\\u0623\\u062e\\u0630 \\u0639\\u064a\\u0646\\u0627\\u062a \\u062f\\u0642\\u064a\\u0642\\u0629 \\u0645\\u0648\\u062c\\u0647\\u0629 \\u0628\\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631 (FNA\\/FNB)\"}},{\"text\":{\"en\":\"POEM (Peroral Endoscopic Myotomy)\",\"ar\":\"\\t\\u0634\\u0642 \\u0639\\u0636\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0631\\u064a\\u0621 \\u0628\\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631 (POEM)\"}},{\"text\":{\"en\":\"G-POEM (Gastric POEM)\",\"ar\":\"\\t\\u0634\\u0642 \\u0639\\u0636\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0639\\u062f\\u0629 \\u0628\\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631 (G-POEM)\"}},{\"text\":{\"en\":\"Z-POEM (Zenker\\u2019s POEM)\",\"ar\":\"\\t\\u0639\\u0644\\u0627\\u062c \\u0631\\u062a\\u062c \\u0632\\u0646\\u0643\\u0631 \\u0628\\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631 (Z-POEM)\"}},{\"text\":{\"en\":\"EMR (Endoscopic Mucosal Resection)\",\"ar\":\"\\t\\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0627\\u0644\\u063a\\u0634\\u0627\\u0621 \\u0627\\u0644\\u0645\\u062e\\u0627\\u0637\\u064a \\u0628\\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631 (EMR)\"}},{\"text\":{\"en\":\"ESD (Endoscopic Submucosal Dissection)\",\"ar\":\"\\t\\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u062a\\u062d\\u062a \\u0627\\u0644\\u0645\\u062e\\u0627\\u0637\\u064a\\u0629 \\u0628\\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631 (ESD)\"}},{\"text\":{\"en\":\"EFTR (Endoscopic Full-Thickness Resection)\",\"ar\":\"\\t\\u0627\\u0644\\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0643\\u0627\\u0645\\u0644 \\u0627\\u0644\\u0633\\u0645\\u0643 \\u0628\\u0627\\u0644\\u0645\\u0646\\u0638\\u0627\\u0631 (EFTR)\"}},{\"text\":{\"en\":\"STER (Submucosal Tunneling Endoscopic Resection)\",\"ar\":\"\\t\\u0627\\u0644\\u0627\\u0633\\u062a\\u0626\\u0635\\u0627\\u0644 \\u0628\\u0627\\u0644\\u0623\\u0646\\u0641\\u0627\\u0642 \\u062a\\u062d\\u062a \\u0627\\u0644\\u0645\\u062e\\u0627\\u0637\\u064a\\u0629 (STER)\"}}]}]', '[{\"title\":{\"en\":\"Head of Department\",\"ar\":\"\\u0631\\u0626\\u064a\\u0633 \\u0627\\u0644\\u0642\\u0633\\u0645\"},\"doctors\":[{\"doctor\":31,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649 \"}},{\"doctor\":35,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]},{\"title\":{\"en\":\"Team\",\"ar\":\"\\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\"},\"doctors\":[{\"doctor\":66,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":62,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":63,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":65,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}},{\"doctor\":67,\"doctor_title\":{\"en\":\"Consultant\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0649\"}}]}]', '[{\"text\":{\"en\":\".\",\"ar\":\"88 ar\"}},{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '[{\"text\":{\"en\":\".\",\"ar\":null}},{\"text\":{\"en\":\".\",\"ar\":null}}]', '2025-12-26 06:33:44', '2026-02-12 18:20:24');
