(12, 'case', '{\"en\":\"Eileen Mohamed Sayed\",\"ar\":\"إيلين محمد سيد\"}', '{\"en\":\"Repair of Aortic Coarctation and Ligation of Patent Ductus Arteriosus (PDA)\",\"ar\":\"إصلاح ضيق في الشريان الأورطي وربط وصلة شريانية\"}', NULL, '{\"en\":\"Brief Brief\"}', '{\"en\":\"<p><strong>Age:</strong> 26 days<br>The family consists of seven members (father, mother, and children of different ages).<br>The father works for a transportation and relocation company in Sudan.<br>The family lives in a modest family home.<br>Accordingly, the family’s financial situation does not allow them to afford this operation.</p>\",\"ar\":\"<p><strong>العمر: 26 يوم</strong><br>الأسرة مكونة من 7 أفراد (أب – أم – أبناء في مختلف الأعمار).<br>الوالد يعمل في شركة نقل وترحيل بالسودان.<br>تقيم الأسرة في منزل عائلي متواضع.<br>وبناءً على ذلك، فإن الوضع المادي للأسرة لا يسمح بإجراء هذه العملية.</p><p></p>\"}', 520000, 0, NULL, 1, '2025-12-26 23:52:51', '2026-02-12 01:08:47', NULL),
(13, 'case', '{\"en\":\"Fayrouz Mostafa Ibrahim\",\"ar\":\"فيروز مصطفى إبراهيم\"}', '{\"en\":\"Repair of Complete Atrioventricular Canal (CAVC) and Repair of Cor Triatriatum with Inspection of Left Pulmonary Veins and Re-implantation of Left SVC into the Right Atrium\",\"ar\":\"إصلاح قناة أذينية بطينية وإصلاح مجرى الأوردة الرئوية\"}', NULL, '{\"en\":\"Brief Brief\"}', '{\"en\":\"<p><strong>Age:</strong> 9 months<br>The family consists of three members (father, mother, and one young child).<br>The father works as a factory laborer.<br>The family lives in a modest family home.<br>Therefore, the family’s financial situation does not allow them to afford this operation.</p>\",\"ar\":\"<p><strong>العمر: 9 شهور</strong><br>الأسرة مكونة من 3 أفراد (أب – أم – طفل صغير).<br>الوالد يعمل عامل في مصنع.<br>تقيم الأسرة في منزل عائلي متواضع.<br>لذلك فإن الوضع المادي للأسرة لا يسمح بإجراء هذه العملية.</p>\"}', 975000, 177000, NULL, 1, '2025-12-26 23:52:51', '2026-02-12 01:14:16', NULL);
