INSERT INTO `donation_pages` (`id`, `form_title`, `cases_title`, `cases_content`, `equipment_title`, `equipment_content`, `supplies_title`, `supplies_content`, `banks_title`, `other_title`, `collection_title`, `collection_subtitle`, `help_title`, `help_subtitle`, `help_form_title`, `help_form_subtitle`, `single_related_toptitle`, `single_related_title`, `single_related_subtitle`, `outside_title`, `outside_swift`, `created_at`, `updated_at`) VALUES
(1, '{\"en\":\"Give Hope Today\",\"ar\":null}', '{\"en\":\"Donate for a case\",\"ar\":null}', '{\"en\":\"<p>Some patients urgently need financial support to continue their treatment journey. Donating for a specific case allows you to make a direct and meaningful impact on someone’s life. By choosing a case from the list below, your donation goes straight toward giving a patient hope, healing, and a second chance.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"Donate for a equipment \",\"ar\":null}', '{\"en\":\"<p>Some patients urgently need financial support to continue their treatment journey. Donating for a specific case allows you to make a direct and meaningful impact on someone’s life. By choosing a case from the list below, your donation goes straight toward giving a patient hope, healing, and a second chance.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"Donate for a supply\",\"ar\":null}', '{\"en\":\"<p>Some patients urgently need financial support to continue their treatment journey. Donating for a specific case allows you to make a direct and meaningful impact on someone’s life. By choosing a case from the list below, your donation goes straight toward giving a patient hope, healing, and a second chance.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"Donate by bank transfer\",\"ar\":null}', '{\"en\":\"Other Donation Ways\",\"ar\":null}', '{\"en\":\"Home Donation Collection\",\"ar\":null}', '{\"en\":\"Can\'t visit us? Our representative can come to your home to collect your donation safely and conveniently\",\"ar\":null}', '{\"en\":\"Need Help with Your Donation?\",\"ar\":null}', '{\"en\":\"Call our hotline for any questions or assistance regarding the donation process - our team is here to help and guide you anytime.\",\"ar\":null}', '{\"en\":\"Need help with your donation?\",\"ar\":null}', '{\"en\":\"If you face any issue or have a question about your donation, please fill out the form below - our team will get back to you as soon as possible.\",\"ar\":null}', '{\"ar\": null, \"en\": \"Single related toptitle\"}', '{\"en\":\"With Your Giving .. We Restore Hope\",\"ar\":\"بتبرعك .. نحيي الأمل\"}', '{\"en\":\"Save a Soul .. Be the Miracle\",\"ar\":\"أنقذ روحًا .. وكن سببًا في معجزة\"}', '{\"en\":\"Outside title\",\"ar\":null}', '{\"en\":\"Outside swift\",\"ar\":null}', NULL, '2026-02-12 01:22:07');
