INSERT INTO `education_pages` (`id`, `intro_title`, `intro_pic`, `intro_content`, `sidebar_box_icon`, `sidebar_box_title`, `sidebar_box_subtitle`, `sidebar_box_btn_link`, `sidebar_box_btn_title`, `created_at`, `updated_at`) VALUES
(1, '{\"ar\":\"التعليم و التدريب\",\"en\":\"Education & Training\"}', NULL, '{\"en\":\"<p><strong>Education &amp; Training </strong>at Al-Nas Hospital is a cornerstone of clinical excellence and institutional growth. We serve as the hospital’s center of excellence for professional development, delivering structured, high-impact educational programs that strengthen clinical competency, leadership capability, and patient safety standards across all departments. Through accredited learning pathways, hands-on clinical training, digital education platforms, research engagement, and leadership development initiatives, we cultivate a workforce prepared to meet the evolving demands of modern healthcare. Our commitment goes beyond training — we build expertise, inspire innovation, and sustain a culture of excellence.</p><h2>Vision</h2><p>To be recognized as a leading hospital-based Center of Excellence in healthcare education — driving clinical mastery, innovation, and sustainable professional growth at national and international levels.</p><h2>Mission</h2><ul><li><p>To deliver structured, competency-driven education programs aligned with accreditation and quality standards.</p></li><li><p>To promote lifelong learning and continuous professional development across all disciplines.</p></li><li><p>To integrate innovation, digital learning, and research into everyday clinical practice.</p></li><li><p>To strengthen leadership capacity and interdisciplinary collaboration.</p></li><li><p>To ensure education directly contributes to patient safety, quality improvement, and organizational excellence.</p></li></ul><h2>Our Commitment</h2><p>We believe that exceptional patient care begins with exceptional education. By investing in knowledge, skills, and professional growth, we ensure that every member of our team is empowered to deliver safe, compassionate, and evidence-based care.</p>\",\"ar\":\"<p>يُعد قطاع <strong>التعليم والتدريب</strong> في مستشفى الناس ركيزة أساسية للتميّز الإكلينيكي والنمو المؤسسي. نحن نعمل كمركز تميز للتطوير المهني على مستوى المستشفى، من خلال تقديم برامج تعليمية منظمة وعالية التأثير تُعزّز الكفاءة الإكلينيكية، والقدرات القيادية، ومعايير سلامة المرضى في جميع الأقسام. ومن خلال مسارات تعليمية معتمدة، وتدريب إكلينيكي عملي، ومنصات تعليم رقمية، وأنشطة بحثية، ومبادرات تطوير قيادي، نعمل على إعداد كوادر مؤهلة قادرة على مواكبة المتطلبات المتجددة للرعاية الصحية الحديثة. التزامنا يتجاوز حدود التدريب — فنحن نبني الخبرات، ونحفّز الابتكار، ونرسّخ ثقافة التميز المستدام.</p><h1>الرؤية</h1><p>أن نكون مركز تميز رائد على مستوى المستشفيات في مجال التعليم الصحي، يقود التميز الإكلينيكي والابتكار والنمو المهني المستدام على المستويين الوطني والدولي.</p><h1>الرسالة</h1><ul><li><p>تقديم برامج تعليمية منظمة قائمة على الكفاءة، ومتوافقة مع معايير الاعتماد والجودة.</p></li><li><p>تعزيز التعلم المستمر والتطوير المهني الدائم لكافة التخصصات.</p></li><li><p>دمج الابتكار والتعليم الرقمي والبحث العلمي في الممارسة الإكلينيكية اليومية.</p></li><li><p>تعزيز القدرات القيادية والتعاون متعدد التخصصات.</p></li><li><p>ضمان إسهام التعليم بشكل مباشر في سلامة المرضى، وتحسين الجودة، والتميز المؤسسي.</p></li></ul><h1>التزامنا</h1><p>نؤمن بأن الرعاية الصحية الاستثنائية تبدأ بتعليم استثنائي. ومن خلال الاستثمار في المعرفة والمهارات والنمو المهني، نُمكّن كل فرد في فريقنا من تقديم رعاية آمنة، إنسانية، وقائمة على الأدلة العلمية.</p>\"}', NULL, '{\"en\":\"Join Our Education & Training Community\",\"ar\":\"انضم إلى مجتمع التعليم والتدريب بمستشفى الناس\"}', '{\"en\":\"Join our Education & Training programs and take the next step in your professional journey toward clinical excellence and leadership.\",\"ar\":\"انضم إلى برامج التعليم والتدريب بمستشفى الناس، وارتقِ بمسيرتك المهنية نحو التميز الإكلينيكي وبناء القدرات القيادية.\"}', 'https://alnas.dawayer.work/education-and-training/participation-form', '{\"en\":\"Begin your journey today!\",\"ar\":\"ابدأ رحلتك الآن!\"}', '2025-12-26 19:58:34', '2026-02-13 11:35:43');
