INSERT INTO `faq_pages` (`id`, `toptitle`, `title`, `content`, `created_at`, `updated_at`) VALUES
(1, '{\"en\":\"How Can We Help You?\",\"ar\":\"كيف يمكننا مساعدتك؟\"}', '{\"en\":\"Patient Help & FAQs\",\"ar\":\"مساعدة المرضى والأسئلة الشائعة\"}', '{\"en\":\"<p>Find answers to frequently asked questions and helpful information about appointments, services, and visiting patients. We are here to support you and make your experience at Al Nas Hospital as smooth as possible.</p>\",\"ar\":\"<p>اعثر على إجابات للأسئلة الشائعة ومعلومات مفيدة حول المواعيد والخدمات وزيارة المرضى. نحن هنا لدعمك وجعل تجربتك في مستشفى الناس سلسة ومريحة قدر الإمكان.</p>\"}', NULL, '2026-02-11 19:52:12');
INSERT INTO `faq_sections` (`id`, `title`, `faqs`, `created_at`, `updated_at`) VALUES
(1, '{\"en\":\"Getting Care at Al Nas\",\"ar\":\"الرعاية الطبية بالمستشفى\"}', '[{\"question\":{\"en\":\"What are the hospital\'s working hours?\",\"ar\":\"\\u0645\\u0627 \\u0647\\u064a \\u0633\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649\\u061f\"},\"answer\":{\"en\":\"9 AM till 5 PM\",\"ar\":\"\\u0645\\u0646 \\u0627\\u0644\\u062a\\u0627\\u0633\\u0639\\u0629 \\u0635\\u0628\\u0627\\u062d\\u0627\\u064b \\u0644\\u0640 \\u0627\\u0644\\u062e\\u0627\\u0645\\u0633\\u0629 \\u0645\\u0633\\u0627\\u0621\\u0627\\u064b\"}},{\"question\":{\"en\":\" Where is Al Nas hospital located?\",\"ar\":\"\\u0623\\u064a\\u0646 \\u062a\\u0642\\u0639 \\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0627\\u0644\\u0646\\u0627\\u0633\\u061f\"},\"answer\":{\"en\":\"Address: Street 2, Shubra Al Kheima, Shubra El Kheima 1, Al-Qalyubia Governorate, Egypt\",\"ar\":\"\\u0627\\u0644\\u0639\\u0646\\u0648\\u0627\\u0646: \\u0634\\u0627\\u0631\\u0639 2\\u060c \\u0634\\u0628\\u0631\\u0627 \\u0627\\u0644\\u062e\\u064a\\u0645\\u0629\\u060c \\u0634\\u0628\\u0631\\u0627 \\u0627\\u0644\\u062e\\u064a\\u0645\\u0629 1\\u060c \\u0645\\u062d\\u0627\\u0641\\u0638\\u0629 \\u0627\\u0644\\u0642\\u0644\\u064a\\u0648\\u0628\\u064a\\u0629\\u060c \\u0645\\u0635\\u0631\"}},{\"question\":{\"en\":\" What medical specialties does the hospital cover?\",\"ar\":\"\\u0645\\u0627 \\u0647\\u064a \\u0627\\u0644\\u062a\\u062e\\u0635\\u0635\\u0627\\u062a \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u062a\\u064a \\u064a\\u063a\\u0637\\u064a\\u0647\\u0627 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649\\u061f\\u0631\"},\"answer\":{\"en\":\" Cardiothoracic surgery - Cardiac catheterization - GIT surgery - GIT endoscopy - Diabetes clinic - Burn - Liver transplantation\",\"ar\":\"\\u062c\\u0631\\u0627\\u062d\\u0629 \\u0642\\u0644\\u0628 \\u0648\\u0627\\u0648\\u0639\\u064a\\u0629 \\u062f\\u0645\\u0648\\u064a\\u0629 - \\u0642\\u0633\\u0637\\u0631\\u0629 \\u0642\\u0644\\u0628\\u064a\\u0629 - \\u062c\\u0631\\u0627\\u062d\\u0629 \\u062c\\u0647\\u0627\\u0632 \\u0647\\u0636\\u0645\\u064a - \\u0645\\u0646\\u0627\\u0638\\u064a\\u0631 \\u0642\\u0648\\u0644\\u0648\\u0646 - \\u0639\\u064a\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a - \\u062d\\u0631\\u0648\\u0642 - \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0643\\u0628\\u062f\"}},{\"question\":{\"en\":\"Is the hospital\'s treatment free of charge?\",\"ar\":\"\\u0647\\u0644 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0641\\u064a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0645\\u062c\\u0627\\u0646\\u064a\\u061f\"},\"answer\":{\"en\":\" Yes, all services at Al-Nas Hospital are provided free of charge\",\"ar\":\"\\u0646\\u0639\\u0645\\u060c \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u062e\\u062f\\u0645\\u0627\\u062a \\u0641\\u064a \\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u062a\\u0642\\u062f\\u0645 \\u0645\\u062c\\u0627\\u0646\\u0627\"}},{\"question\":{\"en\":\"How do I register as a new patient?\",\"ar\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0643\\u0645\\u0631\\u064a\\u0636 \\u062c\\u062f\\u064a\\u062f\\u061f\"},\"answer\":{\"en\":\"Select your specialty. Gather required medical documents. Submit documents via WhatsApp to specialty-specific number. Wait for medical committee review and approval.\",\"ar\":\"\\u064a\\u0631\\u062c\\u0649 \\u0627\\u062e\\u062a\\u064a\\u0627\\u0631 \\u0627\\u0644\\u062a\\u062e\\u0635\\u0635 \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u060c \\u062b\\u0645 \\u062a\\u062c\\u0647\\u064a\\u0632 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0644\\u0627\\u0632\\u0645\\u0629\\u060c \\u0648\\u0625\\u0631\\u0633\\u0627\\u0644\\u0647\\u0627 \\u0639\\u0628\\u0631 \\u062a\\u0637\\u0628\\u064a\\u0642 \\u0648\\u0627\\u062a\\u0633\\u0627\\u0628 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0645\\u062e\\u0635\\u0635 \\u0644\\u0643\\u0644 \\u062a\\u062e\\u0635\\u0635. \\u0628\\u0639\\u062f \\u0630\\u0644\\u0643\\u060c \\u0633\\u064a\\u062a\\u0645 \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u0648\\u0627\\u0639\\u062a\\u0645\\u0627\\u062f \\u0627\\u0644\\u0644\\u062c\\u0646\\u0629 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062e\\u062a\\u0635\\u0629.\"}}]', '2026-02-04 17:17:20', '2026-02-09 16:53:36'),
(5, '{\"en\":\"Contacting the Hospital\",\"ar\":\"التواصل مع المستشفى\"}', '[{\"question\":{\"en\":\"How can I contact the hospital for inquiries?\",\"ar\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0644\\u0644\\u0627\\u0633\\u062a\\u0641\\u0633\\u0627\\u0631\\u061f\"},\"answer\":{\"en\":\"For any inquiries, contact our customer service team: 01154410665 \\/ 01154410774 \\/ 0221283000\",\"ar\":\"\\u0628\\u0631\\u062c\\u0627\\u0621 \\u0627\\u0644\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0628\\u062e\\u062f\\u0645\\u0647 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0627\\u0631\\u0642\\u0627\\u0645 \\u0627\\u0644\\u062a\\u0627\\u0644\\u064a\\u0647: 01154410665 \\/ 01154410774 \\/  0221283000 \\/\"}},{\"question\":{\"en\":\"WhatsApp Contact Numbers by Specialty\",\"ar\":\"\\u0623\\u0631\\u0642\\u0627\\u0645 \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0628\\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u064a \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0648\\u0627\\u062a\\u0633\\u0627\\u0628 \\u0644\\u0643\\u0644 \\u062a\\u062e\\u0635\\u0635\"},\"answer\":{\"en\":\"Cardiology & Cardiothoracic clinic: +20 15 5575 7358\\nGastrointestinal clinic: +20 15 5519 7621\\nDiabetes clinic: +20 10 8077 7060\\nLiver Transplantation clinic: +20 15 5519 7563\\nBurn victims: +20 15 5519 7807\",\"ar\":\"\\u0639\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0648\\u062c\\u0631\\u0627\\u062d\\u0629 \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0648\\u0627\\u0644\\u0635\\u062f\\u0631: +20 15 5575 7358\\n\\u0639\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a: +20 15 5519 7621\\n\\u0639\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a: +20 10 8077 7060\\n\\u0639\\u064a\\u0627\\u062f\\u0629 \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0643\\u0628\\u062f: +20 15 5519 7563\\n\\u0636\\u062d\\u0627\\u064a\\u0627 \\u0627\\u0644\\u062d\\u0631\\u0648\\u0642: +20 15 5519 7807\"}}]', '2026-02-04 17:17:20', '2026-02-09 17:20:03'),
(2, '{\"en\":\"Required Documents by Specialty\",\"ar\":\"المستندات المطلوبة لكل تخصص\"}', '[{\"question\":{\"en\":\"What documents are needed to register in Gastrointestinal Department?\",\"ar\":\"\\u0645\\u0627 \\u0647\\u064a \\u0627\\u0644\\u0623\\u0648\\u0631\\u0627\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629 \\u0644\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0641\\u064a \\u0639\\u064a\\u0627\\u062f\\u0629 \\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a\\u061f\"},\"answer\":{\"en\":\"For Pediatric Patients:\\n\\nScanned copy of the child\\u2019s computerized birth certificate.\\n\\nScanned copy of one parent\\u2019s national ID (both sides).\\n\\nFor Adult Patients:\\n\\nScanned copy of the patient\\u2019s national ID (both sides) or passport.\\n\\nFor All Patients:\\n\\nTwo phone numbers (patient or first-degree relative).\\n\\nMedical documents showing the GIT condition (test results, endoscopy reports, medical reports, or CT scans of the digestive system).\\n\\nAll documents must clearly display the patient\\u2019s full name.\\n\\nImportant:\\n\\nAll required documents must be complete and clear.\\n\\nThe first step is to schedule an appointment at the preparatory clinic (waiting list applies).\",\"ar\":\"\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644:\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0634\\u0647\\u0627\\u062f\\u0629 \\u0645\\u064a\\u0644\\u0627\\u062f \\u0627\\u0644\\u0637\\u0641\\u0644 \\u0627\\u0644\\u0645\\u0645\\u064a\\u0643\\u0646\\u0629.\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0642\\u0648\\u0645\\u064a \\u0644\\u0623\\u062d\\u062f \\u0627\\u0644\\u0648\\u0627\\u0644\\u062f\\u064a\\u0646 (\\u0627\\u0644\\u0648\\u062c\\u0647\\u0627\\u0646).\\n\\n\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0628\\u0627\\u0644\\u063a\\u064a\\u0646:\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0642\\u0648\\u0645\\u064a \\u0644\\u0644\\u0645\\u0631\\u064a\\u0636 (\\u0627\\u0644\\u0648\\u062c\\u0647\\u0627\\u0646) \\u0623\\u0648 \\u062c\\u0648\\u0627\\u0632 \\u0627\\u0644\\u0633\\u0641\\u0631.\\n\\n\\u0641\\u064a \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a:\\n\\n\\u0631\\u0642\\u0645\\u0627\\u0646 \\u0647\\u0627\\u062a\\u0641\\u064a\\u0627\\u0646 (\\u0644\\u0644\\u0645\\u0631\\u064a\\u0636 \\u0623\\u0648 \\u0644\\u0623\\u062d\\u062f \\u0623\\u0642\\u0627\\u0631\\u0628\\u0647 \\u0645\\u0646 \\u0627\\u0644\\u062f\\u0631\\u062c\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649).\\n\\n\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0637\\u0628\\u064a\\u0629 \\u062a\\u0648\\u0636\\u062d \\u062d\\u0627\\u0644\\u0629 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a\\u060c \\u0645\\u062b\\u0644 \\u0646\\u062a\\u0627\\u0626\\u062c \\u0627\\u0644\\u062a\\u062d\\u0627\\u0644\\u064a\\u0644\\u060c \\u062a\\u0642\\u0627\\u0631\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0638\\u064a\\u0631\\u060c \\u0627\\u0644\\u062a\\u0642\\u0627\\u0631\\u064a\\u0631 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629\\u060c \\u0623\\u0648 \\u0627\\u0644\\u0623\\u0634\\u0639\\u0629 \\u0627\\u0644\\u0645\\u0642\\u0637\\u0639\\u064a\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a.\\n\\n\\u064a\\u062c\\u0628 \\u0623\\u0646 \\u062a\\u062d\\u062a\\u0648\\u064a \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0627\\u0633\\u0645 \\u0627\\u0644\\u0643\\u0627\\u0645\\u0644 \\u0644\\u0644\\u0645\\u0631\\u064a\\u0636.\\n\\n\\u0647\\u0627\\u0645:\\n\\n\\u064a\\u0634\\u062a\\u0631\\u0637 \\u0623\\u0646 \\u062a\\u0643\\u0648\\u0646 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0645\\u0643\\u062a\\u0645\\u0644\\u0629 \\u0648\\u0648\\u0627\\u0636\\u062d\\u0629.\\n\\n\\u0627\\u0644\\u062e\\u0637\\u0648\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649 \\u0647\\u064a \\u062d\\u062c\\u0632 \\u0645\\u0648\\u0639\\u062f \\u0628\\u0639\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0636\\u064a\\u0631\\u060c \\u0639\\u0644\\u0645\\u064b\\u0627 \\u0628\\u0648\\u062c\\u0648\\u062f \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631.\"}},{\"question\":{\"en\":\"What documents are needed to register in the Cardiac Department?\",\"ar\":\"\\u0633\\u0624\\u0627\\u0644: \\u0645\\u0627 \\u0647\\u064a \\u0627\\u0644\\u0623\\u0648\\u0631\\u0627\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629 \\u0644\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0641\\u064a \\u0639\\u064a\\u0627\\u062f\\u0629 \\u0623\\u0645\\u0631\\u0627\\u0636 \\u0627\\u0644\\u0642\\u0644\\u0628\\u061f\"},\"answer\":{\"en\":\"For Pediatric Patients:\\n\\nScanned copy of the child\\u2019s computerized birth certificate.\\n\\nChild\\u2019s weight (if under 3 years old).\\n\\nScanned copy of one parent\\u2019s national ID (both sides).\\n\\nFor Adult Patients:\\n\\nScanned copy of the patient\\u2019s national ID (both sides).\\n\\nFor All Patients:\\n\\nTwo phone numbers (patient or family member).\\n\\nMedical documents indicating the heart condition (ECG, echocardiography, or cardiac CT scan).\\n\\nFor Patients Under 18:\\n\\nHealth insurance authorization is required. Visit your health insurance office with the echocardiography report to obtain authorization (valid at any hospital).\",\"ar\":\"\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644:\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0634\\u0647\\u0627\\u062f\\u0629 \\u0645\\u064a\\u0644\\u0627\\u062f \\u0627\\u0644\\u0637\\u0641\\u0644 \\u0627\\u0644\\u0645\\u0645\\u064a\\u0643\\u0646\\u0629.\\n\\n\\u0648\\u0632\\u0646 \\u0627\\u0644\\u0637\\u0641\\u0644 (\\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646 \\u0627\\u0644\\u0639\\u0645\\u0631 \\u0623\\u0642\\u0644 \\u0645\\u0646 3 \\u0633\\u0646\\u0648\\u0627\\u062a).\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0642\\u0648\\u0645\\u064a \\u0644\\u0623\\u062d\\u062f \\u0627\\u0644\\u0648\\u0627\\u0644\\u062f\\u064a\\u0646 (\\u0627\\u0644\\u0648\\u062c\\u0647\\u0627\\u0646).\\n\\n\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0628\\u0627\\u0644\\u063a\\u064a\\u0646:\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0642\\u0648\\u0645\\u064a \\u0644\\u0644\\u0645\\u0631\\u064a\\u0636 (\\u0627\\u0644\\u0648\\u062c\\u0647\\u0627\\u0646).\\n\\n\\u0641\\u064a \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a:\\n\\n\\u0631\\u0642\\u0645\\u0627\\u0646 \\u0647\\u0627\\u062a\\u0641\\u064a\\u0627\\u0646 (\\u0644\\u0644\\u0645\\u0631\\u064a\\u0636 \\u0623\\u0648 \\u0623\\u062d\\u062f \\u0623\\u0641\\u0631\\u0627\\u062f \\u0627\\u0644\\u0623\\u0633\\u0631\\u0629).\\n\\n\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0637\\u0628\\u064a\\u0629 \\u062a\\u0648\\u0636\\u062d \\u062d\\u0627\\u0644\\u0629 \\u0627\\u0644\\u0642\\u0644\\u0628\\u060c \\u0645\\u062b\\u0644: \\u0631\\u0633\\u0645 \\u0627\\u0644\\u0642\\u0644\\u0628 (ECG)\\u060c \\u0627\\u0644\\u0625\\u064a\\u0643\\u0648 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0642\\u0644\\u0628\\u060c \\u0623\\u0648 \\u0627\\u0644\\u0623\\u0634\\u0639\\u0629 \\u0627\\u0644\\u0645\\u0642\\u0637\\u0639\\u064a\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0642\\u0644\\u0628.\\n\\n\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0623\\u0642\\u0644 \\u0645\\u0646 18 \\u0639\\u0627\\u0645\\u064b\\u0627:\\n\\n\\u064a\\u0634\\u062a\\u0631\\u0637 \\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0645\\u0648\\u0627\\u0641\\u0642\\u0629 \\u0627\\u0644\\u062a\\u0623\\u0645\\u064a\\u0646 \\u0627\\u0644\\u0635\\u062d\\u064a.\\n\\n\\u064a\\u062a\\u0645 \\u0627\\u0644\\u062a\\u0648\\u062c\\u0647 \\u0625\\u0644\\u0649 \\u0645\\u0643\\u062a\\u0628 \\u0627\\u0644\\u062a\\u0623\\u0645\\u064a\\u0646 \\u0627\\u0644\\u0635\\u062d\\u064a \\u0645\\u0635\\u0637\\u062d\\u0628\\u064a\\u0646 \\u062a\\u0642\\u0631\\u064a\\u0631 \\u0627\\u0644\\u0625\\u064a\\u0643\\u0648 \\u0644\\u0627\\u0633\\u062a\\u062e\\u0631\\u0627\\u062c \\u0627\\u0644\\u0645\\u0648\\u0627\\u0641\\u0642\\u0629\\u060c \\u0648\\u0647\\u064a \\u0635\\u0627\\u0644\\u062d\\u0629 \\u0644\\u0644\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0641\\u064a \\u0623\\u064a \\u0645\\u0633\\u062a\\u0634\\u0641\\u0649.\"}},{\"question\":{\"en\":\"What documents are needed to register in the Fetal Echo Department?\",\"ar\":\"\\u0627\\u0644\\u0627\\u0648\\u0631\\u0627\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629 \\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0641\\u064a \\u0639\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0643\\u0634\\u0641 \\u0639\\u0644\\u0649 \\u0642\\u0644\\u0628 \\u0627\\u0644\\u0623\\u062c\\u0646\\u0629\"},\"answer\":{\"en\":\"\\\"Required Documents:\\n\\nScanned copy of the mother\\u2019s national ID (both sides) or passport.\\n\\nTwo contact phone numbers (patient or first-degree family member).\\n\\nMother\\u2019s ultrasound report.\\n\\nImportant:\\n\\nAll documents must be complete and clear.\\n\\nThe first step is to schedule an appointment at the preparatory clinic (waiting list applies).\",\"ar\":\"\\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629:\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0642\\u0648\\u0645\\u064a \\u0644\\u0644\\u0623\\u0645 (\\u0627\\u0644\\u0648\\u062c\\u0647\\u0627\\u0646) \\u0623\\u0648 \\u062c\\u0648\\u0627\\u0632 \\u0627\\u0644\\u0633\\u0641\\u0631.\\n\\u0631\\u0642\\u0645\\u0627 \\u0647\\u0627\\u062a\\u0641 \\u0644\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 (\\u0644\\u0644\\u0645\\u0631\\u064a\\u0636\\u0629 \\u0623\\u0648 \\u0644\\u0623\\u062d\\u062f \\u0623\\u0642\\u0627\\u0631\\u0628\\u0647\\u0627 \\u0645\\u0646 \\u0627\\u0644\\u062f\\u0631\\u062c\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649).\\n\\u062a\\u0642\\u0631\\u064a\\u0631 \\u0627\\u0644\\u0633\\u0648\\u0646\\u0627\\u0631 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0627\\u0644\\u0623\\u0645.\\n\\n\\u0647\\u0627\\u0645:\\n\\u064a\\u0634\\u062a\\u0631\\u0637 \\u0623\\u0646 \\u062a\\u0643\\u0648\\u0646 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629 \\u0645\\u0643\\u062a\\u0645\\u0644\\u0629 \\u0648\\u0648\\u0627\\u0636\\u062d\\u0629.\\n\\u0627\\u0644\\u062e\\u0637\\u0648\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649 \\u0647\\u064a \\u062d\\u062c\\u0632 \\u0645\\u0648\\u0639\\u062f \\u0628\\u0639\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0636\\u064a\\u0631\\u060c \\u0639\\u0644\\u0645\\u064b\\u0627 \\u0628\\u0648\\u062c\\u0648\\u062f \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631.\"}},{\"question\":{\"en\":\"What documents are needed to register in the Diabetes Department?\",\"ar\":\"\\u0645\\u0627 \\u0647\\u064a \\u0627\\u0644\\u0623\\u0648\\u0631\\u0627\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629 \\u0644\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0641\\u064a \\u0639\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a\\u061f\"},\"answer\":{\"en\":\"For All Patients:\\n\\nPrevious prescription or medical report confirming the diabetes diagnosis.\\n\\nHbA1c (glycated hemoglobin) test report from the past three months.\\n\\nDaily record of blood sugar and insulin levels for one week before the visit, including readings:\\n\\nBefore and after meals\\n\\nBefore bedtime\\n\\nUpon waking\\n\\nFor Pediatric Patients:\\n\\nScanned copy of the child\\u2019s birth certificate.\\n\\nScanned copy of one parent\\u2019s national ID (both sides).\\n\\nFor Adult Patients:\\n\\nValid national ID (both sides).\\n\\nTwo different contact phone numbers.\",\"ar\":\"\\u0641\\u064a \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a:\\n\\n\\u0631\\u0648\\u0634\\u062a\\u0629 \\u0639\\u0644\\u0627\\u062c \\u0633\\u0627\\u0628\\u0642\\u0629 \\u0623\\u0648 \\u062a\\u0642\\u0631\\u064a\\u0631 \\u0637\\u0628\\u064a \\u064a\\u0624\\u0643\\u062f \\u062a\\u0634\\u062e\\u064a\\u0635 \\u0645\\u0631\\u0636 \\u0627\\u0644\\u0633\\u0643\\u0631\\u064a.\\n\\n\\u062a\\u0642\\u0631\\u064a\\u0631 \\u062a\\u062d\\u0644\\u064a\\u0644 HbA1c (\\u0627\\u0644\\u0633\\u0643\\u0631 \\u0627\\u0644\\u062a\\u0631\\u0627\\u0643\\u0645\\u064a) \\u062e\\u0644\\u0627\\u0644 \\u0627\\u0644\\u062b\\u0644\\u0627\\u062b\\u0629 \\u0623\\u0634\\u0647\\u0631 \\u0627\\u0644\\u0645\\u0627\\u0636\\u064a\\u0629.\\n\\n\\u0633\\u062c\\u0644 \\u064a\\u0648\\u0645\\u064a \\u0644\\u0645\\u0633\\u062a\\u0648\\u064a\\u0627\\u062a \\u0627\\u0644\\u0633\\u0643\\u0631 \\u0641\\u064a \\u0627\\u0644\\u062f\\u0645 \\u0648\\u062c\\u0631\\u0639\\u0627\\u062a \\u0627\\u0644\\u0625\\u0646\\u0633\\u0648\\u0644\\u064a\\u0646 \\u0644\\u0645\\u062f\\u0629 \\u0623\\u0633\\u0628\\u0648\\u0639 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u0632\\u064a\\u0627\\u0631\\u0629\\u060c \\u0645\\u0648\\u0636\\u062d\\u064b\\u0627 \\u0627\\u0644\\u0642\\u0631\\u0627\\u0621\\u0627\\u062a:\\n\\n\\u0642\\u0628\\u0644 \\u0648\\u0628\\u0639\\u062f \\u0627\\u0644\\u0648\\u062c\\u0628\\u0627\\u062a\\n\\n\\u0642\\u0628\\u0644 \\u0627\\u0644\\u0646\\u0648\\u0645\\n\\n\\u0639\\u0646\\u062f \\u0627\\u0644\\u0627\\u0633\\u062a\\u064a\\u0642\\u0627\\u0638\\n\\n\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644:\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0634\\u0647\\u0627\\u062f\\u0629 \\u0645\\u064a\\u0644\\u0627\\u062f \\u0627\\u0644\\u0637\\u0641\\u0644.\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0642\\u0648\\u0645\\u064a \\u0644\\u0623\\u062d\\u062f \\u0627\\u0644\\u0648\\u0627\\u0644\\u062f\\u064a\\u0646 (\\u0627\\u0644\\u0648\\u062c\\u0647\\u0627\\u0646).\\n\\n\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0628\\u0627\\u0644\\u063a\\u064a\\u0646:\\n\\n\\u0628\\u0637\\u0627\\u0642\\u0629 \\u0631\\u0642\\u0645 \\u0642\\u0648\\u0645\\u064a \\u0633\\u0627\\u0631\\u064a\\u0629 (\\u0627\\u0644\\u0648\\u062c\\u0647\\u0627\\u0646).\\n\\n\\u0631\\u0642\\u0645\\u0627 \\u0647\\u0627\\u062a\\u0641 \\u0645\\u062e\\u062a\\u0644\\u0641\\u0627\\u0646 \\u0644\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644.\"}},{\"question\":{\"en\":\"What documents are needed to register in the Burn Department?\",\"ar\":\"\\u0645\\u0627 \\u0647\\u064a \\u0627\\u0644\\u0623\\u0648\\u0631\\u0627\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629 \\u0644\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0641\\u064a \\u0639\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u062d\\u0631\\u0648\\u0642\\u061f\"},\"answer\":{\"en\":\"For Pediatric Patients:\\n\\nScanned copy of the child\\u2019s computerized birth certificate.\\n\\nScanned copy of one parent\\u2019s national ID (both sides).\\n\\nFor Adult Patients:\\n\\nScanned copy of the patient\\u2019s national ID (both sides) or passport.\\n\\nFor All Patients:\\n\\nTwo different contact phone numbers (patient or first-degree family member).\\n\\nA clear photo of the burn.\\n\\nIf the patient received treatment elsewhere: a medical report detailing the treatment provided.\\n\\nImportant:\\n\\nAll required documents must be complete and clear.\\n\\nThe first step is to schedule an appointment at the preparatory clinic (waiting list applies)\",\"ar\":\"\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644:\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0634\\u0647\\u0627\\u062f\\u0629 \\u0645\\u064a\\u0644\\u0627\\u062f \\u0627\\u0644\\u0637\\u0641\\u0644 \\u0627\\u0644\\u0645\\u0645\\u064a\\u0643\\u0646\\u0629.\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0642\\u0648\\u0645\\u064a \\u0644\\u0623\\u062d\\u062f \\u0627\\u0644\\u0648\\u0627\\u0644\\u062f\\u064a\\u0646 (\\u0627\\u0644\\u0648\\u062c\\u0647\\u0627\\u0646).\\n\\n\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0628\\u0627\\u0644\\u063a\\u064a\\u0646:\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0642\\u0648\\u0645\\u064a \\u0644\\u0644\\u0645\\u0631\\u064a\\u0636 (\\u0627\\u0644\\u0648\\u062c\\u0647\\u0627\\u0646) \\u0623\\u0648 \\u062c\\u0648\\u0627\\u0632 \\u0627\\u0644\\u0633\\u0641\\u0631.\\n\\n\\u0641\\u064a \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a:\\n\\n\\u0631\\u0642\\u0645\\u0627 \\u0647\\u0627\\u062a\\u0641 \\u0645\\u062e\\u062a\\u0644\\u0641\\u0627\\u0646 \\u0644\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 (\\u0644\\u0644\\u0645\\u0631\\u064a\\u0636 \\u0623\\u0648 \\u0644\\u0623\\u062d\\u062f \\u0623\\u0642\\u0627\\u0631\\u0628\\u0647 \\u0645\\u0646 \\u0627\\u0644\\u062f\\u0631\\u062c\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649).\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0648\\u0627\\u0636\\u062d\\u0629 \\u0644\\u0644\\u062d\\u0631\\u0642.\\n\\n\\u0641\\u064a \\u062d\\u0627\\u0644 \\u062a\\u0644\\u0642\\u064a \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0633\\u0627\\u0628\\u0642\\u064b\\u0627 \\u0641\\u064a \\u062c\\u0647\\u0629 \\u0623\\u062e\\u0631\\u0649: \\u062a\\u0642\\u0631\\u064a\\u0631 \\u0637\\u0628\\u064a \\u064a\\u0648\\u0636\\u062d \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0627\\u0644\\u0630\\u064a \\u062a\\u0645 \\u062a\\u0642\\u062f\\u064a\\u0645\\u0647.\\n\\n\\u0647\\u0627\\u0645:\\n\\n\\u064a\\u0634\\u062a\\u0631\\u0637 \\u0623\\u0646 \\u062a\\u0643\\u0648\\u0646 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629 \\u0645\\u0643\\u062a\\u0645\\u0644\\u0629 \\u0648\\u0648\\u0627\\u0636\\u062d\\u0629.\\n\\n\\u0627\\u0644\\u062e\\u0637\\u0648\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649 \\u0647\\u064a \\u062d\\u062c\\u0632 \\u0645\\u0648\\u0639\\u062f \\u0628\\u0639\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0636\\u064a\\u0631\\u060c \\u0639\\u0644\\u0645\\u064b\\u0627 \\u0628\\u0648\\u062c\\u0648\\u062f \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631.\"}},{\"question\":{\"en\":\" What are the needed documents to register in the Liver Transplant department?\",\"ar\":\"\\u0627\\u0644\\u0627\\u0648\\u0631\\u0627\\u0642 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629 \\u0644\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0641\\u064a \\u0639\\u064a\\u0627\\u062f\\u0629 \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0643\\u0628\\u062f\"},\"answer\":{\"en\":\"For Pediatric Patients: Scanned copy of child\'s computerized birth certificate, Scanned copy of one parent\'s national ID (both sides). For Adult Patients: Scanned copy of patient\'s national ID (both sides) or passport. For All Cases: Two different phone numbers (patient or first-degree family member), Any medical investigations indicating diagnosis (lab tests, medical reports, imaging, etc.). Important: All documents must be complete and clear. The first step is scheduling appointment at preparatory clinic (waiting list exists).\",\"ar\":\"\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644:\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0634\\u0647\\u0627\\u062f\\u0629 \\u0645\\u064a\\u0644\\u0627\\u062f \\u0627\\u0644\\u0637\\u0641\\u0644 \\u0627\\u0644\\u0645\\u0645\\u064a\\u0643\\u0646\\u0629.\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0642\\u0648\\u0645\\u064a \\u0644\\u0623\\u062d\\u062f \\u0627\\u0644\\u0648\\u0627\\u0644\\u062f\\u064a\\u0646 (\\u0627\\u0644\\u0648\\u062c\\u0647\\u0627\\u0646).\\n\\n\\u0628\\u0627\\u0644\\u0646\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0628\\u0627\\u0644\\u063a\\u064a\\u0646:\\n\\n\\u0635\\u0648\\u0631\\u0629 \\u0645\\u0645\\u0633\\u0648\\u062d\\u0629 \\u0636\\u0648\\u0626\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0642\\u0648\\u0645\\u064a \\u0644\\u0644\\u0645\\u0631\\u064a\\u0636 (\\u0627\\u0644\\u0648\\u062c\\u0647\\u0627\\u0646) \\u0623\\u0648 \\u062c\\u0648\\u0627\\u0632 \\u0627\\u0644\\u0633\\u0641\\u0631.\\n\\n\\u0641\\u064a \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a:\\n\\u0631\\u0642\\u0645\\u0627 \\u0647\\u0627\\u062a\\u0641 \\u0645\\u062e\\u062a\\u0644\\u0641\\u0627\\u0646 \\u0644\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 (\\u0644\\u0644\\u0645\\u0631\\u064a\\u0636 \\u0623\\u0648 \\u0644\\u0623\\u062d\\u062f \\u0623\\u0642\\u0627\\u0631\\u0628\\u0647 \\u0645\\u0646 \\u0627\\u0644\\u062f\\u0631\\u062c\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649).\\n\\u0623\\u064a \\u0641\\u062d\\u0648\\u0635\\u0627\\u062a \\u0623\\u0648 \\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0637\\u0628\\u064a\\u0629 \\u062a\\u062f\\u0639\\u0645 \\u0627\\u0644\\u062a\\u0634\\u062e\\u064a\\u0635\\u060c \\u0645\\u062b\\u0644 \\u0627\\u0644\\u062a\\u062d\\u0627\\u0644\\u064a\\u0644 \\u0627\\u0644\\u0645\\u0639\\u0645\\u0644\\u064a\\u0629\\u060c \\u0627\\u0644\\u062a\\u0642\\u0627\\u0631\\u064a\\u0631 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629\\u060c \\u0623\\u0648 \\u0627\\u0644\\u0641\\u062d\\u0648\\u0635\\u0627\\u062a \\u0627\\u0644\\u0625\\u0634\\u0639\\u0627\\u0639\\u064a\\u0629 \\u0648\\u063a\\u064a\\u0631\\u0647\\u0627.\\n\\n\\u0647\\u0627\\u0645:\\n\\u064a\\u0634\\u062a\\u0631\\u0637 \\u0623\\u0646 \\u062a\\u0643\\u0648\\u0646 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629 \\u0645\\u0643\\u062a\\u0645\\u0644\\u0629 \\u0648\\u0648\\u0627\\u0636\\u062d\\u0629.\\n\\u0627\\u0644\\u062e\\u0637\\u0648\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649 \\u0647\\u064a \\u062d\\u062c\\u0632 \\u0645\\u0648\\u0639\\u062f \\u0628\\u0639\\u064a\\u0627\\u062f\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0636\\u064a\\u0631\\u060c \\u0639\\u0644\\u0645\\u064b\\u0627 \\u0628\\u0648\\u062c\\u0648\\u062f \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631.\"}}]', '2026-02-04 17:17:20', '2026-02-09 16:47:01'),
(3, '{\"en\":\"Appointments & Scheduling\",\"ar\":\"الحجز و المواعيد\"}', '[{\"question\":{\"en\":\" How long does it take to get an appointment?\",\"ar\":\"\\u0643\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0648\\u0642\\u062a \\u064a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0645\\u0648\\u0639\\u062f\\u061f\"},\"answer\":{\"en\":\"The first time you take your turn in any procedure, you will be contacted because there are waiting lists\",\"ar\":\"\\u0639\\u0646\\u062f \\u062d\\u0644\\u0648\\u0644 \\u062f\\u0648\\u0631\\u0643\\u0645 \\u0644\\u0623\\u0648\\u0644 \\u0645\\u0631\\u0629 \\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0623\\u064a \\u062a\\u062f\\u062e\\u0644 \\u0637\\u0628\\u064a\\u060c \\u0633\\u064a\\u062a\\u0645 \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0643\\u0645 \\u0646\\u0638\\u0631\\u064b\\u0627 \\u0644\\u0648\\u062c\\u0648\\u062f \\u0642\\u0648\\u0627\\u0626\\u0645 \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631.\"}},{\"question\":{\"en\":\" How do I book a follow-up appointment?\",\"ar\":\"\\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062d\\u062c\\u0632 \\u0645\\u0648\\u0639\\u062f \\u0644\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629\\u061f\"},\"answer\":{\"en\":\"After your initial appointment, the hospital will contact you directly through the relevant department for any follow-up scheduling.\",\"ar\":\"\\u0628\\u0639\\u062f \\u0645\\u0648\\u0639\\u062f\\u0643\\u0645 \\u0627\\u0644\\u0623\\u0648\\u0644\\u064a\\u060c \\u0633\\u062a\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0643\\u0645 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629\\u064b \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0642\\u0633\\u0645 \\u0627\\u0644\\u0645\\u062e\\u062a\\u0635 \\u0644\\u062a\\u0631\\u062a\\u064a\\u0628 \\u0623\\u064a \\u0645\\u0648\\u0627\\u0639\\u064a\\u062f \\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0644\\u0627\\u062d\\u0642\\u0629.\"}},{\"question\":{\"en\":\"Ques 1?\",\"ar\":null},\"answer\":{\"en\":\"Lorem ipsum dolor sit amet, consectetur adipisicing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum \",\"ar\":null}},{\"question\":{\"en\":\" Can I walk in without an appointment?\",\"ar\":\"\\u0647\\u0644 \\u0623\\u0633\\u062a\\u0637\\u064a\\u0639 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0628\\u062f\\u0648\\u0646 \\u0645\\u0648\\u0639\\u062f\\u061f\"},\"answer\":{\"en\":\"No\",\"ar\":\"\\u0644\\u0623\"}},{\"question\":{\"en\":\" How will I know my appointment date?\",\"ar\":\"\\u0643\\u064a\\u0641 \\u0633\\u0623\\u0639\\u0631\\u0641 \\u0645\\u0648\\u0639\\u062f\\u064a\\u061f\"},\"answer\":{\"en\":\"You have a scheduled appointment, and the relevant department will contact you and a text message will be sent.\",\"ar\":\"\\u0644\\u062f\\u064a\\u0643 \\u0645\\u0648\\u0639\\u062f \\u0645\\u062d\\u062f\\u062f\\u060c \\u0648\\u0633\\u0648\\u0641 \\u064a\\u0642\\u0648\\u0645 \\u0627\\u0644\\u0642\\u0633\\u0645 \\u0627\\u0644\\u0645\\u062e\\u062a\\u0635 \\u0628\\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0643 \\u0648\\u0633\\u064a\\u062a\\u0645 \\u0627\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0631\\u0633\\u0627\\u0644\\u0629 \\u0646\\u0635\\u064a\\u0629\"}},{\"question\":{\"en\":\"What should I do if I miss my appointment?\",\"ar\":\"\\u0645\\u0627\\u0630\\u0627 \\u064a\\u062c\\u0628 \\u0623\\u0646 \\u0623\\u0641\\u0639\\u0644 \\u0625\\u0630\\u0627 \\u0641\\u0627\\u062a\\u0646\\u064a \\u0645\\u0648\\u0639\\u062f\\u064a\\u061f\"},\"answer\":{\"en\":\"Please contact customer service immediately to reschedule.\",\"ar\":\"\\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639 \\u062e\\u062f\\u0645\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0641\\u0648\\u0631\\u064b\\u0627 \\u0644\\u0625\\u0639\\u0627\\u062f\\u0629 \\u062c\\u062f\\u0648\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0648\\u0639\\u062f.\"}}]', '2026-02-04 17:17:20', '2026-02-09 17:08:03'),
(4, '{\"en\":\"Medical Reports & Certificates\",\"ar\":\"التقارير و الشهادات الطبية\"}', '[{\"question\":{\"en\":\"Can I get a medical certificate or official report from the hospital?\",\"ar\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0634\\u0647\\u0627\\u062f\\u0629 \\u0637\\u0628\\u064a\\u0629 \\u0623\\u0648 \\u062a\\u0642\\u0631\\u064a\\u0631 \\u0631\\u0633\\u0645\\u064a \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649\\u061f\"},\"answer\":{\"en\":\"You must come to receive it in person every day from 9 AM to 3 PM, except Friday and Saturday. Any first-degree relative can receive it with an ID card after contacting customer service to confirm the result is ready.\",\"ar\":\"\\u064a\\u062c\\u0628 \\u0627\\u0644\\u062d\\u0636\\u0648\\u0631 \\u0644\\u0627\\u0633\\u062a\\u0644\\u0627\\u0645\\u0647 \\u0634\\u062e\\u0635\\u064a\\u064b\\u0627 \\u064a\\u0648\\u0645\\u064a\\u064b\\u0627 \\u0645\\u0646 \\u0627\\u0644\\u0633\\u0627\\u0639\\u0629 9 \\u0635\\u0628\\u0627\\u062d\\u064b\\u0627 \\u062d\\u062a\\u0649 3 \\u0645\\u0633\\u0627\\u0621\\u064b\\u060c \\u0645\\u0627 \\u0639\\u062f\\u0627 \\u064a\\u0648\\u0645\\u064a \\u0627\\u0644\\u062c\\u0645\\u0639\\u0629 \\u0648\\u0627\\u0644\\u0633\\u0628\\u062a. \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0623\\u064a \\u0642\\u0631\\u064a\\u0628 \\u0645\\u0646 \\u0627\\u0644\\u062f\\u0631\\u062c\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649 \\u0627\\u0633\\u062a\\u0644\\u0627\\u0645\\u0647 \\u0645\\u0639 \\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0647\\u0648\\u064a\\u0629 \\u0628\\u0639\\u062f \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639 \\u062e\\u062f\\u0645\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0644\\u062a\\u0623\\u0643\\u064a\\u062f \\u062c\\u0627\\u0647\\u0632\\u064a\\u0629 \\u0627\\u0644\\u0646\\u062a\\u064a\\u062c\\u0629.\"}},{\"question\":{\"en\":\"When can I receive discharge summary?\",\"ar\":\"\\u0645\\u062a\\u0649 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0627\\u0633\\u062a\\u0644\\u0627\\u0645 \\u0645\\u0644\\u062e\\u0635 \\u0627\\u0644\\u062e\\u0631\\u0648\\u062c\\u061f\"},\"answer\":{\"en\":\"Coordinate with your treating physician for timing.\",\"ar\":\"\\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u062a\\u0646\\u0633\\u064a\\u0642 \\u0645\\u0639 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0628 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0644\\u062c \\u0644\\u062a\\u062d\\u062f\\u064a\\u062f \\u0627\\u0644\\u062a\\u0648\\u0642\\u064a\\u062a \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628.\"}},{\"question\":{\"en\":\" Can I collect my medical reports online?\",\"ar\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u062c\\u0645\\u0639 \\u062a\\u0642\\u0627\\u0631\\u064a\\u0631\\u064a \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a\\u061f\"},\"answer\":{\"en\":\" You must come in person to collect from 9 AM to 3 PM, except Friday and Saturday.\",\"ar\":\"\\u0628\\u062a\\u064a\\u062c\\u0649 \\u062a\\u0633\\u062a\\u0644\\u0645\\u0647\\u0627 \\u0643\\u0644 \\u064a\\u0648\\u0645 \\u0645\\u0646 9 \\u0635 \\u062d\\u062a\\u0649 3 \\u0639\\u0635\\u0631\\u0627 \\u0645\\u0639\\u0627\\u062f \\u0627\\u0644\\u062c\\u0645\\u0639\\u0647 \\u0648\\u0627\\u0644\\u0633\\u0628\\u062a\"}},{\"question\":{\"en\":\"Can I get medical tests or imaging done without being a hospital patient?\",\"ar\":\"\\u0647\\u0644 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u0641\\u062d\\u0648\\u0635\\u0627\\u062a \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0623\\u0648 \\u0627\\u0644\\u062a\\u0635\\u0648\\u064a\\u0631 \\u062f\\u0648\\u0646 \\u0623\\u0646 \\u0623\\u0643\\u0648\\u0646 \\u0645\\u0631\\u064a\\u0636\\u0627\\u064b \\u0641\\u064a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649\\u061f\"},\"answer\":{\"en\":\"Al Nas Hoospital is a medical city for treatment and managemet of multiple specialities and not a center for conducting tests \\/ imaging. Requesting investigations is the responsibility of the treating physician and based on the requirements of the patient\'s health condition.\",\"ar\":\"\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0647\\u0648 \\u0645\\u062f\\u064a\\u0646\\u0629 \\u0637\\u0628\\u064a\\u0629 \\u0645\\u062a\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0644\\u0639\\u0644\\u0627\\u062c \\u0648\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0645\\u062e\\u062a\\u0644\\u0641 \\u0627\\u0644\\u062a\\u062e\\u0635\\u0635\\u0627\\u062a \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629\\u060c \\u0648\\u0644\\u064a\\u0633 \\u0645\\u0631\\u0643\\u0632\\u064b\\u0627 \\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u0641\\u062d\\u0648\\u0635\\u0627\\u062a \\u0623\\u0648 \\u0627\\u0644\\u0623\\u0634\\u0639\\u0629. \\u0648\\u064a\\u064f\\u0639\\u062f \\u0637\\u0644\\u0628 \\u0627\\u0644\\u0641\\u062d\\u0648\\u0635\\u0627\\u062a \\u0648\\u0627\\u0644\\u0623\\u0634\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0645\\u0646 \\u0645\\u0633\\u0624\\u0648\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0628 \\u0627\\u0644\\u0645\\u0639\\u0627\\u0644\\u062c\\u060c \\u0648\\u0630\\u0644\\u0643 \\u0648\\u0641\\u0642\\u064b\\u0627 \\u0644\\u0645\\u062a\\u0637\\u0644\\u0628\\u0627\\u062a \\u0627\\u0644\\u062d\\u0627\\u0644\\u0629 \\u0627\\u0644\\u0635\\u062d\\u064a\\u0629 \\u0644\\u0644\\u0645\\u0631\\u064a\\u0636.\"}}]', '2026-02-04 17:17:20', '2026-02-09 17:13:29'),
(6, '{\"en\":\"Application Status & Medical Review\",\"ar\":\"حالة الطلب والمراجعة الطبية\"}', '[{\"question\":{\"en\":\" After sending documents; when will the hospital call me?\",\"ar\":\"\\u0628\\u0639\\u062f \\u062a\\u0642\\u062f\\u064a\\u0645 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0648\\u0631\\u0627\\u0642\\/ \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a\\u060c \\u0645\\u062a\\u0649 \\u0633\\u062a\\u062a\\u0635\\u0644 \\u0628\\u064a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649\\u061f\"},\"answer\":{\"en\":\"\\/ Your submitted medical reports are under review by our medical committee. The case is still pending approval.\",\"ar\":\"\\u062a\\u0642\\u0627\\u0631\\u064a\\u0631\\u0643 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0642\\u062f\\u0645\\u0629 \\u0642\\u064a\\u062f \\u0627\\u0644\\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u0645\\u0646 \\u0642\\u0628\\u0644 \\u0644\\u062c\\u0646\\u062a\\u0646\\u0627 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629. \\u0648\\u0644\\u0627 \\u062a\\u0632\\u0627\\u0644 \\u0627\\u0644\\u0642\\u0636\\u064a\\u0629 \\u0641\\u064a \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0641\\u0642\\u0629\"}},{\"question\":{\"en\":\"What should I do if my documents need revision?\",\"ar\":\"\\u0645\\u0627\\u0630\\u0627 \\u0623\\u0641\\u0639\\u0644 \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646\\u062a \\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a\\u064a \\u0628\\u062d\\u0627\\u062c\\u0629 \\u0644\\u0644\\u062a\\u0639\\u062f\\u064a\\u0644\\u061f\"},\"answer\":{\"en\":\"Please provide the missing or unclear documents:\\nSend an alternative phone number.\\nSend the back of your ID card.\\nResend the birth certificate with a clear picture.\\nSend pictures of your EKG (not a video).\",\"ar\":\"\\u064a\\u0631\\u062c\\u0649 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0627\\u0644\\u0645\\u0641\\u0642\\u0648\\u062f\\u0629 \\u0623\\u0648 \\u063a\\u064a\\u0631 \\u0627\\u0644\\u0648\\u0627\\u0636\\u062d\\u0629:\\n\\n\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0631\\u0642\\u0645 \\u062a\\u0644\\u064a\\u0641\\u0648\\u0646 \\u0622\\u062e\\u0631.\\n\\n\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0638\\u0647\\u0631 \\u0627\\u0644\\u0628\\u0637\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0634\\u062e\\u0635\\u064a\\u0629.\\n\\n\\u0625\\u0639\\u0627\\u062f\\u0629 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0634\\u0647\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0645\\u064a\\u0644\\u0627\\u062f \\u0628\\u0635\\u0648\\u0631\\u0629 \\u0648\\u0627\\u0636\\u062d\\u0629.\\n\\n\\u0625\\u0631\\u0633\\u0627\\u0644 \\u0635\\u0648\\u0631 \\u0631\\u0633\\u0645 \\u0627\\u0644\\u0642\\u0644\\u0628 (\\u0648\\u0644\\u064a\\u0633 \\u0641\\u064a\\u062f\\u064a\\u0648).\"}},{\"question\":{\"en\":\"What happens if my case is not accepted?\",\"ar\":\"\\u0645\\u0627\\u0630\\u0627 \\u064a\\u0639\\u0646\\u064a \\u0642\\u0628\\u0648\\u0644 \\u062d\\u0627\\u0644\\u062a\\u064a\\u061f\"},\"answer\":{\"en\":\"Your case has been accepted. Please wait until we contact you to inform you of your examination date.\\nYou have also been successfully registered and added to the waiting list. Someone will contact you soon with further updates.\",\"ar\":\"\\u062a\\u0645 \\u0642\\u0628\\u0648\\u0644 \\u062d\\u0627\\u0644\\u062a\\u0643. \\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u062d\\u062a\\u0649 \\u0646\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0643 \\u0644\\u062a\\u062d\\u062f\\u064a\\u062f \\u0645\\u0648\\u0639\\u062f \\u0627\\u0644\\u0643\\u0634\\u0641.\\n\\u062a\\u0645 \\u062a\\u0633\\u062c\\u064a\\u0644\\u0643 \\u0628\\u0646\\u062c\\u0627\\u062d \\u0648\\u0625\\u0636\\u0627\\u0641\\u062a\\u0643 \\u0625\\u0644\\u0649 \\u0642\\u0627\\u0626\\u0645\\u0629 \\u0627\\u0644\\u0627\\u0646\\u062a\\u0638\\u0627\\u0631\\u060c \\u0648\\u0633\\u064a\\u062a\\u0645 \\u0627\\u0644\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0628\\u0643 \\u0642\\u0631\\u064a\\u0628\\u064b\\u0627 \\u0644\\u0645\\u0632\\u064a\\u062f \\u0645\\u0646 \\u0627\\u0644\\u062a\\u062d\\u062f\\u064a\\u062b\\u0627\\u062a.\"}},{\"question\":{\"en\":\"What happens if my case is not accepted?\",\"ar\":\"\\u0645\\u0627\\u0630\\u0627 \\u064a\\u062d\\u062f\\u062b \\u0625\\u0630\\u0627 \\u0644\\u0645 \\u064a\\u062a\\u0645 \\u0642\\u0628\\u0648\\u0644 \\u062d\\u0627\\u0644\\u062a\\u064a\\u061f\"},\"answer\":{\"en\":\"Al-Nas Hospital apologizes for not being able to accept your case at this time. We advise you to follow up at another hospital.\",\"ar\":\"\\u064a\\u0639\\u062a\\u0630\\u0631 \\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0639\\u0646 \\u0639\\u062f\\u0645 \\u0642\\u0628\\u0648\\u0644 \\u062d\\u0627\\u0644\\u062a\\u0643 \\u0641\\u064a \\u0627\\u0644\\u0648\\u0642\\u062a \\u0627\\u0644\\u062d\\u0627\\u0644\\u064a. \\u0646\\u0646\\u0635\\u062d\\u0643 \\u0628\\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0641\\u064a \\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0622\\u062e\\u0631.\"}},{\"question\":{\"en\":\"What if my submitted documents are unclear?\",\"ar\":\"\\u0645\\u0627\\u0630\\u0627 \\u0623\\u0641\\u0639\\u0644 \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646\\u062a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u0642\\u062f\\u0645\\u062a\\u0647\\u0627 \\u063a\\u064a\\u0631 \\u0648\\u0627\\u0636\\u062d\\u0629\\u061f\"},\"answer\":{\"en\":\"Some details are missing or your documents are unclear. Please re-submit the required information.\",\"ar\":\"\\u0628\\u0639\\u0636 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0645\\u0641\\u0642\\u0648\\u062f\\u0629 \\u0623\\u0648 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0646\\u062f\\u0627\\u062a \\u063a\\u064a\\u0631 \\u0648\\u0627\\u0636\\u062d\\u0629. \\u064a\\u0631\\u062c\\u0649 \\u0625\\u0639\\u0627\\u062f\\u0629 \\u0625\\u0631\\u0633\\u0627\\u0644 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628\\u0629.\"}},{\"question\":{\"en\":\"How will I know when my case has been reviewed by the medical committee?\",\"ar\":\"\\u0643\\u064a\\u0641 \\u0633\\u0623\\u0639\\u0631\\u0641 \\u0623\\u0646 \\u0627\\u0644\\u0644\\u062c\\u0646\\u0629 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0642\\u062f \\u0631\\u0627\\u062c\\u0639\\u062a \\u062d\\u0627\\u0644\\u062a\\u064a\\u061f\"},\"answer\":{\"en\":\"Once the medical committee has reviewed your case, our team will contact you via WhatsApp or phone. Make sure your contact details are correct when registering.\",\"ar\":\"\\u0628\\u0645\\u062c\\u0631\\u062f \\u0623\\u0646 \\u062a\\u0642\\u0648\\u0645 \\u0627\\u0644\\u0644\\u062c\\u0646\\u0629 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0628\\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u062d\\u0627\\u0644\\u062a\\u0643\\u060c \\u0633\\u064a\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0643 \\u0641\\u0631\\u064a\\u0642\\u0646\\u0627 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0648\\u0627\\u062a\\u0633\\u0627\\u0628 \\u0623\\u0648 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641. \\u064a\\u064f\\u0631\\u062c\\u0649 \\u0627\\u0644\\u062a\\u0623\\u0643\\u062f \\u0645\\u0646 \\u0635\\u062d\\u0629 \\u0628\\u064a\\u0627\\u0646\\u0627\\u062a \\u0627\\u0644\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643 \\u0639\\u0646\\u062f \\u0627\\u0644\\u062a\\u0633\\u062c\\u064a\\u0644.\"}}]', '2026-02-04 17:17:20', '2026-02-09 17:51:53');
INSERT INTO `faq_sections` (`id`, `title`, `faqs`, `created_at`, `updated_at`) VALUES
(7, '{\"en\":\"ER and Referrals\",\"ar\":\"الطوارئ و التحويلات الطبية\"}', '[{\"question\":{\"en\":\" Do you accept referrals from other hospitals?\",\"ar\":\"\\u0647\\u0644 \\u062a\\u0642\\u0628\\u0644\\u0648\\u0646 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644\\u0627\\u062a \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u064a\\u0627\\u062a \\u0627\\u0644\\u0623\\u062e\\u0631\\u0649\\u061f\"},\"answer\":{\"en\":\" Yes\",\"ar\":\"\\u0646\\u0639\\u0645\"}},{\"question\":{\"en\":\" Does the hospital accept emergency cases?\",\"ar\":\"\\u0647\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u064a\\u0642\\u0628\\u0644 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u0637\\u0627\\u0631\\u0626\\u0629\\u061f\"},\"answer\":{\"en\":\"The hospital receives patients who have previously undergone procedures at Al Nas Hospital.\",\"ar\":\"\\u064a\\u0633\\u062a\\u0642\\u0628\\u0644 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0627\\u0644\\u062d\\u0627\\u0644\\u0627\\u062a \\u0627\\u0644\\u062a\\u064a \\u062e\\u0636\\u0639\\u062a \\u0645\\u0633\\u0628\\u0642\\u064b\\u0627 \\u0644\\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0637\\u0628\\u064a\\u0629 \\u0641\\u064a \\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0627\\u0644\\u0646\\u0627\\u0633.\"}},{\"question\":{\"en\":\"Does the hospital offer general medical services?\",\"ar\":\"\\u0647\\u0644 \\u064a\\u0642\\u062f\\u0645 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u062e\\u062f\\u0645\\u0627\\u062a \\u0637\\u0628\\u064a\\u0629 \\u0639\\u0627\\u0645\\u0629\\u061f\"},\"answer\":{\"en\":\"No. We are a specialized hospital for cardiothoracic, gastroenterology, diabetes, burn, and liver transplant services only.\",\"ar\":\"\\u0644\\u0627\\u060c \\u0646\\u062d\\u0646 \\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0645\\u062a\\u062e\\u0635\\u0635 \\u0641\\u0642\\u0637 \\u0641\\u064a \\u062e\\u062f\\u0645\\u0627\\u062a \\u0627\\u0644\\u0642\\u0644\\u0628 \\u0648\\u0627\\u0644\\u0635\\u062f\\u0631\\u060c \\u0648\\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 \\u0627\\u0644\\u0647\\u0636\\u0645\\u064a\\u060c \\u0648\\u0627\\u0644\\u0633\\u0643\\u0631\\u064a\\u060c \\u0648\\u0627\\u0644\\u062d\\u0631\\u0648\\u0642\\u060c \\u0648\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0643\\u0628\\u062f.\"}}]', '2026-02-04 17:17:20', '2026-02-09 17:55:09');
INSERT INTO `homepages` (`id`, `banner_pic`, `banner_toptitle`, `banner_title`, `banner_subtitle`, `banner_link`, `about_toptitle`, `about_title`, `about_content`, `about_counters`, `about_pic1`, `about_pic2`, `success_toptitle`, `success_title`, `success_content`, `impact_title`, `imapct_content`, `counters`, `impact_pic1`, `impact_pic2`, `team_tootitle`, `team_title`, `team_content`, `team_pic`, `vt_title`, `vt_pic`, `vt_content`, `location_title`, `location_pic`, `location_content`, `edu_title`, `edu_content`, `edu_pic`, `donate_cta_toptitle`, `donate_cta_title`, `donate_cta_subtitle`, `donate_cta_bg`, `donate_toptitle`, `donate_title`, `donate_content`, `patient_portal_url`, `created_at`, `updated_at`, `vt_link`, `location_link`, `visit_title`, `visit_pic`, `visit_content`, `visit_link`) VALUES
(1, NULL, '{\"en\":\"Welcome to al nas hospital\",\"ar\":\"مرحبًا بكم في مستشفى الناس\"}', '{\"en\":\"We\'re Always Close\",\"ar\":\"احنا مش بعيد\"}', '{\"en\":\"For every care in the world\",\"ar\":\"لأن كل رعاية تصنع فرقًا\"}', '#!', '{\"en\":\"al nas hospital\",\"ar\":\"مستشفى الناس\"}', '{\"en\":\"why we standout together\",\"ar\":\"ما الذي يميزنا معًا\"}', '{\"en\":\"<p>Al Nas Hospital is a nonprofit medical city located in the heart of Shubra El Kheima, one of the most densely populated areas in Qalyubia Governorate, just north of Cairo. Since its opening in September 2019, Al Nas has provided all its services free of charge.</p>\",\"ar\":\"<p>يُعد مستشفى الناس مدينة طبية غير هادفة للربح تقع في قلب شبرا الخيمة، إحدى أكثر المناطق كثافة سكانية في محافظة القليوبية شمال القاهرة. ومنذ افتتاحه في سبتمبر 2019، يلتزم المستشفى بتقديم جميع خدماته الطبية مجانًا، واضعًا جودة الرعاية وسلامة المرضى في مقدمة أولوياته، مع توفير أحدث التقنيات الطبية وأعلى معايير التميز في مختلف التخصصات.</p>\"}', '[{\"title\":{\"ar\":\"\\u0627\\u0644\\u0623\\u0633\\u0631\\u0629\",\"en\":\"Hospital Beds\"},\"number\":600},{\"title\":{\"ar\":\"\\u063a\\u0631\\u0641 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a\",\"en\":\"Operating Rooms\"},\"number\":10},{\"title\":{\"ar\":\"\\u0648\\u062d\\u062f\\u0627\\u062a \\u0627\\u0644\\u0631\\u0627\\u0639\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0643\\u0632\\u0629\",\"en\":\"Intensive Care Units\"},\"number\":140},{\"0\":{\"title\":\"title 1\",\"number\":123},\"1\":{\"title\":\"title 2\",\"number\":123},\"2\":{\"title\":\"title 3\",\"number\":123},\"title\":{\"ar\":\"\\u063a\\u0631\\u0641 \\u0627\\u0644\\u0642\\u0633\\u0637\\u0631\\u0629 \\u0627\\u0644\\u0642\\u0644\\u0628\\u064a\\u0629\",\"en\":\"Cardiac Catheterization Labs\"},\"number\":4},{\"title\":{\"en\":\"Outpatient Clinics\",\"ar\":\"\\u0627\\u0644\\u0639\\u064a\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u062e\\u0627\\u0631\\u062c\\u064a\\u0629\"},\"number\":48}]', NULL, NULL, '{\"en\":\"al nas hospital\",\"ar\":\"مستشفى الناس\"}', '{\"en\":\"Success stories\",\"ar\":\"قصص النجاح\"}', '{\"en\":\"<p>Every success story reflects expert care, advanced treatment, and a deep commitment to improving patients’ lives. These journeys highlight the dedication to delivering exceptional outcomes and giving patients a healthier future.</p>\",\"ar\":\"<p>تعكس كل قصة نجاح مستوى الرعاية المتقدمة والخبرة الطبية المتخصصة والالتزام المستمر بتحسين حياة المرضى. وتمثل هذه الرحلات الإنسانية دليلًا على التفاني في تحقيق أفضل النتائج ومنح المرضى فرصة لحياة صحية أفضل.</p>\"}', '{\"en\":\"Our Impact\",\"ar\":\"أثرنا\"}', '{\"en\":\"<p>Our results speak through every procedure performed and every life improved. We remain committed to excellence, transparency, and continuous advancement in patient care.</p>\",\"ar\":\"<p>تتجسد نتائجنا في كل إجراء طبي ناجح وكل مريض استعاد صحته. ونواصل التزامنا بالتميز والشفافية والتطوير المستمر لضمان أعلى مستويات الرعاية الصحية.</p>\"}', '[{\"title\":{\"ar\":\"\\u200f\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0642\\u0644\\u0628 \\u0645\\u0641\\u062a\\u0648\\u062d \\u0648 \\u0642\\u0633\\u0637\\u0631\\u0629 \\u0642\\u0644\\u0628\\u064a\\u0629\",\"en\":\"Heart Surgeries & Catheterization\"},\"number\":13793},{\"0\":{\"title\":\"tite 1\",\"number\":111},\"1\":{\"title\":\"tite 1\",\"number\":111},\"2\":{\"title\":\"tite 1\",\"number\":111},\"title\":{\"ar\":\"\\u200f\\u0643\\u0634\\u0641 \\u0628\\u0627\\u0644\\u0639\\u064a\\u0627\\u062f\\u0627\\u062a \\u0627\\u0644\\u062e\\u0627\\u0631\\u062c\\u064a\\u0629\",\"en\":\"Outpatient Clinic Visits\"},\"number\":93742},{\"title\":{\"en\":\"Gastrointestinal Surgeries & Endoscopies\",\"ar\":\"\\u200f\\u0639\\u0645\\u0644\\u064a\\u0629 \\u062c\\u0631\\u0627\\u062d\\u064a\\u0629 \\u0648\\u0645\\u0646\\u0627\\u0638\\u064a\\u0631 \\u062c\\u0647\\u0627\\u0632 \\u0647\\u0636\\u0645\\u064a\"},\"number\":4965},{\"title\":{\"en\":\"Diabetic Patients Managed\",\"ar\":\"\\u200f\\u0639\\u062f\\u062f \\u0645\\u0631\\u0636\\u0649 \\u0648\\u062d\\u062f\\u0629 \\u0627\\u0644\\u0633\\u0643\\u0631\"},\"number\":2443},{\"title\":{\"en\":\"Medical & Diagnostic Investigations\",\"ar\":\"\\u200f\\u0641\\u062d\\u0648\\u0635\\u0627\\u062a \\u0637\\u0628\\u064a\\u0629\"},\"number\":1427961},{\"title\":{\"en\":\"Burn Victims Treated\",\"ar\":\"\\u200f\\u0639\\u0644\\u0627\\u062c \\u062d\\u0627\\u0644\\u0627\\u062a \\u0641\\u064a \\u0648\\u062d\\u062f\\u0629 \\u0627\\u0644\\u062d\\u0631\\u0648\\u0642\"},\"number\":354}]', NULL, NULL, '{\"en\":\"Our Team\",\"ar\":\"فريقنا الطبي\"}', '{\"en\":\"Our Doctors\",\"ar\":\"أطباؤنا\"}', '{\"en\":\"<p>At Al Nas Hospital, our physicians and specialists are leaders in their fields, dedicated to providing advanced, compassionate, and evidence-based care. Our multidisciplinary teams work collaboratively to deliver the highest standards of treatment, innovation, and patient outcomes across all specialties.</p>\",\"ar\":\"<p>يضم مستشفى الناس نخبة من الأطباء والاستشاريين المتخصصين في مختلف المجالات الطبية، والذين يكرسون خبراتهم لتقديم رعاية متقدمة قائمة على أحدث الأدلة العلمية وبأعلى درجات التعاطف والاهتمام بالمريض. ويعمل فريقنا متعدد التخصصات بروح التعاون لضمان أفضل النتائج العلاجية وتعزيز جودة الرعاية في جميع التخصصات.</p>\"}', NULL, '{\"en\":\"Virtual Tour\",\"ar\":\"جولة افتراضية\"}', NULL, '{\"en\":\"<p>Through our virtual tour, you can explore our medical city, discover our facilities, and witness the spirit of compassionate care — all at your fingertips.</p>\",\"ar\":\"<p>من خلال جولتنا الافتراضية، يمكنك استكشاف مدينتنا الطبية، والتعرّف على مرافقنا، ومشاهدة روح الرعاية الرحيمة — كل ذلك بين يديك.</p>\"}', '{\"en\":\"Location\",\"ar\":\"الموقع\"}', NULL, '{\"en\":\"<p>Street 2, Shubra Al Kheimah, Shubra El Kheima 1, Al-Qalyubia Governorate</p>\",\"ar\":\"<p>ش ترعة الإسماعيلية- شرق كوبري أحمد حلمي، بجوار موقف الزهور- شبرا الخيمة، محافظة القليوبية.</p>\"}', '{\"en\":\"Education & Training\",\"ar\":\"التعليم والتدريب\"}', '{\"en\":\"<p>Education and training are central to Al Nas Hospital’s mission of advancing healthcare excellence. We provide continuous professional development, clinical training programs, and academic collaborations to ensure our medical teams remain at the forefront of innovation and evidence-based practice. Through structured education initiatives, we strengthen clinical expertise, enhance patient safety, and contribute to the future of specialized medical care.</p>\",\"ar\":\"<p>يُعد التعليم والتدريب ركيزة أساسية في رسالة مستشفى الناس لتعزيز التميز في الرعاية الصحية. ونوفر برامج تدريب سريرية مستمرة، وفرص تطوير مهني، وتعاونًا أكاديميًا لضمان بقاء كوادرنا الطبية في طليعة الابتكار والممارسة الطبية المبنية على الأدلة. ومن خلال هذه المبادرات، نعمل على تطوير الكفاءات الطبية، وتعزيز سلامة المرضى، والمساهمة في مستقبل الرعاية الصحية المتخصصة.</p>\"}', NULL, '{\"en\":\"al nas hospital\",\"ar\":\"مستشفى الناس\"}', '{\"en\":\"Your donation brings healing to every heart.\",\"ar\":\"تبرعك يمنح الأمل والشفاء لكل مريض\"}', '{\"en\":\"Join us in providing free, life-saving care to those who need it most.\",\"ar\":\"ساهم معنا في تقديم رعاية طبية مجانية ومنقذة للحياة لمن هم في أمسّ الحاجة إليها\"}', NULL, '{\"en\":\"Donate Now\",\"ar\":\"تبرع الآن\"}', '{\"en\":\"Donate for a case, equipment and supplies\",\"ar\":\"تبرع لحالة، أو جهاز طبي، أو مستلزمات علاجية\"}', '{\"en\":\"<p>Your support helps us provide advanced treatment, critical equipment, and life-saving care to patients in need. Together, we can continue transforming lives through specialized medical excellence.</p>\",\"ar\":\"<p>يساعد دعمكم في توفير أحدث العلاجات الطبية، والأجهزة الحيوية، والرعاية المنقذة للحياة للمرضى المحتاجين. معًا، نواصل إحداث فرق حقيقي وتحويل حياة المرضى من خلال التميز الطبي المتخصص.</p>\"}', 'https://hmis.alnaseg.dynv6.net/CMIS/4D-PatientPortal_Ver2/Home', '2025-12-24 09:07:02', '2026-02-15 18:42:17', NULL, 'https://share.google/MF4D1142UtWBRX7Sz', '{\"en\":\"Visits\",\"ar\":null}', NULL, '{\"en\":\"<p>A visit to Al Nas Hospital is a moment of hope and connection — where compassionate, free care meets a rich legacy of healing that continues to inspire lives today.</p>\",\"ar\":\"<p>زيارة مستشفى الناس هي لحظة أمل وتواصل إنساني — حيث تلتقي الرعاية المجانية الرحيمة بإرث عريق من الشفاء لا يزال يلهم الحياة حتى اليوم.</p>\"}', 'https://alnas.dawayer.work/visit');
