INSERT INTO `job_categories` (`id`, `title`, `content`, `toptitle`, `brief`, `created_at`, `updated_at`) VALUES
(1, '{\"en\":\"Administrative\",\"ar\":null}', '{\"en\":\"<p><strong>Behind every life we touch, there is a dedicated administrative team. We have opportunities in HR, Finance, Supply chain, Marketing, Engineering, Food and Beverage, Hospitality and more...</strong></p><p></p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"Careers\",\"ar\":null}', '{\"en\":\"Explore our career areas below and find where your skills can create real impact.\\n\",\"ar\":null}', '2026-02-04 17:24:06', '2026-02-12 18:07:55'),
(2, '{\"en\":\"Nursing\",\"ar\":\"التمريض\"}', '{\"en\":\"<p><strong>Nursing at Al Nas Hospital is a calling -- lifesaving care while growing your career in a supportive, mission-driven environment. Whatever area you specialize in, you will be a valued member of our patient care team</strong></p>\",\"ar\":\"<p><strong>التمريض في مستشفى الناس ليس مجرد وظيفة، بل دعوة — تقديم رعاية تنقذ الأرواح بينما تنمي مسارك المهني في بيئة داعمة وملتزمة بالرسالة. مهما كانت تخصصاتك، ستكون عضوًا قيمًا في فريق رعاية المرضى لدينا.</strong></p><p></p>\"}', '{\"en\":\"Careers\",\"ar\":\"الوظائف\"}', '{\"en\":\"Join our professional nursing team and make a difference in patient care.\",\"ar\":\"كن جزءًا من فريق التمريض المهني لدينا وقدم رعاية تحدث فرقًا حقيقيًا في حياة المرضى\"}', '2026-02-04 17:24:06', '2026-02-12 19:26:45'),
(4, '{\"en\":\"Medical \",\"ar\":\"القسم الطبي\"}', '{\"en\":\"<p><strong>Make a difference every day — Join a dynamic group of doctors, Consultants, specialists, and allied health professionals and deliver world-class care while growing your career.</strong></p>\",\"ar\":\"<p><strong>اصنع فرقًا كل يوم — انضم إلى فريقنا المتميز من الأطباء والاستشاريين والأخصائيين والمتخصصين في الرعاية الصحية وقدم رعاية عالمية المستوى بينما تطور مسارك المهني</strong></p><p></p>\"}', '{\"en\":\"Careers\",\"ar\":\"الوظائف\"}', '{\"en\":\"Join Our Growing Professional Medical Team – Where Expertise Meets Opportunity.\",\"ar\":\"كن جزءًا من فريقنا الطبي المتوسع – حيث تتحول خبرتك إلى فرص حقيقية للنمو والتطور\"}', '2026-02-04 17:24:06', '2026-02-12 19:29:25'),
(5, '{\"en\":\"Early Careers\",\"ar\":\"فرص للكوادر / حديثي التخرج\"}', '{\"en\":\"<p>Kickstart your healthcare journey with Al Nas Hospital’s Early Careers programs. We offer <strong>Internships</strong> for Administrative and Nursing students,<strong> Fellowships and Observer ships</strong> for medical students and early-career clinicians, offering mentorship, training, and exposure to real-world patient care.</p><p></p>\",\"ar\":\"<p><strong>ابدأ رحلتك في مجال الرعاية الصحية مع برامج &quot;بداية المسار المهني&quot; في مستشفى الناس. نقدم تدريبات للطلاب في الأقسام الإدارية والتمريضية، وزمالات وفرص متابعة للأطباء والطلاب الطبيين في بداية مسارهم المهني، مع توفير الإرشاد، والتدريب، والتعرض لتجارب حقيقية في رعاية المرضى</strong></p><p></p>\"}', '{\"en\":\"Careers\",\"ar\":\"الوظائف\"}', '{\"en\":\"Start Your Career with us\",\"ar\":\"ابدأ مسارك المهني معنا\"}', '2026-02-04 17:24:06', '2026-02-12 19:32:22');
INSERT INTO `job_posts` (`id`, `title`, `job_category_id`, `brief`, `about`, `description`, `requirement`, `created_at`, `updated_at`) VALUES
(1, '{\"en\":\"Senior Biomedical Engineer.\",\"ar\":null}', 1, '{\"en\":\"View Position.\",\"ar\":null}', '{\"en\":\"<p>The <strong>Senior Biomedical Engineer</strong> at Al-Nas Hospital plays a vital role in maintaining the safety, efficiency, and reliability of all medical equipment. This position ensures that clinical teams have fully functional, calibrated, and compliant equipment to deliver world-class patient care. The role involves hands-on technical work, preventive maintenance, troubleshooting, and collaboration with various departments to optimize equipment performance and support hospital operations.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<ul><li><p>Perform routine maintenance, calibration, and troubleshooting of medical equipment.</p></li><li><p>Respond promptly to equipment malfunctions and emergencies.</p></li><li><p>Install, configure, and test new medical equipment.</p></li><li><p>Develop and implement preventive maintenance programs.</p></li><li><p>Provide technical support and guidance to healthcare professionals.</p></li><li><p>Collaborate with other departments to ensure optimal equipment performance and compliance with safety standards.</p></li></ul>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<ul><li><p>Bachelor’s degree in Biomedical Engineering or a related field.</p></li><li><p>Minimum <strong>3-5 years</strong> of experience in biomedical engineering, preferably in a hospital setting.</p></li><li><p>Hands-on experience in <strong>Operating Rooms (OR)</strong> and <strong>Intensive Care Units (ICU)</strong>.</p></li><li><p>Proven practical experience in medical equipment maintenance and troubleshooting.</p></li><li><p>Strong <strong>problem-solving and analytical skills</strong>.</p></li><li><p>Excellent <strong>communication and interpersonal skills</strong>.</p></li><li><p>Ability to work in a fast-paced, multidisciplinary healthcare environment.</p></li></ul>\",\"ar\":\"<p></p>\"}', '2026-02-04 17:27:47', '2026-02-12 19:44:10'),
(2, '{\"en\":\"Staff Nurse - Burn Unit\",\"ar\":\" -  Copy\"}', 2, '{\"en\":\"Join our team as a Staff nurse and help make a difference in patient care\",\"ar\":null}', '{\"en\":\"<p>The <strong>Burn Unit Staff Nurse</strong> at Al-Nas Hospital provides specialized nursing care to patients with burn injuries. You will play a critical role in delivering high-quality, compassionate care while supporting the recovery and rehabilitation of patients. This role involves hands-on patient care, monitoring, treatment administration, and collaboration with the multidisciplinary burn care team.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<ul><li><p>Provide comprehensive nursing care to burn patients, including wound care, pain management, and rehabilitation support.</p></li><li><p>Monitor patient conditions, document progress, and report changes to the care team.</p></li><li><p>Assist with medical procedures and treatments in collaboration with doctors and specialists.</p></li><li><p>Educate patients and families on burn care and recovery.</p></li><li><p>Ensure infection control and patient safety protocols are strictly followed.</p></li><li><p>Participate in continuous professional development and training programs.</p></li></ul>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<ul><li><p>Bachelor’s degree in nursing (BSc) or equivalent.</p></li><li><p>Valid nursing license.</p></li><li><p>Minimum <strong>2 years of experience</strong> in burn care or critical care preferred.</p></li><li><p>Strong clinical skills and knowledge of burn treatment protocols.</p></li><li><p>Ability to work in a fast-paced, high-stress environment.</p></li><li><p>Excellent communication, teamwork, and patient care skills.</p></li><li><p>Compassionate and dedicated to patient recovery.</p></li></ul>\",\"ar\":\"<p></p>\"}', '2026-02-04 17:27:47', '2026-02-12 20:00:47'),
(4, '{\"en\":\"Anesthesia Specialist\",\"ar\":\" -  Copy -  Copy\"}', 4, '{\"en\":\"Al Nas Hospital, one of Egypt’s leading non-profit hospitals, is expanding its operations team and is pleased to announce openings for Anesthesia Specialists to join our growing medical team.\",\"ar\":null}', '{\"en\":\"<p>As an Anesthesia Specialist at Al Nas Hospital, you will play a critical role in ensuring patient safety and comfort during surgical procedures. You will assess patients, administer anesthesia, and monitor recovery while collaborating closely with surgical and nursing teams to achieve optimal outcomes.</p>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<ul><li><p>Assess patients’ medical conditions prior to anesthesia and determine the appropriate anesthetic plan for each case.</p></li><li><p>Administer all types of anesthesia, including general, regional/spinal, local, and pain management, according to case requirements.</p></li><li><p>Supervise patients in the recovery room and follow up until full stabilization.</p></li><li><p>Fully comply with infection control policies and patient safety standards.</p></li><li><p>Accurately document all medical and anesthetic procedures in the patient’s medical record.</p></li><li><p>Collaborate with surgical and nursing teams to ensure the best therapeutic outcomes.</p></li></ul>\",\"ar\":\"<p></p>\"}', '{\"en\":\"<ul><li><p>Bachelor’s degree in Medicine and Surgery.</p></li><li><p>Specialized qualification in Anesthesiology (Master’s degree or Fellowship).</p></li><li><p>Prior experience in reputable hospitals.</p></li><li><p>Valid medical practice license.</p></li><li><p>Strong clinical skills, attention to detail, and ability to work in a fast-paced surgical environment.</p></li></ul>\",\"ar\":\"<p></p>\"}', '2026-02-04 17:27:47', '2026-02-12 19:59:31');
