INSERT INTO `research_pages` (`id`, `about_title`, `about_slides`, `about_vision_title`, `about_vision_icon`, `about_vision_content`, `about_vision_pic`, `about_mission_title`, `about_mission_icon`, `about_mission_content`, `about_mission_pic`, `objs`, `studies_title`, `studies`, `crc_title`, `crc_pic`, `crc_content`, `crc_members`, `irb_title`, `irb_pic`, `irb_content`, `irb_members`, `sci_title`, `sci_pic`, `sci_content`, `sci_members`, `chart_id`, `created_at`, `updated_at`) VALUES
(1, '{\"ar\":\"من نحن \",\"en\":\"Pioneering the Future of Medicine with Al Nas Research\"}', '[{\"title\":{\"en\":\"Troponin I Predicting Outcomes in post cardiac surgery Pediatric Patients.\",\"ar\":\"111 ar\"},\"year\":\"2022\",\"link\":\"alnas-hosptial.com\",\"uuid\":null},{\"title\":{\"en\":\"Troponin I Predicting Outcomes in post cardiac surgery Pediatric Patients.\",\"ar\":\"111 ar\"},\"year\":\"2022\",\"link\":\"alnas-hosptial.com\",\"uuid\":null},{\"title\":{\"en\":\"Troponin I Predicting Outcomes in post cardiac surgery Pediatric Patients.\",\"ar\":\"111 ar\"},\"year\":\"2022\",\"link\":\"alnas-hosptial.com\",\"uuid\":null},{\"title\":{\"en\":\"Troponin I Predicting Outcomes in post cardiac surgery Pediatric Patients.\",\"ar\":\"111 ar\"},\"year\":\"2022\",\"link\":\"alnas-hosptial.com\",\"uuid\":null}]', '{\"en\":\"Vision\",\"ar\":null}', NULL, '{\"en\":\"<p style=\\\"text-align: justify;\\\">To become a leading and internationally recognized center of excellence in clinical research, leveraging research collaboration and the power of Artificial Intelligence to improve treatment outcomes and overall health across Egypt and the broader regional population.<br></p>\",\"ar\":\"<p></p>\"}', NULL, '{\"en\":\"Mission\",\"ar\":null}', NULL, '{\"en\":\"<p>To address our community healthcare challenges, bridge the research gaps in clinical practice, and investigate innovative preventive and therapeutic strategies through high-quality research.</p><p style=\\\"text-align: justify;\\\">To reinforce the hospital’s commitment to deliver the highest standards of patient care.</p>\",\"ar\":\"<p></p>\"}', NULL, '[{\"uuid\":\"790b06ee-c525-4e53-89e5-cbd6bb776364\",\"title\":{\"en\":\"Advancing Breakthrough Techniques\",\"ar\":null}},{\"uuid\":\"1e190929-21f4-4a8b-9392-6a72e47dd4d7\",\"title\":{\"en\":\" Leading New Procedures with Limited Regional & Global Data\",\"ar\":null}},{\"uuid\":\"fde04910-1bd5-4a49-b733-4380120a7a31\",\"title\":{\"en\":\"Novel Research in the Egyptian Population\",\"ar\":null}},{\"uuid\":\"c2fde144-53f8-4a67-82b2-28351e2e5bb8\",\"title\":{\"en\":\"Awareness and Preventive Research\",\"ar\":null}},{\"uuid\":\"df04270a-fda7-4105-9d2a-7fb760a47591\",\"title\":{\"en\":\"Scientific Global Impact and Bridging Research Gaps\",\"ar\":null}}]', '{\"en\":\"Ongoing IRB Approved Research Studies\",\"ar\":null}', '[{\"title\":{\"en\":\"Ongoing Studies per Year\",\"ar\":\"4\"},\"embed\":\"<div id=\\\"pup_chart-3d\\\" class=\\\"height-400px\\\"><\\/div>\",\"chart_id\":2},{\"title\":{\"en\":\"Ongoing Studies per Year Per Department\",\"ar\":null},\"embed\":\"<div id=\\\"irb_dept_year_chart_3d\\\" class=\\\"height-400px width-500px\\\"><\\/div>\",\"chart_id\":3}]', '{\"en\":\"Al Nas CRC Board\",\"ar\":null}', NULL, '{\"en\":\"<p>To become a leading center of excellence in clinical research, pioneering studies that enhance treatment outcomes, reduce hospital stays, and improve overall health in Egypt and the broader regional community.</p>\",\"ar\":\"<p></p>\"}', '[11]', '{\"en\":\"Al Nas Institution Review Board (IRB) Members\",\"ar\":null}', NULL, '{\"en\":\"<ul><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Magdy Gomaa (Chairman)</p></li><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Hala Agha (Vice Chairman)</p></li><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Magdy Abdelhamid</p></li><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Mohamed Hassan</p></li><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Abeer Awad</p></li><li><p style=\\\"text-align: justify;\\\">Prof Dr. Amal Fathy Mohammad Radwan</p></li><li><p style=\\\"text-align: justify;\\\">Dr. Hany Seleem</p></li><li><p style=\\\"text-align: justify;\\\">Dr.Osama Abdelaziz</p></li><li><p style=\\\"text-align: justify;\\\">Dr. Yasmin Elsobky</p></li><li><p style=\\\"text-align: justify;\\\">Mr Ahmed Torky</p></li><li><p style=\\\"text-align: justify;\\\">Mr. Yasser Mohamed</p></li></ul>\",\"ar\":\"<p></p>\"}', '[5,11,45,35]', '{\"en\":\"Al Nas Scientific Research Committee \",\"ar\":null}', NULL, '{\"en\":\"<ul><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Mohamed Hassan (Committee Chairman)</p></li><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Ahmed Adel</p></li><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Mohamed Elmaghawry</p></li><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Rodyna Sobhy</p></li><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Abeer Awad</p></li><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Yasser Ahmed Salem</p></li><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Ahmad Hasseb</p></li><li><p style=\\\"text-align: justify;\\\">Prof. Dr. Amal Rizk</p></li><li><p style=\\\"text-align: justify;\\\">Dr. Yasmin Elsobky</p></li></ul>\",\"ar\":\"<p></p>\"}', '[5,11,55,15]', 3, '2025-12-26 09:45:19', '2026-02-14 11:05:30');
