INSERT INTO `success_stories` (`id`, `title`, `pic`, `brief`, `content`, `created_at`, `updated_at`, `order_column`) VALUES
(2, '{\"en\":\"Omar Mahmoud\",\"ar\":null}', NULL, '{\"en\":\"Omar received the surgery that gave him a new chance at life.\",\"ar\":null}', '{\"en\":\"<p>Omar received the surgery that gave him a new chance at life.</p>\",\"ar\":\"<p></p>\"}', '2025-12-29 21:20:25', '2026-01-07 01:12:42', NULL),
(3, '{\"ar\":\" -  Copy\",\"en\":\"Sara Ahmed\"}', NULL, '{\"en\":\"Sara’s journey to recovery brought hope and relief to her father, and their whole family.\",\"ar\":null}', '{\"en\":\"<p>Sara’s journey to recovery brought hope and relief to her father, and their whole family.</p>\",\"ar\":\"<p></p>\"}', '2025-12-29 21:20:25', '2026-01-07 01:14:10', NULL),
(4, '{\"ar\":\" -  Copy -  Copy\",\"en\":\"Youssef Hassan\"}', NULL, '{\"en\":\"After months of care, Youssef is now healthy, active, and full of life again.\",\"ar\":null}', '{\"en\":\"<p>After months of care, Youssef is now healthy, active, and full of life again.</p>\",\"ar\":\"<p></p>\"}', '2025-12-29 21:20:25', '2026-01-07 01:14:48', NULL);
