INSERT INTO `visit_pages` (`id`, `toptitle`, `title`, `content`, `boxes`, `icons`, `info`, `form_toptitle`, `form_title`, `form_content`, `created_at`, `updated_at`) VALUES
(1, '{\"en\":\"Take A Tour\",\"ar\":\"استمتع بجولة\"}', '{\"en\":\"Be Part of the Healing Journey\",\"ar\":\"كونوا جزءًا من رحلة الشفاء\"}', '{\"en\":\"<p></p>\",\"ar\":\"<p></p>\"}', '[{\"uuid\":\"3341d20a-dfa9-44bc-94f3-c2e6a4fd8345\",\"title\":{\"en\":\"Step Inside Our Care\",\"ar\":\"\\u062e\\u0637\\u0648\\u0629 \\u062f\\u0627\\u062e\\u0644 \\u0631\\u0639\\u0627\\u064a\\u062a\\u0646\\u0627\"},\"content\":{\"en\":\"A visit to Al Nas Hospital is more than a tour, it\\u2019s a moment of human connection. By spending time with our patients, you help spread hope, comfort, and joy during their healing journey. Your visit also offers a closer look at our medical city, the free care we proudly provide, and meaningful opportunities to collaborate for greater impact.\",\"ar\":\"\\u0632\\u064a\\u0627\\u0631\\u0629 \\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0644\\u064a\\u0633\\u062a \\u0645\\u062c\\u0631\\u062f \\u062c\\u0648\\u0644\\u0629\\u060c \\u0628\\u0644 \\u0647\\u064a \\u0644\\u062d\\u0638\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0627\\u0646\\u064a. \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0642\\u0636\\u0627\\u0626\\u0643\\u0645 \\u0648\\u0642\\u062a\\u064b\\u0627 \\u0645\\u0639 \\u0645\\u0631\\u0636\\u0627\\u0646\\u0627\\u060c \\u062a\\u0633\\u0627\\u0639\\u062f\\u0648\\u0646 \\u0641\\u064a \\u0646\\u0634\\u0631 \\u0627\\u0644\\u0623\\u0645\\u0644 \\u0648\\u0627\\u0644\\u0631\\u0627\\u062d\\u0629 \\u0648\\u0627\\u0644\\u0641\\u0631\\u062d \\u062e\\u0644\\u0627\\u0644 \\u0631\\u062d\\u0644\\u0629 \\u0634\\u0641\\u0627\\u0626\\u0647\\u0645. \\u0643\\u0645\\u0627 \\u062a\\u0645\\u0646\\u062d \\u0632\\u064a\\u0627\\u0631\\u062a\\u0643\\u0645 \\u0641\\u0631\\u0635\\u0629 \\u0644\\u0644\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0646 \\u0642\\u0631\\u0628 \\u0639\\u0644\\u0649 \\u0645\\u062f\\u064a\\u0646\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649\\u060c \\u0648\\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062c\\u0627\\u0646\\u064a\\u0629 \\u0627\\u0644\\u062a\\u064a \\u0646\\u0642\\u062f\\u0645\\u0647\\u0627 \\u0628\\u0641\\u062e\\u0631\\u060c \\u0648\\u0641\\u0631\\u0635 \\u0627\\u0644\\u062a\\u0639\\u0627\\u0648\\u0646 \\u0627\\u0644\\u0647\\u0627\\u062f\\u0641\\u0629 \\u0644\\u062a\\u062d\\u0642\\u064a\\u0642 \\u062a\\u0623\\u062b\\u064a\\u0631 \\u0623\\u0643\\u0628\\u0631.\"},\"link\":{\"en\":\"#form-section\",\"ar\":null}},{\"uuid\":\"88b05862-fb18-474b-a030-b66e8841e1cf\",\"title\":{\"en\":\"AL Nas Gallery of Egyptian Medical History\",\"ar\":\"\\u0645\\u0639\\u0631\\u0636 \\u0645\\u0633\\u062a\\u0634\\u0641\\u0649 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0644\\u062a\\u0627\\u0631\\u064a\\u062e \\u0627\\u0644\\u0637\\u0628 \\u0641\\u064a \\u0645\\u0635\\u0631\"},\"content\":{\"en\":\"Explore 5,000 years of medicine and healing in Egypt through an inspiring journey. The gallery highlights the evolution of healthcare from ancient Egyptian practices to modern medicine, showcasing key milestones, early healing traditions, medical advances, and the compassionate care that continues to shape healthcare today.\",\"ar\":\"\\u0627\\u0633\\u062a\\u0643\\u0634\\u0641\\u0648\\u0627 5000 \\u0633\\u0646\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0637\\u0628 \\u0648\\u0627\\u0644\\u0634\\u0641\\u0627\\u0621 \\u0641\\u064a \\u0645\\u0635\\u0631 \\u0639\\u0628\\u0631 \\u0631\\u062d\\u0644\\u0629 \\u0645\\u0644\\u0647\\u0645\\u0629. \\u064a\\u0633\\u0644\\u0637 \\u0627\\u0644\\u0645\\u0639\\u0631\\u0636 \\u0627\\u0644\\u0636\\u0648\\u0621 \\u0639\\u0644\\u0649 \\u062a\\u0637\\u0648\\u0631 \\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0635\\u062d\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0645\\u0627\\u0631\\u0633\\u0627\\u062a \\u0627\\u0644\\u0645\\u0635\\u0631\\u064a\\u0629 \\u0627\\u0644\\u0642\\u062f\\u064a\\u0645\\u0629 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0637\\u0628 \\u0627\\u0644\\u062d\\u062f\\u064a\\u062b\\u060c \\u0645\\u0639 \\u0625\\u0628\\u0631\\u0627\\u0632 \\u0627\\u0644\\u0625\\u0646\\u062c\\u0627\\u0632\\u0627\\u062a \\u0627\\u0644\\u0631\\u0626\\u064a\\u0633\\u064a\\u0629\\u060c \\u0648\\u0627\\u0644\\u062a\\u0642\\u0627\\u0644\\u064a\\u062f \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0628\\u0643\\u0631\\u0629\\u060c \\u0648\\u0627\\u0644\\u062a\\u0642\\u062f\\u0645\\u0627\\u062a \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629\\u060c \\u0648\\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0625\\u0646\\u0633\\u0627\\u0646\\u064a\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0633\\u062a\\u0645\\u0631 \\u0641\\u064a \\u062a\\u0634\\u0643\\u064a\\u0644 \\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0635\\u062d\\u064a\\u0629 \\u062d\\u062a\\u0649 \\u0627\\u0644\\u064a\\u0648\\u0645.\"},\"link\":{\"en\":\"https:\\/\\/al-nas-events.vercel.app\\/\",\"ar\":null}}]', '[{\"uuid\":\"e5aaf4d3-8501-468f-994b-a4eb6cb62227\",\"title\":{\"en\":\"Virtual Tour\",\"ar\":\"\\u062c\\u0648\\u0644\\u0629 \\u0627\\u0641\\u062a\\u0631\\u0627\\u0636\\u064a\\u0629\"},\"content\":{\"en\":\"Plan your visit and experience our care firsthand.\",\"ar\":\"\\u0631\\u062a\\u0628 \\u0644\\u0632\\u064a\\u0627\\u0631\\u062a\\u0643 \\u0648\\u0627\\u062e\\u062a\\u0628\\u0631 \\u0631\\u0639\\u0627\\u064a\\u062a\\u0646\\u0627 \\u0628\\u0646\\u0641\\u0633\\u0643\"}},{\"uuid\":\"7d8d94dc-8a40-4f6d-b770-dc2e8eb49bab\",\"title\":{\"en\":\"Location\",\"ar\":\"\\u0627\\u0644\\u0645\\u0648\\u0642\\u0639\"},\"content\":{\"en\":\"Discover our exact location.\",\"ar\":\"\\u0627\\u0643\\u062a\\u0634\\u0641\\u0648\\u0627 \\u0645\\u0648\\u0642\\u0639\\u0646\\u0627 \\u0628\\u062f\\u0642\\u0629.\"}},{\"uuid\":\"ceb456c1-1b03-4f0c-bcad-1fa8e55230b4\",\"title\":{\"en\":\" Donate Now\",\"ar\":\"\\u0627\\u062a\\u0628\\u0631\\u0639 \\u0627\\u0644\\u0622\\u0646\"},\"content\":{\"en\":\"Every donation supports advanced treatment, critical equipment, and better outcomes for patients in need.\",\"ar\":\"\\u0643\\u0644 \\u062a\\u0628\\u0631\\u0639 \\u064a\\u0633\\u0627\\u0647\\u0645 \\u0641\\u064a \\u062a\\u0648\\u0641\\u064a\\u0631 \\u0639\\u0644\\u0627\\u062c \\u0645\\u062a\\u0642\\u062f\\u0645\\u060c \\u0648\\u062a\\u062c\\u0647\\u064a\\u0632\\u0627\\u062a \\u0637\\u0628\\u064a\\u0629 \\u062d\\u064a\\u0648\\u064a\\u0629\\u060c \\u0648\\u062a\\u062d\\u0642\\u064a\\u0642 \\u0646\\u062a\\u0627\\u0626\\u062c \\u0623\\u0641\\u0636\\u0644 \\u0644\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u0645\\u062d\\u062a\\u0627\\u062c\\u064a\\u0646.\"}}]', '[{\"uuid\":\"3048b38b-d944-4abe-9980-b916dbcdf921\",\"title\":{\"ar\":\"\\u0627\\u0644\\u062d\\u062c\\u0632\",\"en\":\"Book\"},\"content\":{\"ar\":\"<ul><li><p>\\u064a\\u0631\\u062c\\u0649 \\u062d\\u062c\\u0632 \\u0632\\u064a\\u0627\\u0631\\u062a\\u0643\\u0645 \\u0645\\u0633\\u0628\\u0642\\u064b\\u0627 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0637\\u0631\\u0642 \\u0627\\u0644\\u062d\\u062c\\u0632 \\u0627\\u0644\\u0628\\u0633\\u064a\\u0637\\u0629 \\u0644\\u062f\\u064a\\u0646\\u0627.<\\/p><\\/li><li><p>\\u064a\\u0633\\u0631\\u0646\\u0627 \\u0627\\u0633\\u062a\\u0642\\u0628\\u0627\\u0644 \\u0627\\u0644\\u0632\\u0648\\u0627\\u0631 \\u0637\\u0648\\u0627\\u0644 \\u0627\\u0644\\u0623\\u0633\\u0628\\u0648\\u0639! \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0623\\u0641\\u0636\\u0644 \\u062a\\u062c\\u0631\\u0628\\u0629\\u060c \\u064a\\u064f\\u0641\\u0636\\u0644 \\u0627\\u0644\\u062d\\u0636\\u0648\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u062d\\u062f \\u0625\\u0644\\u0649 \\u0627\\u0644\\u062e\\u0645\\u064a\\u0633\\u060c \\u062d\\u064a\\u062b \\u064a\\u062a\\u0648\\u0627\\u062c\\u062f \\u0639\\u062f\\u062f \\u0623\\u0643\\u0628\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644.<\\/p><\\/li><li><p>\\u064a\\u062a\\u0645 \\u062a\\u0631\\u062a\\u064a\\u0628 \\u0639\\u062f\\u062f \\u0627\\u0644\\u0632\\u0648\\u0627\\u0631 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0647\\u0627\\u062a\\u0641\\u060c \\u0648\\u0641\\u0642\\u064b\\u0627 \\u0644\\u062a\\u0648\\u062c\\u064a\\u0647\\u0627\\u062a \\u0641\\u0631\\u064a\\u0642\\u0646\\u0627 \\u0627\\u0644\\u0637\\u0628\\u064a.<br><\\/p><\\/li><\\/ul>\",\"en\":\"<ul><li><p>Please book your visit in advance using our simple booking methods.<\\/p><\\/li><li><p>We\\u2019re delighted to welcome visitors all week! For the best experience, Sunday to Thursday is ideal, when more children are present.<\\/p><\\/li><li><p>The number of visitors is arranged by phone, following the guidance of our medical team.<\\/p><\\/li><\\/ul>\"}},{\"uuid\":\"af3601ee-7b87-4862-941c-dbef5f495436\",\"title\":{\"ar\":\"\\u062f\\u0644\\u064a\\u0644 \\u0627\\u0644\\u0632\\u064a\\u0627\\u0631\\u0629\",\"en\":\"Guide\"},\"content\":{\"ar\":\"<ul><li><p>\\u064a\\u062c\\u0628 \\u0623\\u0646 \\u062a\\u0643\\u0648\\u0646 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0647\\u062f\\u0627\\u064a\\u0627 \\u0627\\u0644\\u0645\\u0642\\u062f\\u0645\\u0629 \\u0645\\u0646\\u0627\\u0633\\u0628\\u0629 \\u0644\\u0644\\u0623\\u0637\\u0641\\u0627\\u0644.<\\/p><\\/li><li><p>\\u064a\\u0642\\u062a\\u0635\\u0631 \\u0639\\u062f\\u062f \\u0627\\u0644\\u0632\\u0648\\u0627\\u0631 \\u0639\\u0644\\u0649 25 \\u0634\\u062e\\u0635\\u064b\\u0627 \\u0643\\u062d\\u062f \\u0623\\u0642\\u0635\\u0649 \\u0644\\u0643\\u0644 \\u0645\\u062c\\u0645\\u0648\\u0639\\u0629.<\\/p><\\/li><li><p>\\u0627\\u0644\\u062a\\u0635\\u0648\\u064a\\u0631 \\u063a\\u064a\\u0631 \\u0645\\u0633\\u0645\\u0648\\u062d \\u0628\\u0647 \\u0625\\u0644\\u0627 \\u0628\\u0639\\u062f \\u0645\\u0648\\u0627\\u0641\\u0642\\u0629 \\u0627\\u0644\\u0641\\u0631\\u064a\\u0642 \\u0648\\u062a\\u0648\\u062c\\u064a\\u0647\\u0647.<\\/p><\\/li><li><p>\\u064a\\u0645\\u0646\\u0639 \\u0625\\u062f\\u062e\\u0627\\u0644 \\u0627\\u0644\\u0637\\u0639\\u0627\\u0645 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u0645\\u0633\\u062a\\u0634\\u0641\\u0649.<\\/p><\\/li><li><p>\\u064a\\u062c\\u0628 \\u062a\\u0646\\u0633\\u064a\\u0642 \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0632\\u064a\\u0627\\u0631\\u0627\\u062a \\u0648\\u0627\\u0644\\u0623\\u0646\\u0634\\u0637\\u0629 \\u0645\\u0633\\u0628\\u0642\\u064b\\u0627 \\u0645\\u0639 \\u0642\\u0633\\u0645 \\u0627\\u0644\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0648\\u0627\\u0644\\u0639\\u0644\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0639\\u0627\\u0645\\u0629.<\\/p><\\/li><\\/ul>\",\"en\":\"<ul><li><p>All gifts brought to the hospital must be suitable for children.<\\/p><\\/li><li><p>Groups are limited to a maximum of 25 visitors at a time.<\\/p><\\/li><li><p>Photography is not allowed unless approved and guided by our team.<\\/p><\\/li><li><p>Bringing food into the hospital is not permitted.<\\/p><\\/li><li><p>All visits and activities must be coordinated in advance with the Communication &amp; PR Department.<\\/p><\\/li><\\/ul>\"}}]', '{\"en\":\"Visit us\",\"ar\":\"زورونا\"}', '{\"en\":\"Book Your Visit\",\"ar\":\"احجز زيارتك\"}', '{\"en\":\"<p>All visits are thoughtfully arranged in advance, and our team will be happy to contact you to coordinate the details ensuring a safe, welcoming, and smoothly organized experience for everyone.</p>\",\"ar\":\"<p>يتم ترتيب جميع الزيارات بعناية مسبقًا، وسيسعد فريقنا بالتواصل معكم لتنسيق التفاصيل وضمان تجربة آمنة، مرحبة، ومنظمة بسلاسة للجميع.</p>\"}', '2026-02-10 03:54:15', '2026-02-15 18:51:18');
